INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12336ab5-cca7-444d-a3e3-3c6e4d81aca3', '嘉陵江', '嘉陵江', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["嘉陵南岸雨初收，江似秋嵐不煞流。","此地終朝有行客，無人一爲櫂扁舟。"]', '["嘉陵南岸雨初收，江似秋嵐不煞流。","此地終朝有行客，無人一爲櫂扁舟。"]', '诗', 'shi', '', NULL, '嘉陵江 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aefd553-d1e5-447c-91bd-f6feedb603ec', '早行', '早行', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["雨灑江聲風又吹，扁舟正與睡相宜。","無端戍鼓催前去，別却青山向曉時。"]', '["雨灑江声风又吹，扁舟正與睡相宜。","無端戍鼓催前去，別却青山向晓时。"]', '诗', 'shi', '', NULL, '早行 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cccc1b-944b-4889-a93d-cfc9788b8837', '黃河曉渡', '黄河晓渡', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["大河平野正窮秋，羸馬羸僮古渡頭。","昨夜蓮花峰下月，隔簾相伴到明愁。"]', '["大河平野正窮秋，羸马羸僮古渡头。","昨夜蓮花峰下月，隔簾相伴到明愁。"]', '诗', 'shi', '', NULL, '黃河曉渡 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a0282a-9aec-4ea1-94cd-63497649c1d8', '溫泉', '溫泉', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一條春水漱莓苔，幾繞玄宗浴殿回。","此水貴妃曾照影，不堪流入舊宮來。"]', '["一條春水漱莓苔，幾繞玄宗浴殿回。","此水貴妃曾照影，不堪流入旧宮来。"]', '诗', 'shi', '', NULL, '溫泉 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7033e7-70ad-449c-8ae8-40ea460f2604', '秋怨', '秋怨', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["夢斷南窗啼曉烏，新霜昨夜下庭梧。","不知簾外如珪月，還照邊城到曉無。"]', '["梦斷南窗啼晓烏，新霜昨夜下庭梧。","不知簾外如珪月，還照邊城到晓無。"]', '诗', 'shi', '', NULL, '秋怨 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf4b0a9-6704-4d07-90c8-9aea0b97ded8', '歎別', '歎別', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["北來南去幾時休，人在光陰似箭流。","直待江山盡無路，始因拋得別離愁。"]', '["北来南去幾时休，人在光陰似箭流。","直待江山尽無路，始因拋得別離愁。"]', '诗', 'shi', '', NULL, '歎別 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea41905-a68a-40c4-bd07-97a70c0342e3', '送春', '送春', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["欲別東風剩黯然，亦知春去有明年。","世間爭那人先老，更對殘花一醉眠。"]', '["欲別东风剩黯然，亦知春去有明年。","世间爭那人先老，更对殘花一醉眠。"]', '诗', 'shi', '', NULL, '送春 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38b46c3-47b3-4530-ac4a-14e13252180c', '蠟燭', '蠟燭', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["煖香紅焰一時燃，緹幕初垂月落天。","堪恨蘭堂別離夜，如珠似淚滴樽前。"]', '["煖香紅焰一时燃，緹幕初垂月落天。","堪恨蘭堂別離夜，如珠似泪滴樽前。"]', '诗', 'shi', '', NULL, '蠟燭 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cdc714c-bb13-4ea2-a894-cfcf3915d801', '陳宮', '陳宮', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["白玉尊前紫桂香，迎春閣上燕雙雙。","陳王半醉貴妃舞，不覺隋兵夜渡江。"]', '["白玉尊前紫桂香，迎春閣上燕雙雙。","陳王半醉貴妃舞，不覺隋兵夜渡江。"]', '诗', 'shi', '', NULL, '陳宮 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52f4a69-8d07-4cfd-a112-85221c647b82', '水簾', '水簾', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["萬點飛泉下白雲，似簾懸處望疑真。","若將此水爲霖雨，更勝長垂隔路塵。"]', '["万点飞泉下白云，似簾懸处望疑真。","若將此水爲霖雨，更勝长垂隔路塵。"]', '诗', 'shi', '', NULL, '水簾 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039fc803-bc22-4f29-9df2-716ca15339b5', '賞春', '賞春', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["芳草和煙暖更青，閑門要路一時生。","年年點檢人間事，唯有春風不世情。"]', '["芳草和煙暖更青，闲门要路一时生。","年年点檢人间事，唯有春风不世情。"]', '诗', 'shi', '', NULL, '賞春 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd0a0ea5-7bd0-4563-b3f8-f65055b175ac', '歎平泉', '歎平泉', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["生前幾到此亭臺，尋歎投荒去不回。","若遣春風會人意，花枝盡合向南開。"]', '["生前幾到此亭台，尋歎投荒去不回。","若遣春风會人意，花枝尽合向南开。"]', '诗', 'shi', '', NULL, '歎平泉 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727fc328-af80-49b6-80be-5bdd43ce0022', '長安春雨', '长安春雨', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["兼風颯颯灑皇洲，能滯輕寒阻勝遊。","半夜五侯池館裏，美人驚起爲花愁。"]', '["兼风颯颯灑皇洲，能滯轻寒阻勝游。","半夜五侯池館裏，美人驚起爲花愁。"]', '诗', 'shi', '', NULL, '長安春雨 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b438d5cf-245c-4c69-bb24-55a4329fb033', '駕蜀回', '駕蜀回', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["上皇西幸却歸秦，花木依然滿禁春。","唯有貴妃歌舞地，月明空殿鎖香塵。"]', '["上皇西幸却归秦，花木依然满禁春。","唯有貴妃歌舞地，月明空殿鎖香塵。"]', '诗', 'shi', '', NULL, '駕蜀回 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b66aed-4942-4982-9ed6-4cd2e9829f26', '吳王古宮井二首 一', '吳王古宮井二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["古宮荒井曾平後，見說耕人又鑿開。","拾得玉衩鐫勅字，當時恩澤賜誰來。"]', '["古宮荒井曾平後，见说耕人又鑿开。","拾得玉衩鐫勅字，當时恩澤賜誰来。"]', '诗', 'shi', '', NULL, '吳王古宮井二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a025954-025b-4537-995a-7ed68f4eb807', '吳王古宮井二首 二', '吳王古宮井二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["含青薜荔隨金甃，碧砌磷磷生綠苔。","莫言數尺無波水，曾與如花竝照來。"]', '["含青薜荔隨金甃，碧砌磷磷生綠苔。","莫言數尺無波水，曾與如花竝照来。"]', '诗', 'shi', '', NULL, '吳王古宮井二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9b0e8d-0e7c-4bdb-8f8b-72f3b664fc7f', '江帆', '江帆', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["別離不獨恨蹄輪，渡口風帆發更頻。","何處青樓方凭檻，半江斜日認歸人。"]', '["別離不独恨蹄輪，渡口风帆發更頻。","何处青楼方凭檻，半江斜日認归人。"]', '诗', 'shi', '', NULL, '江帆 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e08109-4137-4309-9a4b-87f12efc7655', '爲人感贈', '爲人感贈', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["歌舞從來最得名，如今老寄洛陽城。","當時醉送龍驤曲，留與誰家唱月明。"]', '["歌舞從来最得名，如今老寄洛陽城。","當时醉送龙驤曲，留與誰家唱月明。"]', '诗', 'shi', '', NULL, '爲人感贈 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4583c2b1-e065-4ea3-9dab-52382928c988', '春江恨別', '春江恨別', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["望斷長川一葉舟，可堪歸路更沿流。","垂來別處無人見，芳草斜陽滿渡頭。"]', '["望斷长川一葉舟，可堪归路更沿流。","垂来別处無人见，芳草斜陽满渡头。"]', '诗', 'shi', '', NULL, '春江恨別 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d500e8f1-7a41-4e87-82a2-b83454a93dee', '歎流水二首 一', '歎流水二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["人間莫謾惜花落，花落明年依舊開。","却最堪悲是流水，便同人事去無迴。"]', '["人间莫謾惜花落，花落明年依旧开。","却最堪悲是流水，便同人事去無迴。"]', '诗', 'shi', '', NULL, '歎流水二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8598df9-4e1d-4323-9c6d-bd4240c5538f', '歎流水二首 二', '歎流水二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["龍躍虬蟠旋作潭，繞紅濺綠下東南。","春風散入侯家去，漱齒花前酒半酣。"]', '["龙躍虬蟠旋作潭，繞紅濺綠下东南。","春风散入侯家去，漱齒花前酒半酣。"]', '诗', 'shi', '', NULL, '歎流水二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75978bd-2c37-4bbe-94e9-9fd37fa5b9af', '落第東歸', '落第东归', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["年年春色獨懷羞，彊向東歸懶舉頭。","莫道還家便容易，人間多少事堪愁。"]', '["年年春色独懷羞，彊向东归懶舉头。","莫道還家便容易，人间多少事堪愁。"]', '诗', 'shi', '', NULL, '落第東歸 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9a8dc2-6ddb-4c78-9623-fff124b26ead', '鏡', '镜', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["昔歲相知別有情，幾迴磨拭始將行。","如今老去愁無限，抱向閑窗却怕明。"]', '["昔歲相知別有情，幾迴磨拭始將行。","如今老去愁無限，抱向闲窗却怕明。"]', '诗', 'shi', '', NULL, '鏡 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee75c5e5-6718-4cee-9a1c-d3332c1fe273', '南行', '南行', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["臘晴江煖鸊鵜飛，梅雪香黏越女衣。","魚市酒村相識徧，短船歌月醉方歸。"]', '["臘晴江煖鸊鵜飞，梅雪香黏越女衣。","鱼市酒村相識徧，短船歌月醉方归。"]', '诗', 'shi', '', NULL, '南行 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e413d4-b9da-476a-93a7-be2142753514', '公子行', '公子行', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["金鞍玉勒照花明，過後春風特地生。","半醉五侯門裏出，月高猶在禁街行。"]', '["金鞍玉勒照花明，過後春风特地生。","半醉五侯门裏出，月高猶在禁街行。"]', '诗', 'shi', '', NULL, '公子行 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4581f7cd-3b3e-4efd-98d3-c9789d6e9dfc', '春日偶題城南韋曲', '春日偶題城南韋曲', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["韋曲城南錦繡堆，千金不惜買花栽。","誰知豪貴多羈束，落盡春紅不見來。"]', '["韋曲城南錦繡堆，千金不惜買花栽。","誰知豪貴多羈束，落尽春紅不见来。"]', '诗', 'shi', '', NULL, '春日偶題城南韋曲 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091a6064-01f8-4f8f-9317-2c1027077445', '上東川顧尚書', '上东川顧尚书', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["輕財重義真公子，長策沈機繼武侯。","龍節坐持兵十萬，可憐三蜀盡無憂。"]', '["轻財重義真公子，长策沈機繼武侯。","龙節坐持兵十万，可怜三蜀尽無憂。"]', '诗', 'shi', '', NULL, '上東川顧尚書 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6caee38d-ca1a-4198-afb9-d2d9e934ce5c', '過王濬墓', '過王濬墓', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["埋骨千年近路塵，路傍碑號晉將軍。","當時若使無功業，早箇耕桑到此墳。"]', '["埋骨千年近路塵，路傍碑號晉將軍。","當时若使無功業，早箇耕桑到此墳。"]', '诗', 'shi', '', NULL, '過王濬墓 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97708b0-b794-46d4-a87a-817b7e1ea3bd', '灞上感別', '灞上感別', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["灞水何人不別離，無家南北倚空悲。","十年此路花時節，立馬霑襟酒一巵。"]', '["灞水何人不別離，無家南北倚空悲。","十年此路花时節，立马霑襟酒一巵。"]', '诗', 'shi', '', NULL, '灞上感別 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f887b920-28d5-410e-8407-5445318457fe', '春日與友人話別', '春日與友人話別', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["酌坐對芳草，東風吹旅衣。","最嫌驅馬倦，自未有山歸。","華髪將時逼，青雲計又非。","離襟一霑灑，迴首正殘暉。"]', '["酌坐对芳草，东风吹旅衣。","最嫌驱马倦，自未有山归。","华髪將时逼，青云計又非。","離襟一霑灑，迴首正殘暉。"]', '诗', 'shi', '', NULL, '春日與友人話別 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77b71ed9-470d-4c38-b24e-8462db41ff93', '竹', '竹', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["翠葉纔分細細枝，清陰猶未上階墀。","蕙蘭雖許相依日，桃李還應笑後時。","抱節不爲霜霰改，成林終與鳳凰期。","渭濱若更徵賢相，好作漁竿繫釣絲。"]', '["翠葉纔分細細枝，清陰猶未上階墀。","蕙蘭雖許相依日，桃李還應笑後时。","抱節不爲霜霰改，成林終與鳳凰期。","渭濱若更徵賢相，好作漁竿繫釣絲。"]', '诗', 'shi', '', NULL, '竹 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e865eefa-a417-4315-b205-43e330d0fac6', '邊將', '邊將', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["馬上乘秋欲建勳，飛狐夜鬬出師頻。","若無紫塞煙塵事，誰識青樓歌舞人。","戰骨沙中金鏃在，賀筵花畔玉盤新。","由來邊卒皆如此，只是君門合殺身。"]', '["马上乘秋欲建勳，飞狐夜鬬出師頻。","若無紫塞煙塵事，誰識青楼歌舞人。","戰骨沙中金鏃在，賀筵花畔玉盤新。","由来邊卒皆如此，只是君门合殺身。"]', '诗', 'shi', '', NULL, '邊將 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6920acb-c13d-4e00-85ee-681ae2588559', '巴南旅泊', '巴南旅泊', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["巴山慘別魂，巴水徹荆門。","此地若重到，居人誰復存。","落帆紅葉渡，駐馬白雲村。","却羨南飛鴈，年年到故園。"]', '["巴山慘別魂，巴水徹荆门。","此地若重到，居人誰复存。","落帆紅葉渡，駐马白云村。","却羨南飞鴈，年年到故园。"]', '诗', 'shi', '', NULL, '巴南旅泊 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5666f391-cb86-4534-81b3-a14386484f5b', '河上逢友人', '河上逢友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["知君意不淺，立馬問生涯。","薄業無歸地，他鄉便是家。","宵吟憐桂魄，朝起怯菱花。","語盡黃河上，西風日又斜。"]', '["知君意不淺，立马问生涯。","薄業無归地，他乡便是家。","宵吟怜桂魄，朝起怯菱花。","語尽黄河上，西风日又斜。"]', '诗', 'shi', '', NULL, '河上逢友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95e5b7b7-96a1-4bdb-ae8d-195c8b5e11db', '偶題離亭', '偶題離亭', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["萬般名利不關身，況待山平海變塵。","五月波濤爭下峽，滿堂金玉爲何人。","謾誇浮世青雲貴，未盡離杯白髮新。","誰似雨篷篷底客，渚花汀鳥自相親。"]', '["万般名利不关身，況待山平海变塵。","五月波濤爭下峽，满堂金玉爲何人。","謾誇浮世青云貴，未尽離杯白髮新。","誰似雨篷篷底客，渚花汀鸟自相親。"]', '诗', 'shi', '', NULL, '偶題離亭 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aad938d-a1c0-4909-b186-737d62bb313a', '夏晚望嵩亭有懷', '夏晚望嵩亭有懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["正憐雲水與心違，湖上亭高對翠微。","盡日不妨憑檻望，終年未必有家歸。","青蟬漸傍幽叢噪，白鳥時穿返照飛。"]', '["正怜云水與心違，湖上亭高对翠微。","尽日不妨憑檻望，終年未必有家归。","青蟬漸傍幽叢噪，白鸟时穿返照飞。"]', '诗', 'shi', '', NULL, '夏晚望嵩亭有懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d82b500-8e29-4eb6-bbb1-30cca024d3c4', '途中寄友人', '途中寄友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["秋庭悵望別君初，折柳分襟十載餘。","相見或因中夜夢，寄來多是隔年書。","攜樽座外花空老，垂釣江頭柳漸疎。","裁得詩憑千里雁，吟來寧不憶吾廬。"]', '["秋庭悵望別君初，折柳分襟十載餘。","相见或因中夜梦，寄来多是隔年书。","携樽座外花空老，垂釣江头柳漸疎。","裁得诗憑千里雁，吟来寧不憶吾廬。"]', '诗', 'shi', '', NULL, '途中寄友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a00fd47-50c4-454e-af86-b6e1a35ec3a7', '傷侯弟', '傷侯弟', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["世間榮辱半相和，昨日權門今雀羅。","萬古明君方納諫，九江遷客更應多。","碧池草熟人偷釣，畫戟春閑鶯亂過。","幾許樂僮無主後，不離隣巷教笙歌。"]', '["世间榮辱半相和，昨日權门今雀羅。","万古明君方納諫，九江遷客更應多。","碧池草熟人偷釣，畫戟春闲鶯亂過。","幾許乐僮無主後，不離隣巷教笙歌。"]', '诗', 'shi', '', NULL, '傷侯弟 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a46df5-f913-4649-b9c1-d1c47ac5eb88', '春日過壽安山館', '春日過壽安山館', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["舊國多將泉石親，西遊愛此拂行塵。","簾開山色離亭午，步入松香別島春。","誰肯暫安耕釣地，相逢謾歎路岐身。","歸期不及桃花水，江上何曾鱠雪鱗。"]', '["旧国多將泉石親，西游愛此拂行塵。","簾开山色離亭午，步入松香別島春。","誰肯暫安耕釣地，相逢謾歎路岐身。","归期不及桃花水，江上何曾鱠雪鱗。"]', '诗', 'shi', '', NULL, '春日過壽安山館 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2dbaa7-0dca-49c0-ba3f-533c1d66f362', '吳門再逢方干處士', '吳门再逢方干处士', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["天上高名世上身，垂綸何不駕蒲輪。","一朝卿相俱前席，千古篇章冠後人。","稽嶺不歸空挂夢，吳宮相值欲霑巾。","吾王若致昇平化，可獨成周只渭濱。"]', '["天上高名世上身，垂綸何不駕蒲輪。","一朝卿相俱前席，千古篇章冠後人。","稽嶺不归空挂梦，吳宮相值欲霑巾。","吾王若致昇平化，可独成周只渭濱。"]', '诗', 'shi', '', NULL, '吳門再逢方干處士 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f1ee93-63e4-4b31-8107-17ccef2d8c9b', '蟬', '蟬', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["纔入新秋百感生，就中蟬噪最堪驚。","能催時節凋雙鬢，愁到江山聽一聲。","不傍管弦拘醉態，偏依楊柳撓離情。","故園聞處猶惆悵，況是經年萬里行。"]', '["纔入新秋百感生，就中蟬噪最堪驚。","能催时節凋雙鬢，愁到江山听一声。","不傍管弦拘醉態，偏依楊柳撓離情。","故园闻处猶惆悵，況是經年万里行。"]', '诗', 'shi', '', NULL, '蟬 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f28e86-f4dc-41cc-867c-651ba4bb4f57', '秋日留別義初上人', '秋日留別義初上人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["塞寺窮秋別還師，西風一雁倍傷悲。","每嗟塵世長多事，重到禪齋是幾時。","霜嶺自添紅葉恨，月溪休和碧雲詞。","關河回首便千里，飛錫南歸詎可知。"]', '["塞寺窮秋別還師，西风一雁倍傷悲。","每嗟塵世长多事，重到禪斋是幾时。","霜嶺自添紅葉恨，月溪休和碧云词。","关河回首便千里，飞錫南归詎可知。"]', '诗', 'shi', '', NULL, '秋日留別義初上人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37028d7-82b5-4d06-a9fe-38ea02e9a612', '夏日宿靈巖寺宗公院', '夏日宿靈巖寺宗公院', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["寺入千巖石路長，孤吟一宿遠公房。","臥聽半夜杉壇雨，轉覺中峰枕簟涼。","花界已無悲喜念，塵襟自足是非妨。","他年縱使重來此，息得心猨鬢已霜。"]', '["寺入千巖石路长，孤吟一宿远公房。","臥听半夜杉壇雨，轉覺中峰枕簟涼。","花界已無悲喜念，塵襟自足是非妨。","他年縱使重来此，息得心猨鬢已霜。"]', '诗', 'shi', '', NULL, '夏日宿靈巖寺宗公院 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c000d87-47b6-4226-9f93-d21869f772dc', '冬日廟中書事呈棲白上人', '冬日廟中书事呈棲白上人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["日高荒廟掩雙扉，杉逕無人鳥雀悲。","昨日江潮起歸思，滿窗風雨覺來時。","何堪身計長如此，閑盡爐灰却是疑。","賴有碧雲吟句客，禪餘相訪說新詩。"]', '["日高荒廟掩雙扉，杉逕無人鸟雀悲。","昨日江潮起归思，满窗风雨覺来时。","何堪身計长如此，闲尽爐灰却是疑。","賴有碧云吟句客，禪餘相訪说新诗。"]', '诗', 'shi', '', NULL, '冬日廟中書事呈棲白上人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('088834a6-8bcf-4562-b553-489c2a4ab7bb', '夏日題遠公北閣', '夏日題远公北閣', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["危閣壓山岡，晴空疑鳥行。","勝搜花界盡，響益梵音長。","有月堪先到，無風亦自涼。","人煙紛繞繞，諸樹共蒼蒼。","榻戀高樓語，甌憐晝茗香。","此身閑未得，驅馬入殘陽。"]', '["危閣壓山岡，晴空疑鸟行。","勝搜花界尽，响益梵音长。","有月堪先到，無风亦自涼。","人煙紛繞繞，諸樹共蒼蒼。","榻戀高楼語，甌怜晝茗香。","此身闲未得，驱马入殘陽。"]', '诗', 'shi', '', NULL, '夏日題遠公北閣 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71d784a-674e-481f-b08c-931b116330be', '秋蝶二首 一', '秋蝶二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["秦樓花發時，秦女笑相隨。","及到秋風日，飛來欲問誰。"]', '["秦楼花發时，秦女笑相隨。","及到秋风日，飞来欲问誰。"]', '诗', 'shi', '', NULL, '秋蝶二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e97bc90-04df-4d50-9604-40a70a990e40', '秋蝶二首 二', '秋蝶二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["似厭栖寒菊，翩翩占晚陽。","愁人如見此，應下淚千行。"]', '["似厭栖寒菊，翩翩占晚陽。","愁人如见此，應下泪千行。"]', '诗', 'shi', '', NULL, '秋蝶二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa73018c-c5be-4d65-ab0d-551a19049b56', '秋別', '秋別', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["別路垂[楊]柳，秋風淒管弦。","青樓君去後，明月爲誰圓。"]', '["別路垂[楊]柳，秋风淒管弦。","青楼君去後，明月爲誰圓。"]', '诗', 'shi', '', NULL, '秋別 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80179f84-582b-46ce-8e64-60f5a3e83cbb', '共友人看花', '共友人看花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["愁將萬里身，來伴看花人。","何事獨惆悵，故園還又春。"]', '["愁將万里身，来伴看花人。","何事独惆悵，故园還又春。"]', '诗', 'shi', '', NULL, '共友人看花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4149460e-a279-46c8-89d6-72433f2d02fa', '行次', '行次', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["終日長程復短程，一山行盡一山青。","路傍君子莫相笑，天上由來有客星。"]', '["終日长程复短程，一山行尽一山青。","路傍君子莫相笑，天上由来有客星。"]', '诗', 'shi', '', NULL, '行次 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('122d3a6f-4d3c-4989-82f7-84cad990ebc6', '鳯州北樓', '鳯州北楼', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["城上層樓北望時，閑雲遠水自相宜。","人人盡道堪圖畫，枉遣山翁醉習池。"]', '["城上層楼北望时，闲云远水自相宜。","人人尽道堪圖畫，枉遣山翁醉習池。"]', '诗', 'shi', '', NULL, '鳯州北樓 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c790d2-6e13-4faa-a2b2-28dbe6a27972', '贈僧', '贈僧', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["繁華舉世皆如夢，今古何人肯暫閑。","唯有東林學禪客，白頭閑坐對青山。"]', '["繁华舉世皆如梦，今古何人肯暫闲。","唯有东林学禪客，白头闲坐对青山。"]', '诗', 'shi', '', NULL, '贈僧 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70cd0ff-ca1c-459d-abc7-6850d58b7629', '曲江春感', '曲江春感', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江頭日暖花又開，江東行客心悠哉。","高陽酒徒半彫落，終南山色空崔嵬。","聖代也知無棄物，侯門未必用非才。","一船明月一竿竹，家住五湖歸去來。"]', '["江头日暖花又开，江东行客心悠哉。","高陽酒徒半彫落，終南山色空崔嵬。","聖代也知無棄物，侯门未必用非才。","一船明月一竿竹，家住五湖归去来。"]', '诗', 'shi', '', NULL, '曲江春感 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996562b6-5aa5-4798-9e29-8712dca22720', '皇陂', '皇陂', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["皇陂瀲灩深復深，陂西下馬聊登臨。","垂楊風輕弄翠帶，鯉魚日暖跳黃金。","三月窮途無勝事，十年流水見歸心。","輸他谷口鄭夫子，偷得閑名說至今。"]', '["皇陂瀲灩深复深，陂西下马聊登臨。","垂楊风轻弄翠带，鯉鱼日暖跳黄金。","三月窮途無勝事，十年流水见归心。","輸他谷口鄭夫子，偷得闲名说至今。"]', '诗', 'shi', '', NULL, '皇陂 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deacbc5d-c662-420c-b733-145872752fae', '寄鄭補闕', '寄鄭補闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["夫子門前數仞牆，每經過處憶遊梁。","路從青瑣無因見，恩在丹心不可忘。","未必便爲讒口隔，只應貪草諫書忙。","別來愁悴知多少，兩度槐花馬上黃。"]', '["夫子门前數仞牆，每經過处憶游梁。","路從青瑣無因见，恩在丹心不可忘。","未必便爲讒口隔，只應貪草諫书忙。","別来愁悴知多少，兩度槐花马上黄。"]', '诗', 'shi', '', NULL, '寄鄭補闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db92063f-038f-4620-9990-3f7d697ad279', '牡丹花', '牡丹花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["似共東風別有因，絳羅高卷不勝春。","若教解語應傾國，任是無情亦動人。","芍藥與君爲近侍，芙蓉何處避芳塵。","可憐韓令功成後，辜負穠華過此身。"]', '["似共东风別有因，絳羅高卷不勝春。","若教解語應傾国，任是無情亦动人。","芍藥與君爲近侍，芙蓉何处避芳塵。","可怜韓令功成後，辜負穠华過此身。"]', '诗', 'shi', '', NULL, '牡丹花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea3421c-ab98-4fe8-96a5-b3e0328016e4', '黃河', '黄河', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["莫把阿膠向此傾，此中天意固難明。","解通銀漢應須曲，纔出崑崙便不清。","高祖誓功衣帶小，仙人占斗客槎輕。","三千年後知誰在，何必勞君報太平。"]', '["莫把阿膠向此傾，此中天意固难明。","解通銀漢應須曲，纔出崑崙便不清。","高祖誓功衣带小，仙人占斗客槎轻。","三千年後知誰在，何必勞君報太平。"]', '诗', 'shi', '', NULL, '黃河 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82431b04-6628-41bc-b038-7913b3fc2236', '汴河', '汴河', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["當時天子是閑遊，今日行人特地愁。","柳色縱饒妝故國，水聲何忍到揚州。","乾坤有意終難會，黎庶無情豈自由。","應笑秦皇用心錯，謾驅神鬼海東頭。"]', '["當时天子是闲游，今日行人特地愁。","柳色縱饒妝故国，水声何忍到揚州。","乾坤有意終难會，黎庶無情豈自由。","應笑秦皇用心錯，謾驱神鬼海东头。"]', '诗', 'shi', '', NULL, '汴河 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42cd3e9-6353-4d46-9caa-2a2b15a018ee', '西京崇德里居', '西京崇德里居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["進乏梯媒退又難，強隨豪貴殢長安。","風從昨夜吹銀漢，淚擬何門落玉盤。","拋擲紅塵應有恨，思量仙桂也無端。","錦鱗赬尾平生事，却被閑人把釣竿。"]', '["進乏梯媒退又难，強隨豪貴殢长安。","风從昨夜吹銀漢，泪擬何门落玉盤。","拋擲紅塵應有恨，思量仙桂也無端。","錦鱗赬尾平生事，却被闲人把釣竿。"]', '诗', 'shi', '', NULL, '西京崇德里居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f50862c-2d38-4905-ad42-aa051802c3ed', '投所思', '投所思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["顦顇長安何所爲，旅魂窮命自相疑。","滿川碧嶂無歸日，一榻紅塵有淚時。","雕琢只應勞郢匠，膏肓終恐誤秦醫。","浮生七十今三十，從此悽惶未可知。"]', '["顦顇长安何所爲，旅魂窮命自相疑。","满川碧嶂無归日，一榻紅塵有泪时。","雕琢只應勞郢匠，膏肓終恐誤秦醫。","浮生七十今三十，從此悽惶未可知。"]', '诗', 'shi', '', NULL, '投所思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a39a519-2dbf-4459-899a-2d222df61449', '經張舍人舊居', '經張舍人旧居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["行塵不是昔時塵，謾向朱門憶侍臣。","一榻已無開眼處，九泉應有愛才人。","文餘吐鳳他年詔，樹想棲鸞舊日春。","從此恩深轉難報，夕陽衰草淚沾巾。"]', '["行塵不是昔时塵，謾向朱门憶侍臣。","一榻已無开眼处，九泉應有愛才人。","文餘吐鳳他年詔，樹想棲鸾旧日春。","從此恩深轉难報，夕陽衰草泪沾巾。"]', '诗', 'shi', '', NULL, '經張舍人舊居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb36b9b4-b939-41c9-8afb-c982600e826c', '雒城作', '雒城作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["大鹵旌旗出洛濱，此中煙月已埃塵。","更無樓閣尋行處，只有山川識野人。","早得鑄金誇范蠡，旋聞垂釣哭平津。","舊遊難得時難遇，迴首空城百草春。"]', '["大鹵旌旗出洛濱，此中煙月已埃塵。","更無楼閣尋行处，只有山川識野人。","早得鑄金誇范蠡，旋闻垂釣哭平津。","旧游难得时难遇，迴首空城百草春。"]', '诗', 'shi', '', NULL, '雒城作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('734ea579-0c9a-41ee-910c-f510551c2983', '姑蘇城南湖陪曹使君遊', '姑蘇城南湖陪曹使君游', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["水蓼花紅稻穗黃，使君蘭棹汎迴塘。","倚風荇藻先開路，迎斾鳧鷖盡著行。","手裏兵符神與術，腰間金印綵爲囊。","少年太守勳庸盛，應笑燕臺兩鬢霜。"]', '["水蓼花紅稻穗黄，使君蘭棹汎迴塘。","倚风荇藻先开路，迎斾鳧鷖尽著行。","手裏兵符神與術，腰间金印綵爲囊。","少年太守勳庸盛，應笑燕台兩鬢霜。"]', '诗', 'shi', '', NULL, '姑蘇城南湖陪曹使君遊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687b7b59-8e11-49a6-9019-27074b232f03', '秋日有寄姑蘇曹使君', '秋日有寄姑蘇曹使君', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["多病無因櫂小舟，闔閭城下謁名侯。","水寒不見雙魚信，風便唯聞五袴謳。","早說用兵長暗合，近傳觀稼亦閑遊。","須知謝奕依前醉，閒阻清談又一秋。"]', '["多病無因櫂小舟，闔閭城下謁名侯。","水寒不见雙鱼信，风便唯闻五袴謳。","早说用兵长暗合，近傳观稼亦闲游。","須知謝奕依前醉，閒阻清談又一秋。"]', '诗', 'shi', '', NULL, '秋日有寄姑蘇曹使君 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b46bca13-2d00-4f0f-999c-61faafae2ef8', '送章碣赴舉', '送章碣赴舉', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["苹鹿歌中別酒催，粉闈星彩動昭回。","久經罹亂心應破，乍覩昇平眼漸開。","顧我昔年悲玉石，憐君今日蘊風雷。","龍門盛事無因見，費盡黃金老隗臺。"]', '["苹鹿歌中別酒催，粉闈星彩动昭回。","久經罹亂心應破，乍覩昇平眼漸开。","顧我昔年悲玉石，怜君今日蘊风雷。","龙门盛事無因见，費尽黄金老隗台。"]', '诗', 'shi', '', NULL, '送章碣赴舉 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603ae201-ece8-4c04-bb3f-8516b304ef86', '寄楊秘書', '寄楊秘书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["湖水平來見鯉魚，偶因烹處得瓊琚。","披尋藻思千重後，吟想冰光萬里餘。","漳浦病來情轉薄，赤城吟苦意何如。","錦衣公子憐君在，十載兵戈從板輿。"]', '["湖水平来见鯉鱼，偶因烹处得瓊琚。","披尋藻思千重後，吟想冰光万里餘。","漳浦病来情轉薄，赤城吟苦意何如。","錦衣公子怜君在，十載兵戈從板輿。"]', '诗', 'shi', '', NULL, '寄楊秘書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb880d90-cec0-490a-b68c-a7b1c29a470f', '往年進士趙能卿嘗話金庭勝事見示敘', '往年進士趙能卿嘗話金庭勝事见示敘', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["會稽詩客趙能卿，往歲相逢話石城。","正恨故人無上壽，喜聞良宰有高情。","山朝佐命層層聳，水接飛流步步清。","兩火一刀罹亂後，會須乘興雪中行。"]', '["會稽诗客趙能卿，往歲相逢話石城。","正恨故人無上壽，喜闻良宰有高情。","山朝佐命層層聳，水接飞流步步清。","兩火一刀罹亂後，會須乘兴雪中行。"]', '诗', 'shi', '', NULL, '往年進士趙能卿嘗話金庭勝事見示敘 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d443dda0-9ffb-4f82-a6e1-8c58d1e4b708', '得宣州竇尚書書因投寄二首 一', '得宣州竇尚书书因投寄二首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雙魚迢遞到江濱，傷感南陵舊主人。","萬里朝臺勞寄夢，十年侯國阻趨塵。","尋知亂後嘗辭祿，共喜閑來得養神。","時見齊山敬亭客，不堪戎馬戰征頻。"]', '["雙鱼迢遞到江濱，傷感南陵旧主人。","万里朝台勞寄梦，十年侯国阻趨塵。","尋知亂後嘗辞祿，共喜闲来得養神。","时见齊山敬亭客，不堪戎马戰征頻。"]', '诗', 'shi', '', NULL, '得宣州竇尚書書因投寄二首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85ef9f8-714c-4bee-9cd5-fddf6897f101', '得宣州竇尚書書因投寄二首 二', '得宣州竇尚书书因投寄二首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["曾逐旌旗過板橋，世途多難竟蓬飄。","步兵校尉辭公府，車騎將軍憶本朝。","醉裏舊遊還歷歷，病中衰鬢奈蕭蕭。","遺簪墮履應留念，門客如今只下僚。"]', '["曾逐旌旗過板橋，世途多难竟蓬飄。","步兵校尉辞公府，车騎將軍憶本朝。","醉裏旧游還歷歷，病中衰鬢奈蕭蕭。","遺簪墮履應留念，门客如今只下僚。"]', '诗', 'shi', '', NULL, '得宣州竇尚書書因投寄二首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c5a3223-b5ac-4be6-a085-c8a4abe9203c', '雪', '雪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["細玉羅紋下碧霄，杜門顏巷落偏饒。","巢居只恐高柯折，旅客愁聞去路遙。","撅凍野蔬和粉重，埽庭松葉帶酥燒。","寒窗呵筆尋詩句，一片飛來紙上銷。"]', '["細玉羅紋下碧霄，杜门顏巷落偏饒。","巢居只恐高柯折，旅客愁闻去路遙。","撅凍野蔬和粉重，埽庭松葉带酥燒。","寒窗呵笔尋诗句，一片飞来紙上銷。"]', '诗', 'shi', '', NULL, '雪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded6ea3d-bfbd-4037-a82f-f9f8e5846d4d', '暇日有寄姑蘇曹使君兼呈張郎中郡中賓僚', '暇日有寄姑蘇曹使君兼呈張郎中郡中賓僚', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["嘉植陰陰覆劒池，此中能政動神祗。","湖邊觀稼雨迎馬，城外犒軍風滿旗。","融酒徒誇無算爵，儉蓮還少最高枝。","珊瑚筆架真珠履，曾和陳王幾首詩。"]', '["嘉植陰陰覆劒池，此中能政动神祗。","湖邊观稼雨迎马，城外犒軍风满旗。","融酒徒誇無算爵，儉蓮還少最高枝。","珊瑚笔架真珠履，曾和陳王幾首诗。"]', '诗', 'shi', '', NULL, '暇日有寄姑蘇曹使君兼呈張郎中郡中賓僚 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa8873a-f6ad-438a-832c-4bfe412a90b1', '寄右省王諫議', '寄右省王諫議', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["耳邊要靜不得靜，心裏欲閑終未閑。","自是宿緣應有累，可能時事更相關。","魚慙張翰辭東府，鶴怨周顒負北山。","看却金庭芝朮老，又驅車入七人班。"]', '["耳邊要静不得静，心裏欲闲終未闲。","自是宿緣應有累，可能时事更相关。","鱼慙張翰辞东府，鹤怨周顒負北山。","看却金庭芝朮老，又驱车入七人班。"]', '诗', 'shi', '', NULL, '寄右省王諫議 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('042ca878-b3bb-45b7-af5a-2719423b4ca1', '焚書坑', '焚书坑', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["千載遺蹤一窖塵，路傍耕者亦傷神。","祖龍算事渾乖角，將謂詩書活得人。"]', '["千載遺蹤一窖塵，路傍耕者亦傷神。","祖龙算事渾乖角，將謂诗书活得人。"]', '诗', 'shi', '', NULL, '焚書坑 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d9a248-116f-4465-8f3b-411bd41324a5', '始皇陵', '始皇陵', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["荒堆無草樹無枝，嬾向行人問昔時。","六國英雄漫多事，到頭徐福是男兒。"]', '["荒堆無草樹無枝，嬾向行人问昔时。","六国英雄漫多事，到头徐福是男兒。"]', '诗', 'shi', '', NULL, '始皇陵 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b29ffdc-f28c-4e03-a2ee-96b99d8ac4f9', '送沈先輩歸送上嘉禮', '送沈先輩归送上嘉禮', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青青月桂觸人香，白苧衫輕稱沈郎。","好繼馬卿歸故里，況聞山簡在襄陽。","盃傾別岸應須醉，花傍征軍漸欲芳。","擬把金錢贈嘉禮，不堪栖屑困名場。"]', '["青青月桂觸人香，白苧衫轻稱沈郎。","好繼马卿归故里，況闻山簡在襄陽。","盃傾別岸應須醉，花傍征軍漸欲芳。","擬把金錢贈嘉禮，不堪栖屑困名場。"]', '诗', 'shi', '', NULL, '送沈先輩歸送上嘉禮 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b298777c-4db6-424c-b441-e4051bf7ecc9', '春日葉秀才曲江', '春日葉秀才曲江', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江花江草暖相隈，也向江邊把酒杯。","春色惱人遮不得，別愁如瘧避還來。","安排賤跡無良策，裨補明時望重才。","一曲吳歌齊拍手，十年塵眼未曾開。"]', '["江花江草暖相隈，也向江邊把酒杯。","春色惱人遮不得，別愁如瘧避還来。","安排賤跡無良策，裨補明时望重才。","一曲吳歌齊拍手，十年塵眼未曾开。"]', '诗', 'shi', '', NULL, '春日葉秀才曲江 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35dc0c09-9b06-424e-88ad-744de4d6b4a7', '西京道德里', '西京道德里', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秦樹團團夕結陰，此中莊舃動悲吟。","一枝丹桂未入手，萬里蒼波長負心。","老去漸知時態薄，愁來唯願酒杯深。","七雄三傑今何在，休爲閑人淚滿襟。"]', '["秦樹團團夕結陰，此中莊舃动悲吟。","一枝丹桂未入手，万里蒼波长負心。","老去漸知时態薄，愁来唯願酒杯深。","七雄三傑今何在，休爲闲人泪满襟。"]', '诗', 'shi', '', NULL, '西京道德里 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf26999-c33a-41aa-814a-32f7a4b1ef15', '憶夏口', '憶夏口', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["漢陽渡口蘭爲舟，漢陽城下多酒樓。","當年不得盡一醉，別夢有時還重遊。","襟帶可憐吞楚塞，風煙只好狎江鷗。","月明更想曾行處，吹笛橋邊木葉秋。"]', '["漢陽渡口蘭爲舟，漢陽城下多酒楼。","當年不得尽一醉，別梦有时還重游。","襟带可怜吞楚塞，风煙只好狎江鷗。","月明更想曾行处，吹笛橋邊木葉秋。"]', '诗', 'shi', '', NULL, '憶夏口 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd478b9-c0d3-4e6d-a3f7-625a1f31d2d7', '武牢關', '武牢关', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["楚人曾此限封疆，不見清陰六里長。","一壑暮聲何怨望，數峰秋勢自顛狂。","由來四皓須神伏，大抵秦皇謾氣強。","欲學雞鳴試關吏，太平時節嬾思量。"]', '["楚人曾此限封疆，不见清陰六里长。","一壑暮声何怨望，數峰秋勢自顛狂。","由来四皓須神伏，大抵秦皇謾氣強。","欲学雞鳴試关吏，太平时節嬾思量。"]', '诗', 'shi', '', NULL, '武牢關 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170a3ec4-38b1-4e0b-947e-7bc6746ec822', '途中獻晉州孟中丞', '途中獻晉州孟中丞', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["太平天子念蒲東，又委星郎養育功。","昨日隼旟辭闕下，今朝珠履在河中。","樓移庾亮千山月，樹待袁宏一扇風。","不及政成應入拜，晉州何足展清通。"]', '["太平天子念蒲东，又委星郎養育功。","昨日隼旟辞闕下，今朝珠履在河中。","楼移庾亮千山月，樹待袁宏一扇风。","不及政成應入拜，晉州何足展清通。"]', '诗', 'shi', '', NULL, '途中獻晉州孟中丞 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def3c98e-2235-49e0-a98a-c41df9d87858', '長安秋夜', '长安秋夜', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遠聞天子似羲皇，偶捨漁鄉入帝鄉。","五等列侯無故舊，一枝仙桂有風霜。","燈欹短焰燒離鬢，漏轉寒更滴旅腸。","歸計未知身已老，九衢雙闕夜蒼蒼。"]', '["远闻天子似羲皇，偶捨漁乡入帝乡。","五等列侯無故旧，一枝仙桂有风霜。","灯欹短焰燒離鬢，漏轉寒更滴旅腸。","归計未知身已老，九衢雙闕夜蒼蒼。"]', '诗', 'shi', '', NULL, '長安秋夜 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a667d245-2c14-4386-8f2b-ad0977c21bc4', '春晚寄鍾尚書', '春晚寄鍾尚书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["宰府初開忝末塵，四年談笑隔通津。","官資肯便矜中路，酒醆還應憶故人。","江畔舊遊秦望月，檻前公事鏡湖春。","如今莫問西禪塢，一炷寒香老病身。"]', '["宰府初开忝末塵，四年談笑隔通津。","官資肯便矜中路，酒醆還應憶故人。","江畔旧游秦望月，檻前公事镜湖春。","如今莫问西禪塢，一炷寒香老病身。"]', '诗', 'shi', '', NULL, '春晚寄鍾尚書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a4bb22-0ec2-46ae-9519-0aca07aac67e', '秋曉寄友人', '秋晓寄友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["洞庭霜落水雲秋，又汎輕漣任去留。","世界高談今已得，宦途清貴舊曾遊。","手中綵筆誇題鳳，天上泥封獎狎鷗。","更見南來釣翁說，醉吟還上木蘭舟。"]', '["洞庭霜落水云秋，又汎轻漣任去留。","世界高談今已得，宦途清貴旧曾游。","手中綵笔誇題鳳，天上泥封獎狎鷗。","更见南来釣翁说，醉吟還上木蘭舟。"]', '诗', 'shi', '', NULL, '秋曉寄友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e62191-de6f-4132-9b42-3353b3552c83', '秋日有酬', '秋日有酬', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["舊業傳家有寶刀，近聞餘力更揮毫。","腰間印佩黃金重，卷裏詩裁白雪高。","讌罷嘉賓迎鳳藻，獵歸諸將問龍韜。","分茅列土纔三十，猶擬廻頭賭錦袍。"]', '["旧業傳家有寶刀，近闻餘力更揮毫。","腰间印佩黄金重，卷裏诗裁白雪高。","讌罷嘉賓迎鳳藻，獵归諸將问龙韜。","分茅列土纔三十，猶擬廻头賭錦袍。"]', '诗', 'shi', '', NULL, '秋日有酬 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0643db-fed7-482c-821d-339d292fbb2e', '所思', '所思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["梁王兔苑荆榛裏，煬帝雞臺夢想中。","只覺惘然悲謝傅，未知何以報文翁。","生靈不幸台星拆，造化無情世界空。","劃盡寒灰始堪歎，滿庭霜葉一窗風。"]', '["梁王兔苑荆榛裏，煬帝雞台梦想中。","只覺惘然悲謝傅，未知何以報文翁。","生靈不幸台星拆，造化無情世界空。","劃尽寒灰始堪歎，满庭霜葉一窗风。"]', '诗', 'shi', '', NULL, '所思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15600055-696a-47f0-817c-79e837b79be8', '送魏校書兼呈曹使君', '送魏校书兼呈曹使君', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["亂離無計駐生涯，又事東遊惜歲華。","村店酒旗沽竹葉，野橋梅雨泊蘆花。","讐書發跡官雖屈，負米安親路不賒。","應見使君論世舊，埽門重得向曹家。"]', '["亂離無計駐生涯，又事东游惜歲华。","村店酒旗沽竹葉，野橋梅雨泊蘆花。","讐书發跡官雖屈，負米安親路不賒。","應见使君論世旧，埽门重得向曹家。"]', '诗', 'shi', '', NULL, '送魏校書兼呈曹使君 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdec1cbe-b0fe-4c00-b212-ed75035cd5aa', '四皓廟', '四皓廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["漢惠秦皇事已聞，廟前高木眼前雲。","楚王謾費閑心力，六里青山盡屬君。"]', '["漢惠秦皇事已闻，廟前高木眼前云。","楚王謾費闲心力，六里青山尽屬君。"]', '诗', 'shi', '', NULL, '四皓廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad3cceb-e35a-4b5a-b362-cd6442348299', '浮雲', '浮云', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["溶溶曳曳自舒張，不向蒼梧即帝鄉。","莫道無心便無事，也曾愁殺楚襄王。"]', '["溶溶曳曳自舒張，不向蒼梧即帝乡。","莫道無心便無事，也曾愁殺楚襄王。"]', '诗', 'shi', '', NULL, '浮雲 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92510ba1-d3e9-4758-986d-cbe94fa8664c', '早發', '早發', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["北去南來無定居，此生生計竟何如。","酷憐一覺平明睡，長被雞聲惡破除。"]', '["北去南来無定居，此生生計竟何如。","酷怜一覺平明睡，长被雞声惡破除。"]', '诗', 'shi', '', NULL, '早發 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7811ce26-7387-43ff-bde2-4489d2d6a668', '香', '香', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["沈水良材食柏珍，博山煙煖玉樓春。","憐君亦是無端物，貪作馨香忘却身。"]', '["沈水良材食柏珍，博山煙煖玉楼春。","怜君亦是無端物，貪作馨香忘却身。"]', '诗', 'shi', '', NULL, '香 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e0483a-7f2d-4d52-941b-26c22158b0f0', '鄴城', '鄴城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["臺上年年揜翠蛾，臺前高樹夾漳河。","英雄亦到分香處，能共常人較幾多。"]', '["台上年年揜翠蛾，台前高樹夾漳河。","英雄亦到分香处，能共常人較幾多。"]', '诗', 'shi', '', NULL, '鄴城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03dae603-233e-4110-b819-f1f4cdaa8e50', '七夕', '七夕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["絡角星河菡萏天，一家懽笑設紅筵。","應傾謝女珠璣篋，盡寫檀郎錦繡篇。","香帳簇成排窈窕，金鍼穿罷拜嬋娟。","銅壺漏報天將曉，惆悵佳期又一年。"]', '["絡角星河菡萏天，一家懽笑設紅筵。","應傾謝女珠璣篋，尽寫檀郎錦繡篇。","香帳簇成排窈窕，金鍼穿罷拜嬋娟。","銅壺漏報天將晓，惆悵佳期又一年。"]', '诗', 'shi', '', NULL, '七夕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb037d5-bfd7-4374-866b-b49a217ebd35', '送臧濆下第謁竇鄜州', '送臧濆下第謁竇鄜州', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["賦得長楊不直錢，却來京口看鶯遷。","也知絳灌輕才子，好謁尤常醉少年。","萬里故鄉雲縹緲，一春生計淚瀾汍。","多情柱史應相問，與話歸心正浩然。"]', '["賦得长楊不直錢，却来京口看鶯遷。","也知絳灌轻才子，好謁尤常醉少年。","万里故乡云縹緲，一春生計泪瀾汍。","多情柱史應相问，與話归心正浩然。"]', '诗', 'shi', '', NULL, '送臧濆下第謁竇鄜州 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952d21bd-f771-4e05-882d-55e26116b124', '清明日曲江懷友', '清明日曲江懷友', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["君與田蘇即舊遊，我於交分亦綢繆。","二年隔絕黃泉下，盡日悲涼曲水頭。","鷗鳥似能齊物理，杏花疑欲伴人愁。","寡妻稚子應寒食，遙望江陵一淚流。"]', '["君與田蘇即旧游，我於交分亦綢繆。","二年隔絕黄泉下，尽日悲涼曲水头。","鷗鸟似能齊物理，杏花疑欲伴人愁。","寡妻稚子應寒食，遙望江陵一泪流。"]', '诗', 'shi', '', NULL, '清明日曲江懷友 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c639a190-62a3-4315-b1b8-ea68063c293e', '送鄭州嚴員外', '送鄭州嚴員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["欲將刀筆潤王猷，東去先分聖主憂。","滿扇好風吹鄭圃，一車甘雨別皇州。","尚書磧冷鴻聲晚，僕射陂寒樹影秋。","從此文星在何處，武牢關外庾公樓。"]', '["欲將刀笔潤王猷，东去先分聖主憂。","满扇好风吹鄭圃，一车甘雨別皇州。","尚书磧冷鴻声晚，僕射陂寒樹影秋。","從此文星在何处，武牢关外庾公楼。"]', '诗', 'shi', '', NULL, '送鄭州嚴員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd43c18-526b-47fb-9c80-0864bf9010b0', '孫員外赴闕後重到三衢', '孫員外赴闕後重到三衢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遠山高樹思悠哉，重倚危樓盡一杯。","謝守已隨徵詔入，魯儒猶逐斷蓬來。","地寒謾憶移暄手，時急方須濟世才。","宣室夜闌如有問，可能全望未然灰。"]', '["远山高樹思悠哉，重倚危楼尽一杯。","謝守已隨徵詔入，魯儒猶逐斷蓬来。","地寒謾憶移暄手，时急方須濟世才。","宣室夜闌如有问，可能全望未然灰。"]', '诗', 'shi', '', NULL, '孫員外赴闕後重到三衢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c2fb76-79ae-4a19-9023-779674fc00f4', '衡陽泊木居士廟下作', '衡陽泊木居士廟下作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["烏噪殘陽草滿庭，此中枯木似人形。","只應神物長爲主，未必浮槎即有靈。","八月風波飄不去，四時黍稷薦惟馨。","南朝庾信無因賦，牢落祠前水氣腥。"]', '["烏噪殘陽草满庭，此中枯木似人形。","只應神物长爲主，未必浮槎即有靈。","八月风波飄不去，四时黍稷薦惟馨。","南朝庾信無因賦，牢落祠前水氣腥。"]', '诗', 'shi', '', NULL, '衡陽泊木居士廟下作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c75a02-2c14-4e7b-abfe-0813bf416aeb', '鍾陵見楊秀才', '鍾陵见楊秀才', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["孺亭滕閣少踟躕，三度南遊一事無。","秪覺流年如鳥逝，不知何處有龍屠？","雲歸洪井枝柯斂，水下漳江氣色麤。","賴得與君同此醉，醒來愁被鬼揶揄。"]', '["孺亭滕閣少踟躕，三度南游一事無。","秪覺流年如鸟逝，不知何处有龙屠？","云归洪井枝柯斂，水下漳江氣色麤。","賴得與君同此醉，醒来愁被鬼揶揄。"]', '诗', 'shi', '', NULL, '鍾陵見楊秀才 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa2eb55-7350-4be6-bf41-30b01d397fef', '自湘川東下立春泊夏口阻風登孫權城', '自湘川东下立春泊夏口阻风登孫權城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳門此去逾千里，湘浦離來想數旬。","只見風師長占路，不知青帝已行春。","危憐壞堞猶遮水，狂愛寒梅欲傍人。","事往時移何足問，且憑村酒暖精神。"]', '["吳门此去逾千里，湘浦離来想數旬。","只见风師长占路，不知青帝已行春。","危怜壞堞猶遮水，狂愛寒梅欲傍人。","事往时移何足问，且憑村酒暖精神。"]', '诗', 'shi', '', NULL, '自湘川東下立春泊夏口阻風登孫權城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c67e23-6445-4765-af73-e8f2cd61c090', '春日憶湖南舊遊寄盧校書', '春日憶湖南旧游寄盧校书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["旅榜前年過洞庭，曾提刀筆事甘寧。","瑇筵離隔將軍幕，朱履頻窺處士星。","恩重匣中孤劒在，夢餘江畔數峰青。","金貂見服嘉賓散，回首昭丘一涕零。"]', '["旅榜前年過洞庭，曾提刀笔事甘寧。","瑇筵離隔將軍幕，朱履頻窺处士星。","恩重匣中孤劒在，梦餘江畔數峰青。","金貂见服嘉賓散，回首昭丘一涕零。"]', '诗', 'shi', '', NULL, '春日憶湖南舊遊寄盧校書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04023e4-bd8a-46ae-9791-8564abfd1870', '賀淮南節度盧員外賜緋', '賀淮南節度盧員外賜緋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["儉蓮高貴九霄聞，粲粲朱衣降五雲。","驄馬早年曾避路，銀魚今日且從軍。","御題綵服垂天眷，袍展花心透縠紋。","應笑當年老萊子，鮮華都自降明君。"]', '["儉蓮高貴九霄闻，粲粲朱衣降五云。","驄马早年曾避路，銀鱼今日且從軍。","御題綵服垂天眷，袍展花心透縠紋。","應笑當年老萊子，鲜华都自降明君。"]', '诗', 'shi', '', NULL, '賀淮南節度盧員外賜緋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9076aaee-0789-49e6-98f2-c1e6ab75db1e', '春日獨遊禪智寺', '春日独游禪智寺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["樹遠連天水接空，幾年行樂舊隋宮。","花開花謝還如此，人去人來自不同。","鸞鳳調高何處酒，吳牛蹄健滿車風。","思量只合騰騰醉，煮海平陳一夢中。"]', '["樹远連天水接空，幾年行乐旧隋宮。","花开花謝還如此，人去人来自不同。","鸾鳳調高何处酒，吳牛蹄健满车风。","思量只合腾腾醉，煮海平陳一梦中。"]', '诗', 'shi', '', NULL, '春日獨遊禪智寺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b0e94c-2f46-4d7f-8678-dd9c2448afb0', '和淮南李司空同轉運員外', '和淮南李司空同轉運員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["層層高閣舊瀛洲，此地須徵第一流。","丞相近年縈倚望，重才今日喜遨遊。","榮持健筆金黃貴，恨咽離筵管吹秋。","誰繼伊臯送行句，梁王詩好郢人愁。"]', '["層層高閣旧瀛洲，此地須徵第一流。","丞相近年縈倚望，重才今日喜遨游。","榮持健笔金黄貴，恨咽離筵管吹秋。","誰繼伊臯送行句，梁王诗好郢人愁。"]', '诗', 'shi', '', NULL, '和淮南李司空同轉運員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c2a2d0-43e3-4dc8-8b04-701f6fe4ed25', '后土廟', '后土廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["四海兵戈尚未寧，始於雲外學儀形。","九天玄女猶無聖，后土夫人豈有靈。","一帶好雲侵鬢綠，兩層危岫拂眉青。","韋郎年少知何在，端坐思量太白經。"]', '["四海兵戈尚未寧，始於云外学儀形。","九天玄女猶無聖，后土夫人豈有靈。","一带好云侵鬢綠，兩層危岫拂眉青。","韋郎年少知何在，端坐思量太白經。"]', '诗', 'shi', '', NULL, '后土廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88590f8c-7514-4583-89e3-048383edb9d9', '金陵夜泊', '金陵夜泊', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["冷煙輕澹傍衰叢，此夕秦淮駐斷蓬。","棲鴈遠驚沽酒火，亂鵶高避落帆風。","地銷王氣波聲急，山帶秋陰樹影空。","六代精靈人不見，思量應在月明中。"]', '["冷煙轻澹傍衰叢，此夕秦淮駐斷蓬。","棲鴈远驚沽酒火，亂鵶高避落帆风。","地銷王氣波声急，山带秋陰樹影空。","六代精靈人不见，思量應在月明中。"]', '诗', 'shi', '', NULL, '金陵夜泊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba05ac2e-d158-43f4-94e4-3615d9957711', '上江州陳員外', '上江州陳員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寒江九派轉城樓，東下鍾陵第一州。","人自中臺方貴盛，地從西晉即風流。","舊班久望鵷晴翥，餘力猶聞虎夜浮。","應恨屬官無健令，異時佳節阻閑遊。"]', '["寒江九派轉城楼，东下鍾陵第一州。","人自中台方貴盛，地從西晉即风流。","旧班久望鵷晴翥，餘力猶闻虎夜浮。","應恨屬官無健令，異时佳節阻闲游。"]', '诗', 'shi', '', NULL, '上江州陳員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100c6eef-0d63-4fa6-8fde-4ddab28bdb2b', '廣陵開元寺閣上作', '廣陵开元寺閣上作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["滿檻山川漾落暉，檻前前事去如飛。","雲中雞犬劉安過，月裏笙歌煬帝歸。","江蹙海門帆散去，地吞淮口樹相依。","紅樓翠幕知多少，長向東風有是非。"]', '["满檻山川漾落暉，檻前前事去如飞。","云中雞犬劉安過，月裏笙歌煬帝归。","江蹙海门帆散去，地吞淮口樹相依。","紅楼翠幕知多少，长向东风有是非。"]', '诗', 'shi', '', NULL, '廣陵開元寺閣上作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7fc97e0-ced3-4dd4-a6bd-b13a4ffdc53c', '上鄂州韋尚書', '上鄂州韋尚书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["往歲先皇馭九州，侍臣才業最風流。","文窮典誥雖餘力，俗致雍熙盡密謀。","蘭省換班青作綬，柏臺前引絳爲韝。","都緣未負江山興，開濟生靈校一秋。"]', '["往歲先皇馭九州，侍臣才業最风流。","文窮典誥雖餘力，俗致雍熙尽密謀。","蘭省換班青作綬，柏台前引絳爲韝。","都緣未負江山兴，开濟生靈校一秋。"]', '诗', 'shi', '', NULL, '上鄂州韋尚書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5139f923-7a06-4ba7-9445-305ab4cbfd81', '早春巴陵道中', '早春巴陵道中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遠雪亭亭望未銷，岳陽春淺似相饒。","短蘆冒土初生笋，高柳偷風已弄條。","波汎洞庭㺍獺健，谷連荆楚鬼神妖。","中流菱唱泊何處，一隻畫船蘭作橈。"]', '["远雪亭亭望未銷，岳陽春淺似相饒。","短蘆冒土初生笋，高柳偷风已弄條。","波汎洞庭㺍獺健，谷連荆楚鬼神妖。","中流菱唱泊何处，一隻畫船蘭作橈。"]', '诗', 'shi', '', NULL, '早春巴陵道中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57834796-ca3b-48da-a2c4-479de7f577ac', '廣陵秋日酬進士臧濆見寄', '廣陵秋日酬進士臧濆见寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["驛西斜日滿窗前，獨凭秋欄思渺綿。","數尺斷蓬慚故國，一輪清鏡泣流年。","已知世事真徒爾，縱有心期亦偶然。","空媿荀家好兄弟，鴈來魚去是因緣。"]', '["驛西斜日满窗前，独凭秋欄思渺綿。","數尺斷蓬慚故国，一輪清镜泣流年。","已知世事真徒爾，縱有心期亦偶然。","空媿荀家好兄弟，鴈来鱼去是因緣。"]', '诗', 'shi', '', NULL, '廣陵秋日酬進士臧濆見寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ecfe6e-3519-4398-9c97-c88411d0c172', '淮南送李司空朝覲', '淮南送李司空朝覲', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["聖君宵旰望時雍，丹詔西來雨露濃。","宣父道高休歎鳳，武侯才大本吟龍。","九州似鼎終須負，萬物爲銅只待鎔。","臘後春前更何事，便看經度奏東封。"]', '["聖君宵旰望时雍，丹詔西来雨露濃。","宣父道高休歎鳳，武侯才大本吟龙。","九州似鼎終須負，万物爲銅只待鎔。","臘後春前更何事，便看經度奏东封。"]', '诗', 'shi', '', NULL, '淮南送李司空朝覲 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029aeaa0-04a3-44a0-acc3-9fde814364a1', '秋日禪智寺見裴郎中題名寄韋瞻', '秋日禪智寺见裴郎中題名寄韋瞻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["野寺疎鐘萬木秋，偶尋題處認名侯。","官離南郡應閑暇，地勝東山想駐留。","百醆濃醪成別夢，兩行垂露澣羈愁。","心知只有韋公在，更對真蹤話舊遊。"]', '["野寺疎鐘万木秋，偶尋題处認名侯。","官離南郡應闲暇，地勝东山想駐留。","百醆濃醪成別梦，兩行垂露澣羈愁。","心知只有韋公在，更对真蹤話旧游。"]', '诗', 'shi', '', NULL, '秋日禪智寺見裴郎中題名寄韋瞻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21648e35-1869-4ed9-b0ab-0164cbd5d350', '廣陵春日憶池陽有寄', '廣陵春日憶池陽有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["煙水濛濛接板橋，數年經歷駐征橈。","醉凭危檻波千頃，愁倚長亭柳萬條。","別後故人冠獬豸，病來知己賞鷦鷯。","清流夾宅千家住，會向閑乘一信潮。"]', '["煙水濛濛接板橋，數年經歷駐征橈。","醉凭危檻波千頃，愁倚长亭柳万條。","別後故人冠獬豸，病来知己賞鷦鷯。","清流夾宅千家住，會向闲乘一信潮。"]', '诗', 'shi', '', NULL, '廣陵春日憶池陽有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192c1e45-f73f-4022-bc3a-21c42d37f215', '春中湘中題岳麓寺僧舍', '春中湘中題岳麓寺僧舍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蟾宮虎穴兩皆休，來凭危欄送遠愁。","多事林鶯還謾語，薄情邊鴈不迴頭。","春融只待乾坤醉，水闊深知世界浮。","欲共高僧話心迹，野花芳草奈相尤。"]', '["蟾宮虎穴兩皆休，来凭危欄送远愁。","多事林鶯還謾語，薄情邊鴈不迴头。","春融只待乾坤醉，水闊深知世界浮。","欲共高僧話心迹，野花芳草奈相尤。"]', '诗', 'shi', '', NULL, '春中湘中題岳麓寺僧舍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a0fcbfe-77cb-4467-b71f-c3bd224770cc', '出試後投所知', '出試後投所知', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["此日蓬壺兩日程，當時消息甚分明。","桃須曼倩催方熟，橘待洪崖遣始行。","島外音書應有意，眼前塵士漸無情。","莫教更似山西鼠，嚙破愁腸恨一生。"]', '["此日蓬壺兩日程，當时消息甚分明。","桃須曼倩催方熟，橘待洪崖遣始行。","島外音书應有意，眼前塵士漸無情。","莫教更似山西鼠，嚙破愁腸恨一生。"]', '诗', 'shi', '', NULL, '出試後投所知 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de174f95-3f82-4ae0-8a51-72ed1433a535', '湘南春日懷古', '湘南春日懷古', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["晴江春暖蘭蕙薰，鳧鷖苒苒鷗著羣。","洛陽賈誼自無命，少陵杜甫兼有文。","空闊遠帆遮落日，蒼茫野樹礙歸雲。","松醪酒好昭潭靜，閑過中流一弔君。"]', '["晴江春暖蘭蕙薰，鳧鷖苒苒鷗著羣。","洛陽賈誼自無命，少陵杜甫兼有文。","空闊远帆遮落日，蒼茫野樹礙归云。","松醪酒好昭潭静，闲過中流一弔君。"]', '诗', 'shi', '', NULL, '湘南春日懷古 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e968ec9-1a22-460a-868e-6837ca27bb0b', '江州望廬山', '江州望廬山', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["東南蒼翠何崔嵬，橫流一望幽抱開。","影寒已令水底去，脚闊欲過湖心來。","深處不唯容鬼怪，暗中兼恐有風雷。","仙人往往今誰在，紅杏花香重首迴。"]', '["东南蒼翠何崔嵬，橫流一望幽抱开。","影寒已令水底去，脚闊欲過湖心来。","深处不唯容鬼怪，暗中兼恐有风雷。","仙人往往今誰在，紅杏花香重首迴。"]', '诗', 'shi', '', NULL, '江州望廬山 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d93cfde-5557-4ab8-b28f-808a3b59ebc3', '金陵寄竇尚書', '金陵寄竇尚书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["二年岐路有西東，長憶優游楚驛中。","虎帳談高無客繼，馬卿官傲少人同。","世危肯使依劉表，山好猶能憶謝公。","此去此恩言不得，謾將閑淚對春風。"]', '["二年岐路有西东，长憶優游楚驛中。","虎帳談高無客繼，马卿官傲少人同。","世危肯使依劉表，山好猶能憶謝公。","此去此恩言不得，謾將闲泪对春风。"]', '诗', 'shi', '', NULL, '金陵寄竇尚書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e6c438-0ac0-466b-978f-55406614eb6f', '清溪江令公宅', '清溪江令公宅', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蠻牋象管夜深時，曾賦陳宮第一詩。","宴罷風流人不見，廢來蹤跡草應知。","鶯憐勝事啼空巷，蜨戀餘香舞好枝。","還有往年金甃井，牧童樵叟等閑窺。"]', '["蠻牋象管夜深时，曾賦陳宮第一诗。","宴罷风流人不见，廢来蹤跡草應知。","鶯怜勝事啼空巷，蜨戀餘香舞好枝。","還有往年金甃井，牧童樵叟等闲窺。"]', '诗', 'shi', '', NULL, '清溪江令公宅 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3a753f-67ba-4020-8826-2963274a0f01', '鄭州獻盧舍人', '鄭州獻盧舍人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["海槎閑暇閬風輕，不是安流不肯行。","雞省露濃湯餅熟，鳳池煙暖詔書成。","漁籌已合光儒夢，堯印何妨且治兵。","會將兩都收復後，右圖儀表左題名。"]', '["海槎闲暇閬风轻，不是安流不肯行。","雞省露濃湯餅熟，鳳池煙暖詔书成。","漁籌已合光儒梦，堯印何妨且治兵。","會將兩都收复後，右圖儀表左題名。"]', '诗', 'shi', '', NULL, '鄭州獻盧舍人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b55463-0bd6-4860-a98b-52ff237f651b', '別池陽所居', '別池陽所居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["黃塵初起此留連，火耨刀耕六七年。","雨夜老農傷水旱，雪晴漁父共舟船。","已悲世亂身須去，肯媿途危跡屢遷。","却是九華山有意，列行相送到江邊。"]', '["黄塵初起此留連，火耨刀耕六七年。","雨夜老農傷水旱，雪晴漁父共舟船。","已悲世亂身須去，肯媿途危跡屢遷。","却是九华山有意，列行相送到江邊。"]', '诗', 'shi', '', NULL, '別池陽所居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c642c7-9100-4a82-ad7c-6e6f60419114', '送內使周大夫自杭州朝貢', '送內使周大夫自杭州朝貢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["八都上將近平戎，便附輶軒奏聖聰。","三接駕前朝覲禮，一函江表戰征功。","雲間閬苑何時見，水底瑤池觸處通。","知有殿庭餘力在，莫辭消息寄西風。"]', '["八都上將近平戎，便附輶軒奏聖聰。","三接駕前朝覲禮，一函江表戰征功。","云间閬苑何时见，水底瑤池觸处通。","知有殿庭餘力在，莫辞消息寄西风。"]', '诗', 'shi', '', NULL, '送內使周大夫自杭州朝貢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a30f782-738e-4dde-9d80-f5a917996397', '酬黃從事懷舊見寄', '酬黄從事懷旧见寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["舊遊不合到心中，把得君詩意亦同。","水館酒闌清夜月，香街人散白楊風。","長繩繫日雖難絆，辨口談天不易窮。","世事自隨蓬轉在，思量何處是飛蓬。"]', '["旧游不合到心中，把得君诗意亦同。","水館酒闌清夜月，香街人散白楊风。","长繩繫日雖难絆，辨口談天不易窮。","世事自隨蓬轉在，思量何处是飞蓬。"]', '诗', 'shi', '', NULL, '酬黃從事懷舊見寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c962f237-a2cc-4e62-a3a7-25b7417bf6dc', '繡', '繡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一片絲羅□□□，洞房西室女工勞。","花隨玉指添春色，鳥逐金鍼長羽毛。","蜀綿謾誇聲自貴，越綾虛說價功高。","可中用作鴛鴦被，紅葉枝枝不礙刀。"]', '["一片絲羅□□□，洞房西室女工勞。","花隨玉指添春色，鸟逐金鍼长羽毛。","蜀綿謾誇声自貴，越綾虛说價功高。","可中用作鴛鴦被，紅葉枝枝不礙刀。"]', '诗', 'shi', '', NULL, '繡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde7b687-57dd-4d31-9df6-54c0866898d0', '西施', '西施', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["家國興亡自有時，吳人何苦怨西施。","西施若解傾吳國，越國亡來又是誰。"]', '["家国兴亡自有时，吳人何苦怨西施。","西施若解傾吳国，越国亡来又是誰。"]', '诗', 'shi', '', NULL, '西施 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f5f07c-296e-4cb6-96a8-5ffdedb281a7', '自遣', '自遣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["得即高歌失即休，多愁多恨亦悠悠。","今朝有酒今朝醉，明日愁來明日愁。"]', '["得即高歌失即休，多愁多恨亦悠悠。","今朝有酒今朝醉，明日愁来明日愁。"]', '诗', 'shi', '', NULL, '自遣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18496a5-bf1d-46ba-aa86-5665375e216b', '白角箆', '白角箆', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["白似瓊瑤滑似苔，隨梳伴鏡拂塵埃。","莫言此箇尖頭物，幾度撩人惡髪來。"]', '["白似瓊瑤滑似苔，隨梳伴镜拂塵埃。","莫言此箇尖头物，幾度撩人惡髪来。"]', '诗', 'shi', '', NULL, '白角箆 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f2348b-aa54-4e2a-8d38-bb7ff2915aa3', '銅雀臺', '銅雀台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["強歌強舞竟難勝，花落花開淚滿膺。","秪合當年伴君死，免交憔悴望西陵。"]', '["強歌強舞竟难勝，花落花开泪满膺。","秪合當年伴君死，免交憔悴望西陵。"]', '诗', 'shi', '', NULL, '銅雀臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e682aca-7b51-4956-acc8-d5a1ccae3e67', '鸚鵡', '鸚鵡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["莫恨雕籠翠羽殘，江南地暖隴西寒。","勸君不用分明語，語得分明出轉難。"]', '["莫恨雕籠翠羽殘，江南地暖隴西寒。","勸君不用分明語，語得分明出轉难。"]', '诗', 'shi', '', NULL, '鸚鵡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('456b097e-1668-4610-9bae-c293ac126bc0', '金錢花', '金錢花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["占得佳名繞樹芳，依依相伴向秋光。","若教此物堪收貯，應被豪門盡劚將。"]', '["占得佳名繞樹芳，依依相伴向秋光。","若教此物堪收貯，應被豪门尽劚將。"]', '诗', 'shi', '', NULL, '金錢花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f204352-241f-417d-b73a-4343c4747bb3', '梅', '梅', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["天賜胭脂一抹腮，盤中磊落笛中哀。","雖然未得和羹便，曾與將軍止渴來。"]', '["天賜胭脂一抹腮，盤中磊落笛中哀。","雖然未得和羹便，曾與將軍止渴来。"]', '诗', 'shi', '', NULL, '梅 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b51918-4187-4fcb-8cc8-75fb9ec7ffd2', '錢尚父生日', '錢尚父生日', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["大昴分光降斗牛，興唐宗社作諸侯。","伊夔事業扶千載，韓白機謀冠九州。","貴盛上持龍節鉞，延長應續鶴春秋。","錦衣玉食將何報，更俟莊椿一舉頭。"]', '["大昴分光降斗牛，兴唐宗社作諸侯。","伊夔事業扶千載，韓白機謀冠九州。","貴盛上持龙節鉞，延长應續鹤春秋。","錦衣玉食將何報，更俟莊椿一舉头。"]', '诗', 'shi', '', NULL, '錢尚父生日 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f09284-25ae-4f76-b76a-fb673bb6ed77', '寄前戶部陸郎中', '寄前戶部陸郎中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["出馴桑雉入朝簪，蕭灑清名映士林。","近日篇章欺白雪，早年詞賦得黃金。","桂堂縱道探龍頷，蘭省何曾駐鶴心。","離亂事多人不會，酒濃花暖且閑吟。"]', '["出馴桑雉入朝簪，蕭灑清名映士林。","近日篇章欺白雪，早年词賦得黄金。","桂堂縱道探龙頷，蘭省何曾駐鹤心。","離亂事多人不會，酒濃花暖且闲吟。"]', '诗', 'shi', '', NULL, '寄前戶部陸郎中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b198d059-b980-4ecc-8ed9-c38c7e184aa6', '登瓦棺寺閣', '登瓦棺寺閣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["下盤空跡上雲浮，偶逐僧行步步愁。","暫憩已知須用意，漸來爭忍不回頭。","煙中樹老重江晚，鐸外風輕四境秋。","嬾指臺城更東望，鵲飛龍鬬盡荒丘。"]', '["下盤空跡上云浮，偶逐僧行步步愁。","暫憩已知須用意，漸来爭忍不回头。","煙中樹老重江晚，鐸外风轻四境秋。","嬾指台城更东望，鵲飞龙鬬尽荒丘。"]', '诗', 'shi', '', NULL, '登瓦棺寺閣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24d9b8f-386d-4ecc-a4d3-55c0804d3835', '九華山費徵君所居', '九华山費徵君所居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["草堂何處試徘徊，見說遺蹤向此開。","蟾桂自歸三徑後，鶴書曾降九天來。","白雲事跡依前在，青瑣光陰竟不迴。","盡夕爲君思曩日，野泉嗚咽路莓苔。"]', '["草堂何处試徘徊，见说遺蹤向此开。","蟾桂自归三徑後，鹤书曾降九天来。","白云事跡依前在，青瑣光陰竟不迴。","尽夕爲君思曩日，野泉嗚咽路莓苔。"]', '诗', 'shi', '', NULL, '九華山費徵君所居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c75c844-f3a0-4c3d-ae1f-6b5705ac4c85', '途中寄懷', '途中寄懷', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不知何處是前程，合眼騰騰信馬行。","兩鬢已衰時未遇，數峰雖在病相攖。","塵埃鞏洛虛光景，詩酒江湖漫姓名。","試哭軍門看誰問，舊來還似禰先生。"]', '["不知何处是前程，合眼腾腾信马行。","兩鬢已衰时未遇，數峰雖在病相攖。","塵埃鞏洛虛光景，诗酒江湖漫姓名。","試哭軍门看誰问，旧来還似禰先生。"]', '诗', 'shi', '', NULL, '途中寄懷 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a804e8-62f9-4c47-80bb-3915f9121b7a', '京口見李侍郎', '京口见李侍郎', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["傞傞江柳欲矜春，鐵甕城邊見故人。","屈指不堪言甲子，披風常記是庚申。","別來且喜身俱健，亂後休悲業盡貧。","還有杖頭沽酒物，待尋山寺話逡巡。"]', '["傞傞江柳欲矜春，鐵甕城邊见故人。","屈指不堪言甲子，披风常記是庚申。","別来且喜身俱健，亂後休悲業尽貧。","還有杖头沽酒物，待尋山寺話逡巡。"]', '诗', 'shi', '', NULL, '京口見李侍郎 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ab19da-bdc0-4fbc-a75b-62ada09c72af', '秋日酬張特玄', '秋日酬張特玄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["病寄南徐兩度秋，故人依約亦揚州。","偶因鴈足思閑事，擬棹孤舟訪舊遊。","風急幾聞江上笛，月高誰共酒家樓。","平生意氣消磨盡，甘露軒前看水流。"]', '["病寄南徐兩度秋，故人依約亦揚州。","偶因鴈足思闲事，擬棹孤舟訪旧游。","风急幾闻江上笛，月高誰共酒家楼。","平生意氣消磨尽，甘露軒前看水流。"]', '诗', 'shi', '', NULL, '秋日酬張特玄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f90da3-5fc8-4e09-b856-2c80a27a2f17', '登高詠菊盡', '登高詠菊尽', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["籬畔霜前偶得存，苦教遲晚避蘭蓀。","能銷造化幾多力，不受陽和一點恩。","生處豈容依玉砌，要時還許上金罇。","陶公沒後無知己，露滴幽叢見淚痕。"]', '["籬畔霜前偶得存，苦教遲晚避蘭蓀。","能銷造化幾多力，不受陽和一点恩。","生处豈容依玉砌，要时還許上金罇。","陶公沒後無知己，露滴幽叢见泪痕。"]', '诗', 'shi', '', NULL, '登高詠菊盡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e5e32c-8412-4701-9f07-b0cee0756dbe', '登夏州城樓', '登夏州城楼', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寒城獵獵戍旗風，獨倚危樓悵望中。","萬里山河唐土地，千年魂魄晉英雄。","離心不忍聽邊馬，往事應須問塞鴻。","好脫儒冠從校尉，一枝長戟六鈞弓。"]', '["寒城獵獵戍旗风，独倚危楼悵望中。","万里山河唐土地，千年魂魄晉英雄。","離心不忍听邊马，往事應須问塞鴻。","好脫儒冠從校尉，一枝长戟六鈞弓。"]', '诗', 'shi', '', NULL, '登夏州城樓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a66f66-b1de-4b37-ae64-b92e6aaa5e69', '水邊偶題', '水邊偶題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["野水無情去不回，水邊花好爲誰開。","只知事逐眼前去，不覺老從頭上來。","窮似丘軻休歎息，達如周召亦塵埃。","思量此理何人會，蒙邑先生最有才。"]', '["野水無情去不回，水邊花好爲誰开。","只知事逐眼前去，不覺老從头上来。","窮似丘軻休歎息，達如周召亦塵埃。","思量此理何人會，蒙邑先生最有才。"]', '诗', 'shi', '', NULL, '水邊偶題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef8f4a0-d61f-4ed9-b6a2-74f8dfb30a9b', '故洛陽公鎮大梁時隱得遊門下今之經歷事往人非聊抒所懷以傷以謝', '故洛陽公鎮大梁时隐得游门下今之經歷事往人非聊抒所懷以傷以謝', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["孤舟欲泊思何窮，曾憶西來值雪中。","珠履少年初滿座，白衣遊子也從公。","狂拋賦筆琉璃冷，醉倚歌筵瑇瑁紅。","今日斯文向誰說，淚碑棠樹兩成空。"]', '["孤舟欲泊思何窮，曾憶西来值雪中。","珠履少年初满座，白衣游子也從公。","狂拋賦笔琉璃冷，醉倚歌筵瑇瑁紅。","今日斯文向誰说，泪碑棠樹兩成空。"]', '诗', 'shi', '', NULL, '故洛陽公鎮大梁時隱得遊門下今之經歷事往人非聊抒所懷以傷以謝 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46825354-bda0-48c1-86df-04d40b0233dc', '杜陵秋思', '杜陵秋思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["南望商於北帝都，兩堪棲託兩無圖。","只聞斥逐張公子，不覺悲同楚大夫。","巖畔早涼生紫桂，井邊疎影落高梧。","一杯淥酒他年憶，瀝向青波寄五湖。"]', '["南望商於北帝都，兩堪棲託兩無圖。","只闻斥逐張公子，不覺悲同楚大夫。","巖畔早涼生紫桂，井邊疎影落高梧。","一杯淥酒他年憶，瀝向青波寄五湖。"]', '诗', 'shi', '', NULL, '杜陵秋思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5004da-4e92-4ea7-a130-3a62ad0cdc80', '隱嘗在江陵忝故中令白公叨蒙知遇今復重過渚宮感事悲身遂成長句', '隐嘗在江陵忝故中令白公叨蒙知遇今复重過渚宮感事悲身遂成长句', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["往歲酇侯鎮渚宮，曾將清律暖孤蓬。","才憐曼倩三冬後，藝許由基一箭中。","言重不能輕薄命，地寒終是泣春風。","鳳凰池涸台星拆，迴首岐山憶至公。"]', '["往歲酇侯鎮渚宮，曾將清律暖孤蓬。","才怜曼倩三冬後，藝許由基一箭中。","言重不能轻薄命，地寒終是泣春风。","鳳凰池涸台星拆，迴首岐山憶至公。"]', '诗', 'shi', '', NULL, '隱嘗在江陵忝故中令白公叨蒙知遇今復重過渚宮感事悲身遂成長句 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a9b920-b9ed-460f-b7c3-0f12fbc61597', '夜泊毘陵無錫縣有寄', '夜泊毘陵無錫縣有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["草蟲幽咽樹初團，獨繫孤舟夜已闌。","濁浪勢奔吳苑急，疎鐘聲徹惠山寒。","愁催鬢髪凋何易，貧戀家鄉別漸難。","他日親朋應大笑，始知書劒是無端。"]', '["草蟲幽咽樹初團，独繫孤舟夜已闌。","濁浪勢奔吳苑急，疎鐘声徹惠山寒。","愁催鬢髪凋何易，貧戀家乡別漸难。","他日親朋應大笑，始知书劒是無端。"]', '诗', 'shi', '', NULL, '夜泊毘陵無錫縣有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8302c621-3c77-4308-9542-e2003c831a70', '桃花', '桃花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["暖觸衣襟漠漠香，閒梅遮柳不勝芳。","數枝豔拂文君酒，半里紅欹宋玉牆。","盡日無人疑悵望，有時經雨乍淒涼。","舊山山下還如此，廻首東風一斷腸。"]', '["暖觸衣襟漠漠香，閒梅遮柳不勝芳。","數枝豔拂文君酒，半里紅欹宋玉牆。","尽日無人疑悵望，有时經雨乍淒涼。","旧山山下還如此，廻首东风一斷腸。"]', '诗', 'shi', '', NULL, '桃花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282a3626-fcad-43fc-81c3-7c6d616d7aca', '籌筆驛', '籌笔驛', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["拋擲南陽爲主憂，北征東討盡良籌。","時來天地皆同力，運去英雄不自由。","千里山河輕孺子，兩朝冠劒恨譙周。","唯餘巖下多情水，猶解年年傍驛流。"]', '["拋擲南陽爲主憂，北征东討尽良籌。","时来天地皆同力，運去英雄不自由。","千里山河轻孺子，兩朝冠劒恨譙周。","唯餘巖下多情水，猶解年年傍驛流。"]', '诗', 'shi', '', NULL, '籌筆驛 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7463fb4d-0d38-446a-95ca-28b8b305efb7', '重過隨州故兵部李侍郎恩知因抒長句', '重過隨州故兵部李侍郎恩知因抒长句', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["莊周高論伯牙琴，閑夜思量淚滿襟。","四海共誰言近事，九原從此負初心。","鷗翻漢浦風波急，鴈下鄖溪霧雨深。","慙媿蒼生還有意，解歌襦袴至如今。"]', '["莊周高論伯牙琴，闲夜思量泪满襟。","四海共誰言近事，九原從此負初心。","鷗翻漢浦风波急，鴈下鄖溪霧雨深。","慙媿蒼生還有意，解歌襦袴至如今。"]', '诗', 'shi', '', NULL, '重過隨州故兵部李侍郎恩知因抒長句 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b319d0c-9e24-401c-918e-90f328e78813', '商於驛樓東望有感', '商於驛楼东望有感', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["山川去接漢江東，曾伴隋侯醉此中。","歌繞夜梁珠宛轉，舞嬌春席雪朦朧。","棠遺善政陰猶在，薤送哀聲事已空。","惆悵知音竟難得，兩行清淚白楊風。"]', '["山川去接漢江东，曾伴隋侯醉此中。","歌繞夜梁珠宛轉，舞嬌春席雪朦朧。","棠遺善政陰猶在，薤送哀声事已空。","惆悵知音竟难得，兩行清泪白楊风。"]', '诗', 'shi', '', NULL, '商於驛樓東望有感 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba643b30-19e2-4219-b0b5-00b41ca5fbe3', '寄南城韋逸人', '寄南城韋逸人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["杜甫詩中韋曲花，至今無賴尚豪家。","美人曉折露沾袖，公子醉時香滿車。","萬里丹青傳不得，二年風雨恨無涯。","羨他南澗高眠客，春去春來任物華。"]', '["杜甫诗中韋曲花，至今無賴尚豪家。","美人晓折露沾袖，公子醉时香满车。","万里丹青傳不得，二年风雨恨無涯。","羨他南澗高眠客，春去春来任物华。"]', '诗', 'shi', '', NULL, '寄南城韋逸人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcca7f52-22eb-4259-b9a7-86e6dd1b6938', '梅花', '梅花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳王醉處十餘里，照野拂衣今正繁。","經雨不隨山鳥散，倚風疑共路人言。","愁憐粉豔飄歌席，靜愛寒香撲酒罇。","欲寄所思無好信，爲人惆恨又黃昏。"]', '["吳王醉处十餘里，照野拂衣今正繁。","經雨不隨山鸟散，倚风疑共路人言。","愁怜粉豔飄歌席，静愛寒香撲酒罇。","欲寄所思無好信，爲人惆恨又黄昏。"]', '诗', 'shi', '', NULL, '梅花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f345e4ae-4e49-4370-9a20-83dab7b30feb', '淮南高駢所造迎仙樓', '淮南高駢所造迎仙楼', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鸞音鶴信杳難迴，鳳駕龍車早晚來。","仙境是誰知處所，人間空自造樓臺。","雲侵朱檻應難到，蟲網閑窗永不開。","子細思量成底事，露凝風擺作塵埃。"]', '["鸾音鹤信杳难迴，鳳駕龙车早晚来。","仙境是誰知处所，人间空自造楼台。","云侵朱檻應难到，蟲網闲窗永不开。","子細思量成底事，露凝风擺作塵埃。"]', '诗', 'shi', '', NULL, '淮南高駢所造迎仙樓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eacb0e2-b501-4a74-9d95-7157411f3074', '和禪月大師見贈', '和禪月大師见贈', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["高僧惠我七言詩，頓豁塵心展白眉。","秀似谷中花媚日，清如潭底月圓時。","應觀法界蓮千葉，肯折人間桂一枝。","漂蕩秦吳十餘載，因循猶恨識師遲。"]', '["高僧惠我七言诗，頓豁塵心展白眉。","秀似谷中花媚日，清如潭底月圓时。","應观法界蓮千葉，肯折人间桂一枝。","漂蕩秦吳十餘載，因循猶恨識師遲。"]', '诗', 'shi', '', NULL, '和禪月大師見贈 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84926f6f-bc31-4657-9eda-faa140b3a4a9', '謁文宣王廟', '謁文宣王廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["晚來乘興謁先師，松柏淒淒人不知。","九仭蕭牆堆瓦礫，三間茅殿走狐狸。","雨淋狀似悲麟泣，露滴還同歎鳳悲。","儻使小儒名稍立，豈教吾道受栖遲。"]', '["晚来乘兴謁先師，松柏淒淒人不知。","九仭蕭牆堆瓦礫，三间茅殿走狐狸。","雨淋狀似悲麟泣，露滴還同歎鳳悲。","儻使小儒名稍立，豈教吾道受栖遲。"]', '诗', 'shi', '', NULL, '謁文宣王廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c0a387-0e79-4207-9e1f-0fa4f6c810e0', '代文宣王答', '代文宣王答', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["三教之中儒最尊，止戈爲武武尊文。","吾今尚自披蓑笠，你等何須讀典墳。","釋氏寶樓侵碧漢，道家宮殿拂青雲。","若教顏閔英靈在，終不羞他李老君。"]', '["三教之中儒最尊，止戈爲武武尊文。","吾今尚自披蓑笠，你等何須读典墳。","釋氏寶楼侵碧漢，道家宮殿拂青云。","若教顏閔英靈在，終不羞他李老君。"]', '诗', 'shi', '', NULL, '代文宣王答 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c9e3b8-9873-498e-aafe-767730ad8e09', '重送朗州張員外', '重送朗州張員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["朱輪此去正春風，且駐青雲聽斷蓬。","一榻早年容孺子，雙旌今日別文翁。","誠知汲善心長在，爭奈干時跡轉窮。","酬德酬恩兩無路，謾勞惆悵鳳城東。"]', '["朱輪此去正春风，且駐青云听斷蓬。","一榻早年容孺子，雙旌今日別文翁。","誠知汲善心长在，爭奈干时跡轉窮。","酬德酬恩兩無路，謾勞惆悵鳳城东。"]', '诗', 'shi', '', NULL, '重送朗州張員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f27ade-d6fc-4054-b48b-6d532251936a', '廣陵秋夜讀進士常修三篇因題', '廣陵秋夜读進士常修三篇因題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["入蜀歸吳三首詩，藏於笥篋重於師。","劒關夜讀相如聽，瓜步秋吟煬帝悲。","景物也知輸健筆，時情誰不許高枝。","明年二月春風裏，江島閑人慰所思。"]', '["入蜀归吳三首诗，藏於笥篋重於師。","劒关夜读相如听，瓜步秋吟煬帝悲。","景物也知輸健笔，时情誰不許高枝。","明年二月春风裏，江島闲人慰所思。"]', '诗', 'shi', '', NULL, '廣陵秋夜讀進士常修三篇因題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b742aada-da27-4eac-a72e-525d247710b4', '逼試投所知', '逼試投所知', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["桃在仙翁舊苑傍，暖煙輕靄撲人香。","十年此地頻偷眼，二月春風最斷腸。","曾恨夢中無好事，也知囊裏有仙方。","尋思仙骨終難得，始與回頭問玉皇。"]', '["桃在仙翁旧苑傍，暖煙轻靄撲人香。","十年此地頻偷眼，二月春风最斷腸。","曾恨梦中無好事，也知囊裏有仙方。","尋思仙骨終难得，始與回头问玉皇。"]', '诗', 'shi', '', NULL, '逼試投所知 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8709a4-746f-4baa-8ec2-ba4d8a33f0ed', '漢江上作', '漢江上作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["漢江波浪淥於苔，每到江邊病眼開。","半雨半風終日恨，無名無跡幾時迴。","雲生岸谷秋陰合，樹接帆檣晚思來。","對此空慚聖明代，忍教纓上有塵埃。"]', '["漢江波浪淥於苔，每到江邊病眼开。","半雨半风終日恨，無名無跡幾时迴。","云生岸谷秋陰合，樹接帆檣晚思来。","对此空慚聖明代，忍教纓上有塵埃。"]', '诗', 'shi', '', NULL, '漢江上作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f2aab5-c61c-47c6-823d-8a3bee66a995', '秋夜寄進士顧榮', '秋夜寄進士顧榮', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秋河耿耿夜沈沈，往事三更盡到心。","多病謾勞窺聖代，薄才終是費知音。","家山夢後帆千尺，塵土搔來髪一簪。","空羨良朋盡高價，可憐東箭與南金。"]', '["秋河耿耿夜沈沈，往事三更尽到心。","多病謾勞窺聖代，薄才終是費知音。","家山梦後帆千尺，塵土搔来髪一簪。","空羨良朋尽高價，可怜东箭與南金。"]', '诗', 'shi', '', NULL, '秋夜寄進士顧榮 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9bae62a-2375-49dd-bc16-f87c56ff4bdf', '寄渭北徐從事', '寄渭北徐從事', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["暖雲慵墮柳垂條，驄馬徐郎過渭橋。","官秩舊參荀祕監，罇罍今伴霍嫖姚。","科隨鵠箭頻曾中，禮向侯弓以重招。","莫恨東風促行李，不多時節却歸朝。"]', '["暖云慵墮柳垂條，驄马徐郎過渭橋。","官秩旧參荀祕監，罇罍今伴霍嫖姚。","科隨鵠箭頻曾中，禮向侯弓以重招。","莫恨东风促行李，不多时節却归朝。"]', '诗', 'shi', '', NULL, '寄渭北徐從事 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9690d8-210e-4fd3-8d15-940cb667b67c', '徐寇南逼感事獻江南知己次韻', '徐寇南逼感事獻江南知己次韻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["酒闌離思浩無窮，西望維揚憶數公。","萬里飄零身未了，一家知獎意曾同。","雲橫晉國塵應暗，路轉吳江信不通。","今日便成盧子諒，滿襟珠淚墮霜風。"]', '["酒闌離思浩無窮，西望維揚憶數公。","万里飄零身未了，一家知獎意曾同。","云橫晉国塵應暗，路轉吳江信不通。","今日便成盧子諒，满襟珠泪墮霜风。"]', '诗', 'shi', '', NULL, '徐寇南逼感事獻江南知己次韻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c652b9aa-0ac6-4540-8626-998427441552', '寄三衢孫員外', '寄三衢孫員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["小敷文伯見何時，南望三衢渴復飢。","天子未能崇典誥，諸生徒欲戀旌旗。","風高綠野苗千頃，露冷平樓酒滿巵。","盡是數旬陪奉處，使君爭肯不相思。"]', '["小敷文伯见何时，南望三衢渴复飢。","天子未能崇典誥，諸生徒欲戀旌旗。","风高綠野苗千頃，露冷平楼酒满巵。","尽是數旬陪奉处，使君爭肯不相思。"]', '诗', 'shi', '', NULL, '寄三衢孫員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00516f98-ea15-4848-8755-8c5cbd3e7bcf', '淮南送盧端公歸臺', '淮南送盧端公归台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鳳鸞勢逸九霄寬，北去南來任羽翰。","朱紱兩參王儉府，繡衣三領杜林官。","道從上國曾匡濟，才向牢盆始重難。","應笑張綱謾生事，埋輪不得在長安。"]', '["鳳鸾勢逸九霄寬，北去南来任羽翰。","朱紱兩參王儉府，繡衣三領杜林官。","道從上国曾匡濟，才向牢盆始重难。","應笑張綱謾生事，埋輪不得在长安。"]', '诗', 'shi', '', NULL, '淮南送盧端公歸臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109b216f-fc72-4d02-aae9-1830a8e50986', '煬帝陵', '煬帝陵', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["入郭登橋出郭船，紅樓日日柳年年。","君王忍把平陳業，只博雷塘數畝田。"]', '["入郭登橋出郭船，紅楼日日柳年年。","君王忍把平陳業，只博雷塘數畝田。"]', '诗', 'shi', '', NULL, '煬帝陵 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656306ec-e597-401b-bb9c-8967763151f5', '馬嵬坡', '马嵬坡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["佛屋前頭野草春，貴妃輕骨此爲塵。","從來絕色知難得，不破中原未是人。"]', '["佛屋前头野草春，貴妃轻骨此爲塵。","從来絕色知难得，不破中原未是人。"]', '诗', 'shi', '', NULL, '馬嵬坡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a935c45-8f29-496b-a6c7-0362682c8c5d', '柳', '柳', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["灞岸晴來送別頻，相偎相倚不勝春。","自家飛絮猶無定，爭解垂絲絆路人。"]', '["灞岸晴来送別頻，相偎相倚不勝春。","自家飞絮猶無定，爭解垂絲絆路人。"]', '诗', 'shi', '', NULL, '柳 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f0e0004-ed06-4c9b-966b-6b726215c8ea', '隋堤柳', '隋堤柳', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["夾路依依千里遙，路人回首認隋朝。","春風未借宣華意，猶費工夫長綠條。"]', '["夾路依依千里遙，路人回首認隋朝。","春风未借宣华意，猶費工夫长綠條。"]', '诗', 'shi', '', NULL, '隋堤柳 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a03df58-e9f4-4936-a6b5-a2ba5530cbf6', '孟浩然墓', '孟浩然墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["數步荒榛接舊蹊，寒江漠漠草淒淒。","鹿門黃土無多少，恰到書生塚便低。"]', '["數步荒榛接旧蹊，寒江漠漠草淒淒。","鹿门黄土無多少，恰到书生塚便低。"]', '诗', 'shi', '', NULL, '孟浩然墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adce9f9c-538c-45f2-938f-4d4143f4973c', '秦紀', '秦紀', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["長策東鞭及海隅，黿鼉奔起鬼神趨。","憐君未到沙丘日，肯信人間有死無。"]', '["长策东鞭及海隅，黿鼉奔起鬼神趨。","怜君未到沙丘日，肯信人间有死無。"]', '诗', 'shi', '', NULL, '秦紀 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6729c05a-c777-4a24-8be6-bc9d469c5bd2', '仙掌', '仙掌', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["掌前流水駐無塵，掌下軒車日日新。","謾向山頭高舉手，何曾招得路行人。"]', '["掌前流水駐無塵，掌下軒车日日新。","謾向山头高舉手，何曾招得路行人。"]', '诗', 'shi', '', NULL, '仙掌 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e266c5-d56f-4ed0-8d24-f076150762cf', '詠月', '詠月', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["湖上風高動白蘋，暫延清景此逡巡。","隔年違別成何事，半夜相看似故人。","蟾向靜中矜爪距，兔隈明處弄精神。","嫦娥老大應惆悵，倚泣蒼蒼桂一輪。"]', '["湖上风高动白蘋，暫延清景此逡巡。","隔年違別成何事，半夜相看似故人。","蟾向静中矜爪距，兔隈明处弄精神。","嫦娥老大應惆悵，倚泣蒼蒼桂一輪。"]', '诗', 'shi', '', NULL, '詠月 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47c8f00d-4417-4e61-93eb-203f19bdcb2c', '宿荆州江陵驛', '宿荆州江陵驛', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["西遊象闕媿知音，東下荆溪稱越吟。","風動芰荷香四散，月明樓閣影相侵。","閒欹別枕千般夢，醉送征帆萬里心。","薜荔衣裳木蘭檝，異時煙雨好追尋。"]', '["西游象闕媿知音，东下荆溪稱越吟。","风动芰荷香四散，月明楼閣影相侵。","閒欹別枕千般梦，醉送征帆万里心。","薜荔衣裳木蘭檝，異时煙雨好追尋。"]', '诗', 'shi', '', NULL, '宿荆州江陵驛 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0fbdee0-1149-4129-86f9-29414c55ba5c', '撫州別阮兵曹', '撫州別阮兵曹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雪晴天外見諸峰，幽軋行輪有去蹤。","內史宅邊今獨恨，步兵廚畔舊相容。","十年別鬢疑朝鏡，千里歸心著晚鐘。","若不他時更青眼，未知誰肯薦臨邛。"]', '["雪晴天外见諸峰，幽軋行輪有去蹤。","內史宅邊今独恨，步兵廚畔旧相容。","十年別鬢疑朝镜，千里归心著晚鐘。","若不他时更青眼，未知誰肯薦臨邛。"]', '诗', 'shi', '', NULL, '撫州別阮兵曹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9476a76-abc6-45b4-b36e-94847f866e9f', '新安投所知', '新安投所知', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["少年容易捨樵漁，曾辱明公薦子虛。","漢殿寒夜時不食，宋都風急命何疎。","雲埋野艇吟歸去，草沒山田賦遂初。","長劒一尋歌一奏，此心爭肯爲鱸魚。"]', '["少年容易捨樵漁，曾辱明公薦子虛。","漢殿寒夜时不食，宋都风急命何疎。","云埋野艇吟归去，草沒山田賦遂初。","长劒一尋歌一奏，此心爭肯爲鱸鱼。"]', '诗', 'shi', '', NULL, '新安投所知 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6caa5b9-9b73-41eb-b973-68037062e935', '江邊有寄', '江邊有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江邊舊業半彫殘，每軫歸心即萬端。","狂折野梅山店暖，醉吹村笛酒樓寒。","只言聖代謀身易，爭奈貧儒得路難。","同病同憂更何事，爲君提筆畫漁竿。"]', '["江邊旧業半彫殘，每軫归心即万端。","狂折野梅山店暖，醉吹村笛酒楼寒。","只言聖代謀身易，爭奈貧儒得路难。","同病同憂更何事，爲君提笔畫漁竿。"]', '诗', 'shi', '', NULL, '江邊有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f54a309-e8ea-435c-a619-761d42169ff5', '送友人歸夷門', '送友人归夷门', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["二年流落大梁城，每送君歸即有情。","別路算來成底事，舊遊言著似前生。","苑荒嬾認詞人會，門在空憐烈士名。","至竟男兒分應定，不須惆悵谷中鶯。"]', '["二年流落大梁城，每送君归即有情。","別路算来成底事，旧游言著似前生。","苑荒嬾認词人會，门在空怜烈士名。","至竟男兒分應定，不須惆悵谷中鶯。"]', '诗', 'shi', '', NULL, '送友人歸夷門 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9292b45-fde7-41c4-a79d-6219186cd031', '湘中見進士喬詡', '湘中见進士喬詡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳公臺下別經秋，破虜城邊暫駐留。","一笑有情堪解夢，數年無故不同遊。","雲牽楚思橫魚艇，柳送鄉心入酒樓。","且酌松醪依舊醉，誰能相見向春愁。"]', '["吳公台下別經秋，破虜城邊暫駐留。","一笑有情堪解梦，數年無故不同游。","云牽楚思橫鱼艇，柳送乡心入酒楼。","且酌松醪依旧醉，誰能相见向春愁。"]', '诗', 'shi', '', NULL, '湘中見進士喬詡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598adc93-bfca-4bf3-be85-a5048ec4bcca', '上霅川裴郎中', '上霅川裴郎中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["貴提金印出咸秦，瀟灑江城兩度春。","一派水清疑見膽，數重山翠欲留人。","望崇早合歸黃閣，詩好何妨戀白蘋。","自是受恩心未足，却垂雙翅羨吳均。"]', '["貴提金印出咸秦，瀟灑江城兩度春。","一派水清疑见膽，數重山翠欲留人。","望崇早合归黄閣，诗好何妨戀白蘋。","自是受恩心未足，却垂雙翅羨吳均。"]', '诗', 'shi', '', NULL, '上霅川裴郎中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d703eb74-ba16-42cc-b86c-d7433fdfa7e8', '錢塘江潮', '錢塘江潮', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["怒聲洶洶勢悠悠，羅剎江邊地欲浮。","漫道往來存大信，也知反覆向平流。","任拋巨浸疑無底，猛過西陵只有頭。","至竟朝昏誰主掌，好騎赬鯉問陽侯。"]', '["怒声洶洶勢悠悠，羅剎江邊地欲浮。","漫道往来存大信，也知反覆向平流。","任拋巨浸疑無底，猛過西陵只有头。","至竟朝昏誰主掌，好騎赬鯉问陽侯。"]', '诗', 'shi', '', NULL, '錢塘江潮 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ac046b-bd19-489b-919d-563595326370', '送人赴職任褒中', '送人赴職任褒中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["物態時情難重陳，夫君此去莫傷春。","男兒只要有知己，才子何堪更問津。","萬轉江山通蜀國，兩行珠翠見褒人。","海棠花謝東風老，應念京都共苦辛。"]', '["物態时情难重陳，夫君此去莫傷春。","男兒只要有知己，才子何堪更问津。","万轉江山通蜀国，兩行珠翠见褒人。","海棠花謝东风老，應念京都共苦辛。"]', '诗', 'shi', '', NULL, '送人赴職任褒中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31d2a65-13f0-4242-81c3-0c205d2b9486', '臨川投穆中丞', '臨川投穆中丞', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["試將生計問蓬根，心委寒灰首戴盆。","翅弱未知三島路，舌頑虛掉五侯門。","嘯煙白狖沈高木，擣月清砧觸旅魂。","家在碧江歸不得，十年魚艇長苔痕。"]', '["試將生計问蓬根，心委寒灰首戴盆。","翅弱未知三島路，舌頑虛掉五侯门。","嘯煙白狖沈高木，擣月清砧觸旅魂。","家在碧江归不得，十年鱼艇长苔痕。"]', '诗', 'shi', '', NULL, '臨川投穆中丞 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6640c0c-32b0-48f7-adbd-6709ec39ea77', '早春送張坤歸大梁', '早春送張坤归大梁', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蕭蕭羸馬正塵埃，又送輶軒向吹臺。","別酒莫辭今夜醉，故人知是幾時回。","泉經華岳猶應凍，花到梁園始合開。","爲謝東門抱關吏，不堪惆悵滿離杯。"]', '["蕭蕭羸马正塵埃，又送輶軒向吹台。","別酒莫辞今夜醉，故人知是幾时回。","泉經华岳猶應凍，花到梁园始合开。","爲謝东门抱关吏，不堪惆悵满離杯。"]', '诗', 'shi', '', NULL, '早春送張坤歸大梁 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d59a44-af3e-40cc-ab1e-5baef4aa0737', '東歸途中作', '东归途中作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["松橘蒼黃覆釣磯，早年生計近年違。","老知風月終堪恨，貧覺家山不易歸。","別岸客帆和鴈落，晚程霜葉向人飛。","買臣嚴助精靈在，應笑無成一布衣。"]', '["松橘蒼黄覆釣磯，早年生計近年違。","老知风月終堪恨，貧覺家山不易归。","別岸客帆和鴈落，晚程霜葉向人飞。","買臣嚴助精靈在，應笑無成一布衣。"]', '诗', 'shi', '', NULL, '東歸途中作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2384ff33-19d4-4417-a53b-dd3640722046', '送進士臧濆下第後歸池州', '送進士臧濆下第後归池州', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["賦成無處換黃金，却向春風動越吟。","天子愛才雖仄席，諸生多病又沾襟。","柳攀灞岸狂遮袂，水憶池陽淥滿心。","珍重綵衣歸正好，莫將閑事繫升沈。"]', '["賦成無处換黄金，却向春风动越吟。","天子愛才雖仄席，諸生多病又沾襟。","柳攀灞岸狂遮袂，水憶池陽淥满心。","珍重綵衣归正好，莫將闲事繫升沈。"]', '诗', 'shi', '', NULL, '送進士臧濆下第後歸池州 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17df864-ff93-4234-8565-45dbab852beb', '湘中贈范鄖', '湘中贈范鄖', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["丹桂無心彼此諳，二年疎嬾共江潭。","愁知酒醆終難捨，老覺人情轉不堪。","雲外鴛鴦非故舊，眼前膠漆似煙嵐。","勞歌一曲霜風暮，擊折湘妃白玉簪。"]', '["丹桂無心彼此諳，二年疎嬾共江潭。","愁知酒醆終难捨，老覺人情轉不堪。","云外鴛鴦非故旧，眼前膠漆似煙嵐。","勞歌一曲霜风暮，擊折湘妃白玉簪。"]', '诗', 'shi', '', NULL, '湘中贈范鄖 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50b42bf-ebbc-4adb-8a5a-47db62eee71c', '寄張侍郎', '寄張侍郎', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["衰羸豈合話荆州，爭奈思多不自由。","無路重趨桓典馬，有詩曾上仲宣樓。","塵銷別跡堪垂淚，樹拂他門嬾舉頭。","一種人間太平日，獨教零落憶滄州。"]', '["衰羸豈合話荆州，爭奈思多不自由。","無路重趨桓典马，有诗曾上仲宣楼。","塵銷別跡堪垂泪，樹拂他门嬾舉头。","一種人间太平日，独教零落憶滄州。"]', '诗', 'shi', '', NULL, '寄張侍郎 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2eb811-aed9-4712-ba96-a7ef06c0d4c3', '渚宮秋思', '渚宮秋思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["楚城日暮煙靄深，楚人駐馬還登臨。","襄王臺下水無賴，神女廟前雲有心。","千載是非難重問，一江風雨好閑吟。","欲招屈宋當時魄，蘭敗荷枯不可尋。"]', '["楚城日暮煙靄深，楚人駐马還登臨。","襄王台下水無賴，神女廟前云有心。","千載是非难重问，一江风雨好闲吟。","欲招屈宋當时魄，蘭敗荷枯不可尋。"]', '诗', 'shi', '', NULL, '渚宮秋思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3723f8d8-27d0-4aff-9df6-34c9430afec0', '閑居早秋', '闲居早秋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["槐杪清蟬煙雨餘，蕭蕭涼葉墮衣裾。","噪槎烏散沈蒼嶺，弄杵風高上碧虛。","百歲夢生悲蛺蜨，一朝香死泣芙蕖。","六宮誰買相如賦，團扇恩情日日疎。"]', '["槐杪清蟬煙雨餘，蕭蕭涼葉墮衣裾。","噪槎烏散沈蒼嶺，弄杵风高上碧虛。","百歲梦生悲蛺蜨，一朝香死泣芙蕖。","六宮誰買相如賦，團扇恩情日日疎。"]', '诗', 'shi', '', NULL, '閑居早秋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f23f6c-4575-4dbf-b621-392c22beef99', '建康', '建康', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["潮平遠岸草侵沙，東晉衰來最可嗟。","庾舅已能窺帝室，王都還是預人家。","山寒老樹啼風曲，泉暖枯骸動芷牙。","欲起九原看一徧，秦淮聲急日西斜。"]', '["潮平远岸草侵沙，东晉衰来最可嗟。","庾舅已能窺帝室，王都還是預人家。","山寒老樹啼风曲，泉暖枯骸动芷牙。","欲起九原看一徧，秦淮声急日西斜。"]', '诗', 'shi', '', NULL, '建康 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df6f1cf-96fc-4341-b1e7-09d703ea95a6', '送舒州宿松縣傅少府', '送舒州宿松縣傅少府', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江蘺漠漠樹重重，東過清淮到宿松。","縣好也知臨浣水，官閑應得看灊峰。","春風綠野吳歌怨，雪霽平郊楚酒濃。","留取餘杯待張翰，明年歸棹一從容。"]', '["江蘺漠漠樹重重，东過清淮到宿松。","縣好也知臨浣水，官闲應得看灊峰。","春风綠野吳歌怨，雪霽平郊楚酒濃。","留取餘杯待張翰，明年归棹一從容。"]', '诗', 'shi', '', NULL, '送舒州宿松縣傅少府 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('943080c5-852b-47ea-a2b2-9cd2e194719d', '經故洛陽城', '經故洛陽城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["敗垣危堞跡依稀，試駐羸驂弔落暉。","跋扈以成梁冀在，簡書難問杜喬歸。","由來世事須翻覆，未必餘才解是非。","千載昆陽好功業，與君門下作恩威。"]', '["敗垣危堞跡依稀，試駐羸驂弔落暉。","跋扈以成梁冀在，簡书难问杜喬归。","由来世事須翻覆，未必餘才解是非。","千載昆陽好功業，與君门下作恩威。"]', '诗', 'shi', '', NULL, '經故洛陽城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aab3187-1815-49eb-9072-3df6036c2988', '夏州胡常侍', '夏州胡常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["百尺高臺勃勃州，大刀長戟漢諸侯。","征鴻過盡邊雲闊，戰馬閑來塞草秋。","國計已推肝膽許，家財不爲子孫謀。","仍聞隴蜀由多事，深喜將軍未白頭。"]', '["百尺高台勃勃州，大刀长戟漢諸侯。","征鴻過尽邊云闊，戰马闲来塞草秋。","国計已推肝膽許，家財不爲子孫謀。","仍闻隴蜀由多事，深喜將軍未白头。"]', '诗', 'shi', '', NULL, '夏州胡常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('497b1b34-1b9e-47a8-a971-9ee55f53470c', '寄進士盧休', '寄進士盧休', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["半年池口恨萍蓬，今日思量已夢中。","遊子馬蹄難重到，故人尊酒與誰同。","山橫翠後千重綠，蠟想歌時一燼紅。","從此客程君不見，麥秋梅雨徧江東。"]', '["半年池口恨萍蓬，今日思量已梦中。","游子马蹄难重到，故人尊酒與誰同。","山橫翠後千重綠，蠟想歌时一燼紅。","從此客程君不见，麦秋梅雨徧江东。"]', '诗', 'shi', '', NULL, '寄進士盧休 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59341040-7f21-497f-a7a5-bfbdcd1cd6e5', '贈先輩令狐補闕', '贈先輩令狐補闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中間聲跡早薰然，阻避鈞衡過十年。","碧海浪高終濟物，蒼梧雲好已歸天。","花迎綵服離鶯谷，柳傍東風觸馬鞭。","應念淒涼洞庭客，夜深雙淚憶漁船。"]', '["中间声跡早薰然，阻避鈞衡過十年。","碧海浪高終濟物，蒼梧云好已归天。","花迎綵服離鶯谷，柳傍东风觸马鞭。","應念淒涼洞庭客，夜深雙泪憶漁船。"]', '诗', 'shi', '', NULL, '贈先輩令狐補闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe585c2-58ba-4dd7-ad20-f8f6df7805b2', '送秦州從事', '送秦州從事', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一枝何足解人愁，拋却還隨定遠侯。","紫陌紅塵今別恨，九衢雙闕夜同遊。","芳時易失勞行止，良會難期且駐留。","若到邊庭有來使，試批書尾話梁州。"]', '["一枝何足解人愁，拋却還隨定远侯。","紫陌紅塵今別恨，九衢雙闕夜同游。","芳时易失勞行止，良會难期且駐留。","若到邊庭有来使，試批书尾話梁州。"]', '诗', 'shi', '', NULL, '送秦州從事 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb3c751-ed46-4634-bfaa-e07ccc696efe', '湖州裴郎中赴闕後投簡寄友生', '湖州裴郎中赴闕後投簡寄友生', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["錦帳郎官塞詔年，汀州曾駐木蘭船。","禰衡酒醒春瓶倒，柳惲詩成海月圓。","歌蹙遠山珠滴滴，漏催香燭淚漣漣。","使君入拜吾徒在，宣室他時豈偶然。"]', '["錦帳郎官塞詔年，汀州曾駐木蘭船。","禰衡酒醒春瓶倒，柳惲诗成海月圓。","歌蹙远山珠滴滴，漏催香燭泪漣漣。","使君入拜吾徒在，宣室他时豈偶然。"]', '诗', 'shi', '', NULL, '湖州裴郎中赴闕後投簡寄友生 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca5a4eb-2ac8-4426-8e47-5d5681dcb9fc', '秋日泊平望驛寄太常裴郎中', '秋日泊平望驛寄太常裴郎中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蘋洲重到杳難期，西倚郵亭憶往時。","北海尊中常有酒，東陽樓上豈無詩。","地清每負生靈望，官重方升禮樂司。","聞說江南舊歌曲，至今猶自唱吳姬。"]', '["蘋洲重到杳难期，西倚郵亭憶往时。","北海尊中常有酒，东陽楼上豈無诗。","地清每負生靈望，官重方升禮乐司。","闻说江南旧歌曲，至今猶自唱吳姬。"]', '诗', 'shi', '', NULL, '秋日泊平望驛寄太常裴郎中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce1451f-5e44-4ebb-80ea-6f0c6c91d5e9', '西塞山', '西塞山', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳塞當時指此山，吳都亡後綠孱顏。","嶺梅乍暖殘妝恨，沙鳥初晴小隊閑。","波闊魚龍應混雜，壁危猿狖奈姦頑。","會將一副寒蓑笠，來與漁翁作往還。"]', '["吳塞當时指此山，吳都亡後綠孱顏。","嶺梅乍暖殘妝恨，沙鸟初晴小隊闲。","波闊鱼龙應混杂，壁危猿狖奈姦頑。","會將一副寒蓑笠，来與漁翁作往還。"]', '诗', 'shi', '', NULL, '西塞山 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebff189e-a2fa-42e8-a008-827abb2b0ff3', '秋日汴河客舍酬友人', '秋日汴河客舍酬友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["梁宋追遊早歲同，偶然違別事皆空。","年如流水催何急，道似危途動即窮。","醉舞且欣連夜月，狂吟還聚上樓風。","煩君更枉騷人句，白鳳靈虵滿袖中。"]', '["梁宋追游早歲同，偶然違別事皆空。","年如流水催何急，道似危途动即窮。","醉舞且欣連夜月，狂吟還聚上楼风。","煩君更枉騷人句，白鳳靈虵满袖中。"]', '诗', 'shi', '', NULL, '秋日汴河客舍酬友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2e79a1-e504-422a-90c4-c398bc9dc47d', '東歸', '东归', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["仙桂高高似有神，貂裘敝盡取無因。","難將白髮期公道，不覺丹枝屬別人。","雙闕往來慙請謁，五湖歸後恥交親。","盈盤紫蟹千巵酒，添得臨岐淚滿巾。"]', '["仙桂高高似有神，貂裘敝尽取無因。","难將白髮期公道，不覺丹枝屬別人。","雙闕往来慙請謁，五湖归後恥交親。","盈盤紫蟹千巵酒，添得臨岐泪满巾。"]', '诗', 'shi', '', NULL, '東歸 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96f3c83-6ec5-4523-9d33-782f7129f4b2', '廣陵李僕射借示近詩因投獻', '廣陵李僕射借示近诗因投獻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["朝論國計暮論兵，餘力猶隨鳳藻生。","語繼盤盂拋俗格，氣兼河岳帶商聲。","閑尋綺思千花麗，靜想高吟六義清。","天柄已持堯典在，更堪回首問緣情。"]', '["朝論国計暮論兵，餘力猶隨鳳藻生。","語繼盤盂拋俗格，氣兼河岳带商声。","闲尋綺思千花丽，静想高吟六義清。","天柄已持堯典在，更堪回首问緣情。"]', '诗', 'shi', '', NULL, '廣陵李僕射借示近詩因投獻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397d8aed-01e9-4f40-93b8-1dd63636e148', '三衢哭孫員外', '三衢哭孫員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["燕戀雕梁馬戀軒，此心從此更何言。","直將塵外三生命，未敵君侯一日恩。","紅蠟有時還入夢，片帆何處獨銷魂？","忍看明發衣襟上，珠淚痕中見酒痕。"]', '["燕戀雕梁马戀軒，此心從此更何言。","直將塵外三生命，未敵君侯一日恩。","紅蠟有时還入梦，片帆何处独銷魂？","忍看明發衣襟上，珠泪痕中见酒痕。"]', '诗', 'shi', '', NULL, '三衢哭孫員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af82dc0f-3a0c-4ff4-bd21-c9309f4a7de5', '篋中得故王郎中書', '篋中得故王郎中书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鳳里前年別望郎，丁寧唯恐滯吳鄉。","勸疎杯酒知妨事，乞與書題作裹糧。","苹鹿未能移海曲，縣花尋已落河陽。","九原自此無因見，反覆遺蹤淚萬行。"]', '["鳳里前年別望郎，丁寧唯恐滯吳乡。","勸疎杯酒知妨事，乞與书題作裹糧。","苹鹿未能移海曲，縣花尋已落河陽。","九原自此無因见，反覆遺蹤泪万行。"]', '诗', 'shi', '', NULL, '篋中得故王郎中書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4cfc91-a317-437e-b1db-e814d9f7e6bb', '淚', '泪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["逼臉橫頤咽復勻，也曾讒毀也傷神。","自從魯國潸然後，不是姦人即婦人。"]', '["逼臉橫頤咽复勻，也曾讒毀也傷神。","自從魯国潸然後，不是姦人即婦人。"]', '诗', 'shi', '', NULL, '淚 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8ce2d8-72a5-47ed-a33e-ed9d7b3620ad', '子規', '子規', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["銅梁路遠草青青，此恨那堪枕上聽。","一種有冤猶可報，不如銜石疊滄溟。"]', '["銅梁路远草青青，此恨那堪枕上听。","一種有冤猶可報，不如銜石叠滄溟。"]', '诗', 'shi', '', NULL, '子規 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158f4c90-4cfe-425b-bf44-32d9a286cd08', '姑蘇臺', '姑蘇台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["讓高泰伯開基日，賢見延陵復命時。","未會子孫因底事，解崇臺榭爲西施。"]', '["讓高泰伯开基日，賢见延陵复命时。","未會子孫因底事，解崇台榭爲西施。"]', '诗', 'shi', '', NULL, '姑蘇臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50426bd-bae7-4cf5-8087-f5be82570c53', '王濬墓', '王濬墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["男兒未必盡英雄，但到時來即命通。","若使吳都猶王氣，將軍何處立殊功。"]', '["男兒未必尽英雄，但到时来即命通。","若使吳都猶王氣，將軍何处立殊功。"]', '诗', 'shi', '', NULL, '王濬墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5bdc9f-bf16-4e43-b9ce-bcd65348d156', '京中晚望', '京中晚望', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["心如野鹿跡如萍，謾向人間性一靈。","往事不知多少夢，夜來和酒一時醒。"]', '["心如野鹿跡如萍，謾向人间性一靈。","往事不知多少梦，夜来和酒一时醒。"]', '诗', 'shi', '', NULL, '京中晚望 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df280adc-ffab-48b3-b3bb-affe22a73caf', '寄竇澤處士二首 一', '寄竇澤处士二首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蘭亭醉客舊知聞，欲問平安隔海雲。","不是金陵錢太尉，世事誰肯更容身。"]', '["蘭亭醉客旧知闻，欲问平安隔海云。","不是金陵錢太尉，世事誰肯更容身。"]', '诗', 'shi', '', NULL, '寄竇澤處士二首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cae4e5-5bc8-487d-8dbc-e998dfe8553e', '寄竇澤處士二首 二', '寄竇澤处士二首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鼇背樓臺拂白榆，此中槎客亦踟躕。","牢山道士無仙骨，却向人間作酒徒。"]', '["鼇背楼台拂白榆，此中槎客亦踟躕。","牢山道士無仙骨，却向人间作酒徒。"]', '诗', 'shi', '', NULL, '寄竇澤處士二首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e37b9d8-3ea8-485f-adf2-a3a01f08d803', '省試秋風生桂枝', '省試秋风生桂枝', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["涼吹從何起，中宵景象清。","漫隨雲葉動，高傍桂枝生。","漠漠看無際，蕭蕭別有聲。","遠吹斜漢轉，低拂白榆輕。","寥泬工夫大，乾坤歲序更。","因悲遠歸客，長望一枝榮。"]', '["涼吹從何起，中宵景象清。","漫隨云葉动，高傍桂枝生。","漠漠看無際，蕭蕭別有声。","远吹斜漢轉，低拂白榆轻。","寥泬工夫大，乾坤歲序更。","因悲远归客，长望一枝榮。"]', '诗', 'shi', '', NULL, '省試秋風生桂枝 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde97bac-83f5-400a-9678-88b15d2de8ed', '思故人', '思故人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["故人不可見，聊復拂鳴琴。","鵲繞風枝急，螢藏露草深。","平生四方志，此夜五湖心。","惆悵友朋盡，洋洋漫好音。"]', '["故人不可见，聊复拂鳴琴。","鵲繞风枝急，螢藏露草深。","平生四方志，此夜五湖心。","惆悵友朋尽，洋洋漫好音。"]', '诗', 'shi', '', NULL, '思故人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be478254-6ea4-4a09-9338-b4b3e6f68f5c', '寄陸龜蒙', '寄陸龟蒙', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["龍樓李丞相，昔歲仰高文。","黃閣尋無主，青山竟未焚。","夜船乘海月，秋寺伴江雲。","却恐塵埃裏，浮名點污君。"]', '["龙楼李丞相，昔歲仰高文。","黄閣尋無主，青山竟未焚。","夜船乘海月，秋寺伴江云。","却恐塵埃裏，浮名点污君。"]', '诗', 'shi', '', NULL, '寄陸龜蒙 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd05c77-a74d-4137-9ab9-13aa44f9249c', '題方干詩', '題方干诗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中間李建州，夏汭偶同遊。","顧我論佳句，推君最上流。","九霄無鶴板，雙鬢老漁舟。","世難方如此，何當浣旅愁。"]', '["中间李建州，夏汭偶同游。","顧我論佳句，推君最上流。","九霄無鹤板，雙鬢老漁舟。","世难方如此，何當浣旅愁。"]', '诗', 'shi', '', NULL, '題方干詩 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b819eb-f3d9-43b1-a8ff-510bf02fb397', '秋江', '秋江', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秋江待晚潮，客歸斾旌搖。","細雨翻蘆葉，高風却柳條。","兵戈村落破，饑儉虎狼驕。","吾土兼連此，離魂望裏消。"]', '["秋江待晚潮，客归斾旌搖。","細雨翻蘆葉，高风却柳條。","兵戈村落破，饑儉虎狼驕。","吾土兼連此，離魂望裏消。"]', '诗', 'shi', '', NULL, '秋江 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74bb3931-e96a-4d7d-97c1-f635abe052f0', '寄制誥李舍人', '寄制誥李舍人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["梁王握豹韜，雪裏見枚臯。","上客趨丹陛，遊人歎二毛。","門閑知待詔，星動想濡毫。","一首長楊賦，應嫌索價高。"]', '["梁王握豹韜，雪裏见枚臯。","上客趨丹陛，游人歎二毛。","门闲知待詔，星动想濡毫。","一首长楊賦，應嫌索價高。"]', '诗', 'shi', '', NULL, '寄制誥李舍人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8aba680-09a8-4db6-9639-b370f25d2a89', '秋日懷孟夷庚', '秋日懷孟夷庚', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秋日黃陂下，孤舟憶共誰。","江山三分楚，風雨二妃祠。","知己秦貂沒，流年賈鵩悲。"]', '["秋日黄陂下，孤舟憶共誰。","江山三分楚，风雨二妃祠。","知己秦貂沒，流年賈鵩悲。"]', '诗', 'shi', '', NULL, '秋日懷孟夷庚 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37349bd5-df05-478f-a312-0f80b060d972', '送李右丞分司', '送李右丞分司', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["分漕得洛川，讜議更昭然。","在省曾批敕，中臺肯避權。","所悲時漸薄，共賀道由全。","賣與清平代，相兼直幾錢。"]', '["分漕得洛川，讜議更昭然。","在省曾批敕，中台肯避權。","所悲时漸薄，共賀道由全。","賣與清平代，相兼直幾錢。"]', '诗', 'shi', '', NULL, '送李右丞分司 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9cf968-9a0c-4df8-9bbd-dfeb8c2fba21', '郴江遷客', '郴江遷客', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不是逢清世，何由見皂囊。","事雖危虎尾，名勝泊鵷行。","毒霧郴江闊，愁雲楚驛長。","歸時有詩賦，一爲弔沈湘。"]', '["不是逢清世，何由见皂囊。","事雖危虎尾，名勝泊鵷行。","毒霧郴江闊，愁云楚驛长。","归时有诗賦，一爲弔沈湘。"]', '诗', 'shi', '', NULL, '郴江遷客 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467d64c8-a182-4939-8cac-65c10d4cea3b', '感舊', '感旧', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["劒佩孫弘閣，戈鋋太尉營。","重言虛有位，孤立竟無成。","丘隴笳簫咽，池臺歲月平。","此恩何以報，歸處是柴荆。"]', '["劒佩孫弘閣，戈鋋太尉營。","重言虛有位，孤立竟無成。","丘隴笳簫咽，池台歲月平。","此恩何以報，归处是柴荆。"]', '诗', 'shi', '', NULL, '感舊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eac8763-a9f9-4d87-837d-572185bcb594', '鷹', '鷹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["越海霜天暮，辭韜野草乾。","俊通司隸職，嚴奉武夫官。","眼惡藏蜂在，心麤逐物殫。","近來脂膩足，驅遣不妨難。"]', '["越海霜天暮，辞韜野草乾。","俊通司隸職，嚴奉武夫官。","眼惡藏蜂在，心麤逐物殫。","近来脂膩足，驱遣不妨难。"]', '诗', 'shi', '', NULL, '鷹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4142ae0c-d062-451b-952d-3456b909d19a', '秋日寄狄補闕', '秋日寄狄補闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["紅塵擾擾間，立馬看南山。","謾道經年往，何妨逐日閑。","病中霜葉赤，愁裏鬢毛斑。","不爲良知在，驅車已出關。"]', '["紅塵擾擾间，立马看南山。","謾道經年往，何妨逐日闲。","病中霜葉赤，愁裏鬢毛斑。","不爲良知在，驱车已出关。"]', '诗', 'shi', '', NULL, '秋日寄狄補闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a3bbd8-63a3-41a1-b561-663a0188e7a7', '寄易定公乘億侍郎', '寄易定公乘億侍郎', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["謝舞仍宮柳，高奇世少雙。","侍中生不到，園令死須降。","班秩通烏府，罇罍奉碧幢。","昭王有餘烈，試爲禱迷邦。"]', '["謝舞仍宮柳，高奇世少雙。","侍中生不到，园令死須降。","班秩通烏府，罇罍奉碧幢。","昭王有餘烈，試爲禱迷邦。"]', '诗', 'shi', '', NULL, '寄易定公乘億侍郎 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a3e7589-6d3a-4b75-83b8-9f4a5489262e', '寄大理徐郎中', '寄大理徐郎中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["佐棘竟誰同，因思證聖中。","事雖忘顯報，理合有陰功。","官序詵枝老，幽塵范甑空。","幾時潘好禮，重與話清風。"]', '["佐棘竟誰同，因思證聖中。","事雖忘显報，理合有陰功。","官序詵枝老，幽塵范甑空。","幾时潘好禮，重與話清风。"]', '诗', 'shi', '', NULL, '寄大理徐郎中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdee7e1d-ae6d-449f-a361-508b279fe539', '寄蘇拾遺', '寄蘇拾遺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["早歲長楊賦，當年諫獵書。","格高時輩伏，言數宦情疎。","慷慨傳丹桂，艱難保舊居。","退朝觀藁草，能望馬相如。"]', '["早歲长楊賦，當年諫獵书。","格高时輩伏，言數宦情疎。","慷慨傳丹桂，艱难保旧居。","退朝观藁草，能望马相如。"]', '诗', 'shi', '', NULL, '寄蘇拾遺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead5fb8e-39c8-48c9-a34c-a8e5b51832eb', '寄許融', '寄許融', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["多病仍疎拙，唯君與我同。","帝鄉年共老，江徼業俱空。","燕冷辭華屋，蛩涼恨曉叢。","白雲高幾許，全屬採芝翁。"]', '["多病仍疎拙，唯君與我同。","帝乡年共老，江徼業俱空。","燕冷辞华屋，蛩涼恨晓叢。","白云高幾許，全屬採芝翁。"]', '诗', 'shi', '', NULL, '寄許融 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee828e9b-fa64-48ce-9b18-d19717987396', '寄禮部鄭員外', '寄禮部鄭員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["欒郄門風大，裴王禮樂優。","班資冠雞舌，人品壓龍頭。","夜直爐香細，晴編疏草稠。","近聞潘散騎，三十二悲秋。"]', '["欒郄门风大，裴王禮乐優。","班資冠雞舌，人品壓龙头。","夜直爐香細，晴編疏草稠。","近闻潘散騎，三十二悲秋。"]', '诗', 'shi', '', NULL, '寄禮部鄭員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a480259-5451-4f83-8ca9-6b099d2bfc4c', '菊', '菊', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["籬落歲云暮，數枝聊自芳。","雪裁纖蘂密，金拆小苞香。","千載白衣酒，一生青女霜。","春叢莫輕薄，彼此有行藏。"]', '["籬落歲云暮，數枝聊自芳。","雪裁纖蘂密，金拆小苞香。","千載白衣酒，一生青女霜。","春叢莫轻薄，彼此有行藏。"]', '诗', 'shi', '', NULL, '菊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('903c2e05-04ca-4177-81e2-e68f917b4d3b', '臺城', '台城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["水國春常在，臺城夜未寒。","麗華承寵渥，江令捧杯盤。","宴罷明堂爛，詩成寶炬殘。","兵來吾有計，金井玉鉤欄。"]', '["水国春常在，台城夜未寒。","丽华承寵渥，江令捧杯盤。","宴罷明堂爛，诗成寶炬殘。","兵来吾有計，金井玉鉤欄。"]', '诗', 'shi', '', NULL, '臺城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d5564a4-bca5-45ed-8a14-b578250b0e77', '舊遊', '旧游', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["良時不復再，漸老更難言。","遠水猶經眼，高樓似斷魂。","依依宋玉宅，歷歷長卿村。","今日空江畔，相於只酒樽。"]', '["良时不复再，漸老更难言。","远水猶經眼，高楼似斷魂。","依依宋玉宅，歷歷长卿村。","今日空江畔，相於只酒樽。"]', '诗', 'shi', '', NULL, '舊遊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92deabd7-56ff-4257-bd98-f2dbe25bb63f', '寄虔州薛大夫', '寄虔州薛大夫', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["祝融峰下別，三載夢魂勞。","地轉南康重，官兼亞相高。","海鵬終負日，神馬背眠槽。","會得窺成績，幽窗染兔毫。"]', '["祝融峰下別，三載梦魂勞。","地轉南康重，官兼亞相高。","海鵬終負日，神马背眠槽。","會得窺成績，幽窗染兔毫。"]', '诗', 'shi', '', NULL, '寄虔州薛大夫 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6733060-b6c9-412e-8c94-5147a0a7b1d1', '蘇小小墓', '蘇小小墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["魂兮檇李城，猶未有人耕。","好月當年事，殘花觸處情。","向誰曾豔冶，隨分得聲名。","應侍吳王宴，蘭橈暗送迎。"]', '["魂兮檇李城，猶未有人耕。","好月當年事，殘花觸处情。","向誰曾豔冶，隨分得声名。","應侍吳王宴，蘭橈暗送迎。"]', '诗', 'shi', '', NULL, '蘇小小墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d14187-5e4f-4c09-8999-44cf9a9e7044', '寒食日早出城東', '寒食日早出城东', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青門欲曙天，車馬已喧闐。","禁柳疎風雨，牆花拆露鮮。","向誰誇麗景，只是歎流年。","不得高飛便，迴頭望紙鳶。"]', '["青门欲曙天，车马已喧闐。","禁柳疎风雨，牆花拆露鲜。","向誰誇丽景，只是歎流年。","不得高飞便，迴头望紙鳶。"]', '诗', 'shi', '', NULL, '寒食日早出城東 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7765e7f-ba4c-4d42-86c1-d7bdcb894858', '秋日懷賈隨進士', '秋日懷賈隨進士', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["邊寇日騷動，故人音信稀。","長纓慙賈誼，孤憤憶韓非。","曉匣魚腸冷，春園鴨掌肥。","知君安未得，聊且示忘機。"]', '["邊寇日騷动，故人音信稀。","长纓慙賈誼，孤憤憶韓非。","晓匣鱼腸冷，春园鴨掌肥。","知君安未得，聊且示忘機。"]', '诗', 'shi', '', NULL, '秋日懷賈隨進士 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f44f93e-dc0c-4ce4-8ff3-376a75c57ea5', '亂後逢友人', '亂後逢友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["滄海去未得，倚舟聊問津。","生靈寇盜盡，方鎮改更貧。","夢裏舊行處，眼前新貴人。","從來事如此，君莫獨霑巾。"]', '["滄海去未得，倚舟聊问津。","生靈寇盜尽，方鎮改更貧。","梦裏旧行处，眼前新貴人。","從来事如此，君莫独霑巾。"]', '诗', 'shi', '', NULL, '亂後逢友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ca03f2-120a-469f-9df6-535a160b9a4d', '殘花', '殘花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["已歎良時晚，仍悲別酒催。","暖芳隨日薄，輕片逐風迴。","黛斂愁歌扇，妝殘泣鏡臺。","繁陰莫矜衒，終是共塵埃。"]', '["已歎良时晚，仍悲別酒催。","暖芳隨日薄，轻片逐风迴。","黛斂愁歌扇，妝殘泣镜台。","繁陰莫矜衒，終是共塵埃。"]', '诗', 'shi', '', NULL, '殘花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274e3283-a3aa-49e8-876a-397f8aa7aced', '秋日富春江行', '秋日富春江行', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遠岸平如翦，澄江靜似鋪。","紫鱗仙客馭，金顆李衡奴。","冷疊羣山闊，清涵萬象殊。","嚴陵亦高見，歸臥是良圖。"]', '["远岸平如翦，澄江静似鋪。","紫鱗仙客馭，金顆李衡奴。","冷叠羣山闊，清涵万象殊。","嚴陵亦高见，归臥是良圖。"]', '诗', 'shi', '', NULL, '秋日富春江行 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a505b7a3-9631-46f7-9dba-7a17a413908d', '寄侯博士', '寄侯博士', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["規諫揚雄賦，邅迴賈誼官。","久貧還往少，孤立轉遷難。","清鏡流年急，高槐旅舍寒。","侏儒亦何有，飽食向長安。"]', '["規諫揚雄賦，邅迴賈誼官。","久貧還往少，孤立轉遷难。","清镜流年急，高槐旅舍寒。","侏儒亦何有，飽食向长安。"]', '诗', 'shi', '', NULL, '寄侯博士 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7d0e82-2c24-4866-a158-3b418686bfdb', '送沈光侍御赴職閩中', '送沈光侍御赴職閩中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["未至應居右，全家出帝鄉。","禮優逢苑雪，官重帶臺霜。","夜浦吳潮吼，春灘建水狂。","延平有風雨，從此是騰驤。"]', '["未至應居右，全家出帝乡。","禮優逢苑雪，官重带台霜。","夜浦吳潮吼，春灘建水狂。","延平有风雨，從此是腾驤。"]', '诗', 'shi', '', NULL, '送沈光侍御赴職閩中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6635ba-e3c0-4aea-b75a-15bd79de18b5', '寄袁皓侍郎', '寄袁皓侍郎', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["東臺失路岐，榮辱事堪悲。","我寢牛衣敝，君居豸角危。","風塵慙上品，才業愧明時。","千里芙蓉幕，何由話所思。"]', '["东台失路岐，榮辱事堪悲。","我寢牛衣敝，君居豸角危。","风塵慙上品，才業愧明时。","千里芙蓉幕，何由話所思。"]', '诗', 'shi', '', NULL, '寄袁皓侍郎 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479bfb22-e8d0-4675-acfc-9b14b8f2be8d', '寄金吾李蓀常侍', '寄金吾李蓀常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["西班掌禁兵，蘭錡最分明。","曉色嚴天仗，春寒避火城。","安危雖已任，韜略即嘉聲。","請問何功德，壺關寇始平。"]', '["西班掌禁兵，蘭錡最分明。","晓色嚴天仗，春寒避火城。","安危雖已任，韜略即嘉声。","請问何功德，壺关寇始平。"]', '诗', 'shi', '', NULL, '寄金吾李蓀常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41c1519-3e03-4a11-b1d2-495dca280343', '商於驛與于蘊玉話別', '商於驛與于蘊玉話別', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["南朝徐庾流，洛下憶同遊。","酒采閑坊菊，山登遠寺樓。","相思勞寄夢，偶別已經秋。","還被青青桂，催君不自由。"]', '["南朝徐庾流，洛下憶同游。","酒采闲坊菊，山登远寺楼。","相思勞寄梦，偶別已經秋。","還被青青桂，催君不自由。"]', '诗', 'shi', '', NULL, '商於驛與于蘊玉話別 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec66fc5-f59d-48b6-8b93-3b37285f518c', '封禪寺居', '封禪寺居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["盛禮何由覩，嘉名偶寄居。","周南太史淚，蠻徼長卿書。","砌竹搖風直，庭花泣露疎。","誰能賦秋興，千里隔吾廬。"]', '["盛禮何由覩，嘉名偶寄居。","周南太史泪，蠻徼长卿书。","砌竹搖风直，庭花泣露疎。","誰能賦秋兴，千里隔吾廬。"]', '诗', 'shi', '', NULL, '封禪寺居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb01fab-d4ec-45f0-b3fc-0f3216b08489', '錢', '錢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["志士不敢道，貯之成禍胎。","小人無事藝，假爾作梯媒。","解釋愁腸結，能分睡眼開。","朱門狼虎性，一半逐君回。"]', '["志士不敢道，貯之成禍胎。","小人無事藝，假爾作梯媒。","解釋愁腸結，能分睡眼开。","朱门狼虎性，一半逐君回。"]', '诗', 'shi', '', NULL, '錢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04657fcb-1d6b-4602-9f49-6dad410298b4', '投寄韋右丞', '投寄韋右丞', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["赤壁徵文聘，中臺拜郄詵。","官資參令僕，曹署轄星辰。","幞被從誰起，持綱自此新。","舉朝明典教，封納詔書頻。","禁樹曾摛藻，臺烏舊避塵。"]', '["赤壁徵文聘，中台拜郄詵。","官資參令僕，曹署轄星辰。","幞被從誰起，持綱自此新。","舉朝明典教，封納詔书頻。","禁樹曾摛藻，台烏旧避塵。"]', '诗', 'shi', '', NULL, '投寄韋右丞 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1220b8-28ca-4ded-b86b-11a6f4a7c0e7', '紅葉', '紅葉', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不奈荒城畔，那堪晚照中。","野晴霜浥綠，山冷雨催紅。","遊子灞陵道，美人長信宮。","等閑居歲暮，搖落意無窮。"]', '["不奈荒城畔，那堪晚照中。","野晴霜浥綠，山冷雨催紅。","游子灞陵道，美人长信宮。","等闲居歲暮，搖落意無窮。"]', '诗', 'shi', '', NULL, '紅葉 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaafa3c0-094c-402f-8610-c706151403bf', '期徐道者不至', '期徐道者不至', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遼鶴虛空語，冥鴻未易親。","偶然來即是，必擬見無因。","霜霰窮冬令，杯盤旅舍貧。","只應薊子訓，醉後懶分身。"]', '["遼鹤虛空語，冥鴻未易親。","偶然来即是，必擬见無因。","霜霰窮冬令，杯盤旅舍貧。","只應薊子訓，醉後懶分身。"]', '诗', 'shi', '', NULL, '期徐道者不至 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132ac8aa-4524-482a-90bc-35498821b663', '歲除夜', '歲除夜', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["官曆行將盡，村醪強自傾。","厭寒思暖律，畏老惜殘更。","歲月已如此，寇戎猶未平。","兒童不諳事，歌吹待天明。"]', '["官曆行將尽，村醪強自傾。","厭寒思暖律，畏老惜殘更。","歲月已如此，寇戎猶未平。","兒童不諳事，歌吹待天明。"]', '诗', 'shi', '', NULL, '歲除夜 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9f5498-6508-420a-a943-80951767c24a', '雪', '雪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["盡道豐年瑞，豐年事若何。","長安有貧者，爲瑞不宜多。"]', '["尽道豐年瑞，豐年事若何。","长安有貧者，爲瑞不宜多。"]', '诗', 'shi', '', NULL, '雪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f16be97-3fdf-4508-963d-43104abcff2f', '旅夢', '旅梦', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["旅夢思遷次，窮愁有歎嗟。","子鵝京口遠，粳米會稽賒。","漏澀纔成滴，燈寒不作花。","出門聊一望，蟾桂向人斜。"]', '["旅梦思遷次，窮愁有歎嗟。","子鵝京口远，粳米會稽賒。","漏澀纔成滴，灯寒不作花。","出门聊一望，蟾桂向人斜。"]', '诗', 'shi', '', NULL, '旅夢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe2f128-c873-4659-9c4a-4f0501660450', '秋寄張坤', '秋寄張坤', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["庭樹已黃落，閉門俱寂寥。","未知棲託處，空羨聖明朝。","酒醒鄉心闊，雲晴客思遙。","吾徒自多感，顏子只簞瓢。"]', '["庭樹已黄落，閉门俱寂寥。","未知棲託处，空羨聖明朝。","酒醒乡心闊，云晴客思遙。","吾徒自多感，顏子只簞瓢。"]', '诗', 'shi', '', NULL, '秋寄張坤 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d5aa06-577c-4aba-8fa5-f169d1295d5e', '傷華髪', '傷华髪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["舊國迢迢遠，清秋種種新。","已衰曾軫慮，初見忽霑巾。","日薄梳兼嬾，根危鑷恐頻。","青銅不自見，只擬老他人。"]', '["旧国迢迢远，清秋種種新。","已衰曾軫慮，初见忽霑巾。","日薄梳兼嬾，根危鑷恐頻。","青銅不自见，只擬老他人。"]', '诗', 'shi', '', NULL, '傷華髪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('457e4b9d-7a1b-4c6d-89fc-cf834b93771e', '九江早秋', '九江早秋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雨過晚涼生，樓中枕簟清。","海風吹亂木，巖磬落孤城。","百歲幾多日，四蹄無限程。","西鄰莫高唱，俱是別離情。"]', '["雨過晚涼生，楼中枕簟清。","海风吹亂木，巖磬落孤城。","百歲幾多日，四蹄無限程。","西鄰莫高唱，俱是別離情。"]', '诗', 'shi', '', NULL, '九江早秋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36166023-ac59-44e9-bdd6-5f637a9facf4', '初秋寄友人', '初秋寄友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["九華曾屏跡，罹亂與心違。","是處堪終老，新秋又未歸。","病中芳草歇，愁裏白雲飛。","樵侶兼同志，音書近亦稀。"]', '["九华曾屏跡，罹亂與心違。","是处堪終老，新秋又未归。","病中芳草歇，愁裏白云飞。","樵侶兼同志，音书近亦稀。"]', '诗', 'shi', '', NULL, '初秋寄友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6412981-f3d1-4051-b7b6-5fe5fe0b885c', '秋居有寄', '秋居有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["端居湖岸東，生計有無中。","魘處千般鬼，寒時百種風。","性靈縱道拙，心事奈成空。","多謝金臺客，何當一笑同。"]', '["端居湖岸东，生計有無中。","魘处千般鬼，寒时百種风。","性靈縱道拙，心事奈成空。","多謝金台客，何當一笑同。"]', '诗', 'shi', '', NULL, '秋居有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26aab409-d6fc-4be7-8e95-030cdb5e486c', '雪霽', '雪霽', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["南山雪乍晴，寒氣轉崢嶸。","銷却閑門出，隨他駿馬行。","一竿如有計，五鼎豈須烹。","愁見天街草，青青又欲生。"]', '["南山雪乍晴，寒氣轉崢嶸。","銷却闲门出，隨他駿马行。","一竿如有計，五鼎豈須烹。","愁见天街草，青青又欲生。"]', '诗', 'shi', '', NULL, '雪霽 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ddef908-251a-42a9-ad6e-930f4886d00c', '堠子', '堠子', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["終日路岐旁，前程亦可量。","未能慙面黑，只是恨頭方。","雅旨逾千里，高文近兩行。","君知不識字，第一莫形相。"]', '["終日路岐旁，前程亦可量。","未能慙面黑，只是恨头方。","雅旨逾千里，高文近兩行。","君知不識字，第一莫形相。"]', '诗', 'shi', '', NULL, '堠子 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131bd556-b400-40a1-9cf6-6671ee1b468f', '初夏寄顧紹宗', '初夏寄顧紹宗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江上偶分袂，四回寒暑更。","青山無路入，白髮滿頭生。","郢浦鴈尋過，鏡湖蟬又鳴。","憐君未歸日，杯酒若爲情。"]', '["江上偶分袂，四回寒暑更。","青山無路入，白髮满头生。","郢浦鴈尋過，镜湖蟬又鳴。","怜君未归日，杯酒若爲情。"]', '诗', 'shi', '', NULL, '初夏寄顧紹宗 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c5376f-dec8-4920-ac45-3e88c1db3150', '寄第五尊師', '寄第五尊師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["苕溪煙月久因循，野鶴衣裘獨繭綸。","只說泊船無定處，不知攜手是何人。","朱黃揀日囚尸鬼，青白臨時注腦神。","欲訪先生問經訣，世間難得不由身。"]', '["苕溪煙月久因循，野鹤衣裘独繭綸。","只说泊船無定处，不知携手是何人。","朱黄揀日囚尸鬼，青白臨时注腦神。","欲訪先生问經訣，世间难得不由身。"]', '诗', 'shi', '', NULL, '寄第五尊師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8080ac2d-a841-4a83-a512-f6d0c5d61072', '寄西華黃鍊師', '寄西华黄鍊師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["西華有路入中華，依約山川認永嘉。","羽客昔時留篠簜，故人今又種煙霞。","壇高已降三清鶴，海近應通八月槎。","盛事兩般君總得，老萊衣服戴顒家。"]', '["西华有路入中华，依約山川認永嘉。","羽客昔时留篠簜，故人今又種煙霞。","壇高已降三清鹤，海近應通八月槎。","盛事兩般君總得，老萊衣服戴顒家。"]', '诗', 'shi', '', NULL, '寄西華黃鍊師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ccfd55-fff6-41fb-968a-4421d9c44803', '所思', '所思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["西上青雲未有期，東歸滄海一何遲。","酒闌夢覺不稱意，花落月明空所思。","長恐病侵多事日，可堪貧過少年時。","鬬雞走狗五陵道，惆悵輸他輕薄兒。"]', '["西上青云未有期，东归滄海一何遲。","酒闌梦覺不稱意，花落月明空所思。","长恐病侵多事日，可堪貧過少年时。","鬬雞走狗五陵道，惆悵輸他轻薄兒。"]', '诗', 'shi', '', NULL, '所思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c761a2ee-bb55-4192-9a12-2ba8eb341156', '送支使蕭中丞赴闕', '送支使蕭中丞赴闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["八年刀筆到京華，歸去青冥路未賒。","今日風流卿相客，舊時基業帝王家。","彤庭彩鳳雖添瑞，望府紅蓮已減花。","從此常僚如有問，海邊麇鹿斗邊槎。"]', '["八年刀笔到京华，归去青冥路未賒。","今日风流卿相客，旧时基業帝王家。","彤庭彩鳳雖添瑞，望府紅蓮已減花。","從此常僚如有问，海邊麇鹿斗邊槎。"]', '诗', 'shi', '', NULL, '送支使蕭中丞赴闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a606ef7-8a48-474d-a800-12b9667c43b2', '送人歸湘中兼寄舊知', '送人归湘中兼寄旧知', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青溪煙雨九華山，亂後應同夢寐間。","萬里分飛休掩袂，兩旬相見且開顏。","君依宰相貉蟬貴，我戀王門鬢髪斑。","爲謝伏波筵上客，幾時金印擬西還。"]', '["青溪煙雨九华山，亂後應同梦寐间。","万里分飞休掩袂，兩旬相见且开顏。","君依宰相貉蟬貴，我戀王门鬢髪斑。","爲謝伏波筵上客，幾时金印擬西還。"]', '诗', 'shi', '', NULL, '送人歸湘中兼寄舊知 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb5983c-9cae-4e89-9eee-fb07f20be96c', '自貽', '自貽', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["衰老應難更進趨，藥畦經卷自朝晡。","縱無顯效亦藏拙，若有所成甘守株。","漢武巡遊虛軋軋，秦皇吞併謾驅驅。","如何只見丁家鶴，依舊遼東歎綠蕪。"]', '["衰老應难更進趨，藥畦經卷自朝晡。","縱無显效亦藏拙，若有所成甘守株。","漢武巡游虛軋軋，秦皇吞併謾驱驱。","如何只见丁家鹤，依旧遼东歎綠蕪。"]', '诗', 'shi', '', NULL, '自貽 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2345ff52-26aa-4bfa-b41c-3ff2320cb5f2', '暇日感懷因寄同院吳蛻拾遺', '暇日感懷因寄同院吳蛻拾遺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["璧池清秩訪燕臺，曾捧瀛州札翰來。","今日二難俱大夜，當時三幅謾高才。","戲悲槐市便便笥，狂憶樟亭滿滿杯。","猶幸小蘭同舍在，每因相見即銜哀。"]', '["璧池清秩訪燕台，曾捧瀛州札翰来。","今日二难俱大夜，當时三幅謾高才。","戲悲槐市便便笥，狂憶樟亭满满杯。","猶幸小蘭同舍在，每因相见即銜哀。"]', '诗', 'shi', '', NULL, '暇日感懷因寄同院吳蛻拾遺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7967ec-05e0-40b9-84e2-07889e817cb7', '偶興', '偶兴', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["逐隊隨行二十春，曲江池畔避車塵。","如今贏得將衰老，閑看人間得意人。"]', '["逐隊隨行二十春，曲江池畔避车塵。","如今贏得將衰老，闲看人间得意人。"]', '诗', 'shi', '', NULL, '偶興 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55a77027-05df-4909-9d2c-ec41e83606cc', '題鑿石山僧院', '題鑿石山僧院', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["日夜潮聲送是非，一迴登眺一忘機。","憐師好事無人見，不把蘭芽染褐衣。"]', '["日夜潮声送是非，一迴登眺一忘機。","怜師好事無人见，不把蘭芽染褐衣。"]', '诗', 'shi', '', NULL, '題鑿石山僧院 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb652cd-890a-4457-87b3-2805735b7234', '圉城偶作', '圉城偶作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["東望陳留日欲曛，每因刀筆想夫君。","自從郭泰碑銘後，只見黃金不見文。"]', '["东望陳留日欲曛，每因刀笔想夫君。","自從郭泰碑銘後，只见黄金不见文。"]', '诗', 'shi', '', NULL, '圉城偶作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbad745-971e-43b0-8cf5-45c815886c0f', '烏程', '烏程', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["兩府攀陪十五年，郡中甘雨幕中蓮。","一瓶猶是烏程酒，須對霜風度泫然。"]', '["兩府攀陪十五年，郡中甘雨幕中蓮。","一瓶猶是烏程酒，須对霜风度泫然。"]', '诗', 'shi', '', NULL, '烏程 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90dd720-cd19-4f65-a6ad-cbe8c7456853', '送楊鍊師却歸貞浩巖', '送楊鍊師却归貞浩巖', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["宦途不復更經營，歸去東南任意行。","別後幾回思會面，到來相見似前生。","久居竹蓋知勤苦，舊業蓮峰想變更。","爲謝佯狂吳道士，耳中時有鐵船聲。"]', '["宦途不复更經營，归去东南任意行。","別後幾回思會面，到来相见似前生。","久居竹蓋知勤苦，旧業蓮峰想变更。","爲謝佯狂吳道士，耳中时有鐵船声。"]', '诗', 'shi', '', NULL, '送楊鍊師却歸貞浩巖 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b2f935d-adca-41d3-9d60-65dfdfa9ee6f', '暇日投錢尚父', '暇日投錢尚父', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["牛斗星邊女宿間，棟梁虛敞麗江關。","望高漢相東西閣，名重淮王大小山。","禮設鬬傾金鑿落，馬蹄爭撼玉連環。","自慙麇鹿無能事，未報深恩鬢已斑。"]', '["牛斗星邊女宿间，棟梁虛敞丽江关。","望高漢相东西閣，名重淮王大小山。","禮設鬬傾金鑿落，马蹄爭撼玉連环。","自慙麇鹿無能事，未報深恩鬢已斑。"]', '诗', 'shi', '', NULL, '暇日投錢尚父 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acca0a2a-2d2d-4aff-ab26-70b61e5eab53', '覽晉史', '覽晉史', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["齊王僚屬好男兒，偶覓東歸便得歸。","滿目路岐拋似夢，一船風雨去如飛。","盤擎紫線蓴初熟，箸撥紅絲鱠正肥。","惆悵途中無限事，與君千載兩忘機。"]', '["齊王僚屬好男兒，偶覓东归便得归。","满目路岐拋似梦，一船风雨去如飞。","盤擎紫線蓴初熟，箸撥紅絲鱠正肥。","惆悵途中無限事，與君千載兩忘機。"]', '诗', 'shi', '', NULL, '覽晉史 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e813292-67fe-43c0-9052-f3b63740b2bf', '感別元帥尚父', '感別元帥尚父', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["玉函瑤檢下台司，記得當時捧領時。","半壁龍虵蟠造化，滿筐山岳動神祇。","疲牛舐犢心猶切，陰鶴鳴雛力已衰。","稚子不才身抱疾，日窺貞跡淚雙垂。"]', '["玉函瑤檢下台司，記得當时捧領时。","半壁龙虵蟠造化，满筐山岳动神祇。","疲牛舐犢心猶切，陰鹤鳴雛力已衰。","稚子不才身抱疾，日窺貞跡泪雙垂。"]', '诗', 'shi', '', NULL, '感別元帥尚父 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4778ce22-246f-41ec-9aad-3b1ebd51cf9b', '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 一', '尚父偶建小楼特摛丽藻絕句不敢稱揚三首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["結構叨馮柱石才，敢期幢蓋此裴回。","陽春曲調高誰和，盡日焚香倚隗臺。"]', '["結構叨馮柱石才，敢期幢蓋此裴回。","陽春曲調高誰和，尽日焚香倚隗台。"]', '诗', 'shi', '', NULL, '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d2f3d2-f693-432c-9ff4-9e5ca6d885bb', '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 二', '尚父偶建小楼特摛丽藻絕句不敢稱揚三首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["瑇簪珠履愧非才，時凭闌干首重迴。","只待淮妖翦除後，別傾巵酒賀行臺。"]', '["瑇簪珠履愧非才，时凭闌干首重迴。","只待淮妖翦除後，別傾巵酒賀行台。"]', '诗', 'shi', '', NULL, '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76d9b17-b356-4174-b775-52daa8e9d8d6', '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 三', '尚父偶建小楼特摛丽藻絕句不敢稱揚三首 三', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["闌檻初成愧楚才，不知星彩尚迂迴。","風流孔令陶鈞外，猶記山妖逼小臺。"]', '["闌檻初成愧楚才，不知星彩尚迂迴。","风流孔令陶鈞外，猶記山妖逼小台。"]', '诗', 'shi', '', NULL, '尚父偶建小樓特摛麗藻絕句不敢稱揚三首 三 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5bcf908-fc2c-4ab0-81cf-1533e11f218e', '題玄同先生草堂三首 一', '題玄同先生草堂三首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["杳杳諸天路，蒼蒼大滌山。","景輿留不得，毛節去應閒。","相府舊知己，教門新啓關。","太平匡濟術，流落在人間。"]', '["杳杳諸天路，蒼蒼大滌山。","景輿留不得，毛節去應閒。","相府旧知己，教门新啓关。","太平匡濟術，流落在人间。"]', '诗', 'shi', '', NULL, '題玄同先生草堂三首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8ce364-7798-4f3f-a329-cefac4f3ae36', '題玄同先生草堂三首 二', '題玄同先生草堂三首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["先生訣行日，曾奉數行書。","意密尋難會，情深恨有餘。","石橋春暖後，句漏藥成初。","珍重雲兼鶴，從來不定居。"]', '["先生訣行日，曾奉數行书。","意密尋难會，情深恨有餘。","石橋春暖後，句漏藥成初。","珍重云兼鹤，從来不定居。"]', '诗', 'shi', '', NULL, '題玄同先生草堂三首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b33a36-98f8-443e-a80e-865d5729c6ec', '題玄同先生草堂三首 三', '題玄同先生草堂三首 三', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["常時憶討論，歷歷事猶存。","酒向餘杭盡，雲從大滌昏。","往來無道侶，歸去有台恩。","自此玄言絕，長應閉洞門。"]', '["常时憶討論，歷歷事猶存。","酒向餘杭尽，云從大滌昏。","往来無道侶，归去有台恩。","自此玄言絕，长應閉洞门。"]', '诗', 'shi', '', NULL, '題玄同先生草堂三首 三 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a922ef7b-7689-470f-9ebe-ca4cf3cff3c1', '城西作', '城西作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["從軍無一事，終日掩空齋。","道薄交遊少，才疎進取乖。","野禽鳴聒耳，庭草綠侵階。","幸自同樗櫟，何妨愜所懷。"]', '["從軍無一事，終日掩空斋。","道薄交游少，才疎進取乖。","野禽鳴聒耳，庭草綠侵階。","幸自同樗櫟，何妨愜所懷。"]', '诗', 'shi', '', NULL, '城西作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3b559f-79c9-4fa9-ab55-3e24f7b38946', '冬暮城西晚眺', '冬暮城西晚眺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["謬忝蓮華幕，虛霑柏署官。","欹危長抱疾，衰老不禁寒。","時事已日過，世途行轉難。","千崖兼萬壑，只向望中看。"]', '["謬忝蓮华幕，虛霑柏署官。","欹危长抱疾，衰老不禁寒。","时事已日過，世途行轉难。","千崖兼万壑，只向望中看。"]', '诗', 'shi', '', NULL, '冬暮城西晚眺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfe1ebd-1ade-4b05-9e45-951d1e789274', '秋霽後', '秋霽後', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["淨碧山光冷，圓明露點勻。","渚蓮丹臉恨，堤柳翠眉顰。","蟬已送行客，鴈應辭主人。","蠅蚊漸無況，日晚自相親。"]', '["淨碧山光冷，圓明露点勻。","渚蓮丹臉恨，堤柳翠眉顰。","蟬已送行客，鴈應辞主人。","蠅蚊漸無況，日晚自相親。"]', '诗', 'shi', '', NULL, '秋霽後 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3fec15-9678-4497-8b9c-147a49214458', '茅齋', '茅斋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["從事不從事，養生非養生。","職爲尸祿本，官是受恩名。","時態已相失，歲華從自驚。","西齋一巵酒，衰老與誰傾。"]', '["從事不從事，養生非養生。","職爲尸祿本，官是受恩名。","时態已相失，歲华從自驚。","西斋一巵酒，衰老與誰傾。"]', '诗', 'shi', '', NULL, '茅齋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae7636f-1bc3-43cb-a107-3ca874e154eb', '使者', '使者', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["使者銜中旨，崎嶇萬里行。","人心猶未革，天意似難明。","四海霍光第，六宮張奉營。","陪臣無以報，西望不勝情。"]', '["使者銜中旨，崎嶇万里行。","人心猶未革，天意似难明。","四海霍光第，六宮張奉營。","陪臣無以報，西望不勝情。"]', '诗', 'shi', '', NULL, '使者 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173cb325-a798-46a8-a8ea-20c689e18617', '途中逢劉知遠', '途中逢劉知远', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吳楚煙波裏，巢由季孟間。","只言無事貴，不道致身閑。","別渚蓮根斷，歸心桂樹頑。","空勞鍾璞意，塵世隔函關。"]', '["吳楚煙波裏，巢由季孟间。","只言無事貴，不道致身闲。","別渚蓮根斷，归心桂樹頑。","空勞鍾璞意，塵世隔函关。"]', '诗', 'shi', '', NULL, '途中逢劉知遠 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70988f5e-b0ff-4ca8-90a8-8fb2b9065204', '遁跡', '遁跡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遁跡知安住，霑襟欲奈何。","朝廷猶禮樂，郡邑忍干戈。","華馬憑誰問，胡塵自此多。","因思漢明帝，中夜憶廉頗。"]', '["遁跡知安住，霑襟欲奈何。","朝廷猶禮乐，郡邑忍干戈。","华马憑誰问，胡塵自此多。","因思漢明帝，中夜憶廉頗。"]', '诗', 'shi', '', NULL, '遁跡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c8679d-597a-47c9-81d2-6030bccfae2f', '隴頭水', '隴头水', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["借問隴頭水，年年恨何事。","全疑嗚咽聲，中有征人淚。","自古無長策，況我非深智。","何計謝潺湲，一宵空不寐。"]', '["借问隴头水，年年恨何事。","全疑嗚咽声，中有征人泪。","自古無长策，況我非深智。","何計謝潺湲，一宵空不寐。"]', '诗', 'shi', '', NULL, '隴頭水 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658b52dc-3731-4d60-9bc4-5b1a60db00f2', '秦中富人', '秦中富人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["高高起華堂，區區引流水。","糞土金玉珍，猶嫌未奢侈。","陋巷滿蓬蒿，誰知有顏子。"]', '["高高起华堂，區區引流水。","糞土金玉珍，猶嫌未奢侈。","陋巷满蓬蒿，誰知有顏子。"]', '诗', 'shi', '', NULL, '秦中富人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dddbcb22-0162-42ea-950d-a4e5555b0411', '思歸行', '思归行', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不耕南畝田，爲愛東堂桂。","身同樹上花，一落又經歲。","交親亦相薄，知己恩潛替。","日開十二門，自是無歸計。"]', '["不耕南畝田，爲愛东堂桂。","身同樹上花，一落又經歲。","交親亦相薄，知己恩潛替。","日开十二门，自是無归計。"]', '诗', 'shi', '', NULL, '思歸行 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af25b610-63f7-4899-94b3-cc078a027aed', '即事中元甲子', '即事中元甲子', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["三秦流血已成川，塞上黃雲戰[馬]閒。","只有羸兵填渭水，終無奇事出商山。","田園已沒紅塵內，弟姪相逢白刃間。","惆悵翠華猶未返，淚痕空滴劒文斑。"]', '["三秦流血已成川，塞上黄云戰[马]閒。","只有羸兵填渭水，終無奇事出商山。","田园已沒紅塵內，弟姪相逢白刃间。","惆悵翠华猶未返，泪痕空滴劒文斑。"]', '诗', 'shi', '', NULL, '即事中元甲子 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a79d78bc-4e00-4bce-99e9-b3a1f8977193', '魏城逢故人', '魏城逢故人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一年兩度錦江遊，前值東風後值秋。","芳草有情皆礙馬，好雲無處不遮樓。","山將別恨和心斷，水帶離聲入夢流。","今日因君試回首，澹煙喬木隔綿州。"]', '["一年兩度錦江游，前值东风後值秋。","芳草有情皆礙马，好云無处不遮楼。","山將別恨和心斷，水带離声入梦流。","今日因君試回首，澹煙喬木隔綿州。"]', '诗', 'shi', '', NULL, '魏城逢故人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed6a301-cc0e-446b-bc03-c8e95524a0be', '遊江夏口', '游江夏口', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["醉別江東酒一杯，往年曾此駐塵埃。","魚聽建業歌聲過，水看瞿塘雪影來。","黃祖不能容賤客，費禕終是負仙才。","平生膽氣平生恨，今日江邊首嬾迴。"]', '["醉別江东酒一杯，往年曾此駐塵埃。","鱼听建業歌声過，水看瞿塘雪影来。","黄祖不能容賤客，費禕終是負仙才。","平生膽氣平生恨，今日江邊首嬾迴。"]', '诗', 'shi', '', NULL, '遊江夏口 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb926914-184e-49ae-a5e0-90b9fb27af44', '春思', '春思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蕩漾春風淥似波，惹情搖恨去傞傞。","燕翻永日音聲好，柳舞空城意緒多。","蜀國暖迴溪峽浪，衛娘清轉遏雲歌。","可憐戶外桃兼李，仲蔚蓬蒿奈爾何。"]', '["蕩漾春风淥似波，惹情搖恨去傞傞。","燕翻永日音声好，柳舞空城意緒多。","蜀国暖迴溪峽浪，衛娘清轉遏云歌。","可怜戶外桃兼李，仲蔚蓬蒿奈爾何。"]', '诗', 'shi', '', NULL, '春思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e52a652-5415-41f1-a900-79497ac40fc5', '黃鶴驛寓題', '黄鹤驛寓題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["野雲芳草繞離鞭，敢對青樓倚少年。","秋色未催榆塞鴈，人心先下洞庭船。","高歌酒市非狂者，大嚼屠門亦偶然。","車馬同歸莫同恨，古人頭白盡林泉。"]', '["野云芳草繞離鞭，敢对青楼倚少年。","秋色未催榆塞鴈，人心先下洞庭船。","高歌酒市非狂者，大嚼屠门亦偶然。","车马同归莫同恨，古人头白尽林泉。"]', '诗', 'shi', '', NULL, '黃鶴驛寓題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7194db68-423e-480e-9610-b60aaefc2984', '安陸贈徐礪', '安陸贈徐礪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["靈虵橋下水聲聲，曾向橋邊話別情。","一榻偶依陳太守，三年深憶禰先生。","塵欺鬢色非前事，火爇蓬根有去程。","還把餘杯重相勸，不堪秋色背鄖城。"]', '["靈虵橋下水声声，曾向橋邊話別情。","一榻偶依陳太守，三年深憶禰先生。","塵欺鬢色非前事，火爇蓬根有去程。","還把餘杯重相勸，不堪秋色背鄖城。"]', '诗', 'shi', '', NULL, '安陸贈徐礪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751a9800-ee11-416b-bdf3-3eff172b271c', '寄鍾常侍', '寄鍾常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一從朱履步金臺，蘗苦冰寒奉上台。","峻節不由人學得，遠途終是自將來。","風高漸展摩天翼，榦聳方呈構廈材。","應笑樟亭舊同舍，九州無驗滿爐灰。"]', '["一從朱履步金台，蘗苦冰寒奉上台。","峻節不由人学得，远途終是自將来。","风高漸展摩天翼，榦聳方呈構廈材。","應笑樟亭旧同舍，九州無驗满爐灰。"]', '诗', 'shi', '', NULL, '寄鍾常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2298227e-be83-43e0-9f33-5acb617c9c46', '中秋夜不見月', '中秋夜不见月', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["陰雲薄霧上空虛，此夕清光已破除。","只恐異時開霽後，玉輪依舊養蟾蜍。"]', '["陰云薄霧上空虛，此夕清光已破除。","只恐異时开霽後，玉輪依旧養蟾蜍。"]', '诗', 'shi', '', NULL, '中秋夜不見月 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e111f1-872b-4103-8db1-a17e5ec87cdc', '魏博羅令公附卷有迴', '魏博羅令公附卷有迴', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寒門雖得在諸宗，棲北巢南恨不同。","馬上固慙消髀肉，幄中由羨愈頭風。","蹉跎歲月心仍切，迢遰江山夢未通。","深荷吾宗有知己，好將刀筆爲英雄。"]', '["寒门雖得在諸宗，棲北巢南恨不同。","马上固慙消髀肉，幄中由羨愈头风。","蹉跎歲月心仍切，迢遰江山梦未通。","深荷吾宗有知己，好將刀笔爲英雄。"]', '诗', 'shi', '', NULL, '魏博羅令公附卷有迴 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd598908-a75e-497a-ab3a-5ecbdb0d60a1', '寄處默師', '寄处默師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["甘露卷簾看雨脚，樟亭倚柱望潮頭。","十年顧我醉中過，兩地與師方外遊。","久隔兵戈常寄夢，近無書信更堪憂。","香爐煙靄虎溪月，終棹鐵船尋惠休。"]', '["甘露卷簾看雨脚，樟亭倚柱望潮头。","十年顧我醉中過，兩地與師方外游。","久隔兵戈常寄梦，近無书信更堪憂。","香爐煙靄虎溪月，終棹鐵船尋惠休。"]', '诗', 'shi', '', NULL, '寄處默師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f663790e-f9d9-4b1e-af51-bc49385fab49', '病中上錢尚父', '病中上錢尚父', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["左脚方行右臂攣，每慙名跡污賓筵。","縱饒吳土容衰病，爭奈燕臺費料錢。","藜杖已乾難更把，竹輿雖在不堪懸。","深恩重德無言處，迴首浮生淚泫然。"]', '["左脚方行右臂攣，每慙名跡污賓筵。","縱饒吳土容衰病，爭奈燕台費料錢。","藜杖已乾难更把，竹輿雖在不堪懸。","深恩重德無言处，迴首浮生泪泫然。"]', '诗', 'shi', '', NULL, '病中上錢尚父 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11c89d2-6302-4ea0-a049-bf64053ad91d', '送梅處士歸寧國', '送梅处士归寧国', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["十五年前即別君，別時天下未紛紜。","亂罹且喜身俱在，存沒那堪耳更聞。","良會謾勞悲曩跡，舊交誰去弔荒墳。","殷勤爲謝逃名客，想望千秋嶺上雲。"]', '["十五年前即別君，別时天下未紛紜。","亂罹且喜身俱在，存沒那堪耳更闻。","良會謾勞悲曩跡，旧交誰去弔荒墳。","殷勤爲謝逃名客，想望千秋嶺上云。"]', '诗', 'shi', '', NULL, '送梅處士歸寧國 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35042c83-6625-4baa-a633-7e280124bcd5', '經故友所居', '經故友所居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["槐花漠漠向人黃，此地追遊跡已荒。","清論不知莊叟達，死交空歡趙岐忙。","病來未忍言閑事，老去唯知覓醉鄉。","日暮街東策羸馬，一聲橫笛似山陽。"]', '["槐花漠漠向人黄，此地追游跡已荒。","清論不知莊叟達，死交空歡趙岐忙。","病来未忍言闲事，老去唯知覓醉乡。","日暮街东策羸马，一声橫笛似山陽。"]', '诗', 'shi', '', NULL, '經故友所居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b581af-f43b-491e-8a29-e7a03cc389ac', '大梁從事居汜水', '大梁從事居汜水', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["前年帝里望行塵，記得仙家第四人。","泉暖舊諳龍偃息，露寒初見鶴精神。","歌聲上榻梁園晚，夢遶殘鐘汜水春。","知有篋中編集在，只應從此是經綸。"]', '["前年帝里望行塵，記得仙家第四人。","泉暖旧諳龙偃息，露寒初见鹤精神。","歌声上榻梁园晚，梦遶殘鐘汜水春。","知有篋中編集在，只應從此是經綸。"]', '诗', 'shi', '', NULL, '大梁從事居汜水 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ee256d-3599-4534-9f72-c74ca62033ad', '杜處士新居', '杜处士新居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["翠斂王孫草，荒誅宋玉茅。","寇餘無故物，時薄少深交。","迸笋穿行徑，饑雛出壞巢。","小園吾亦有，多病近來拋。"]', '["翠斂王孫草，荒誅宋玉茅。","寇餘無故物，时薄少深交。","迸笋穿行徑，饑雛出壞巢。","小园吾亦有，多病近来拋。"]', '诗', 'shi', '', NULL, '杜處士新居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db40f212-23cf-4858-a4e3-371cc0ae35b0', '絕境', '絕境', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["絕境非身事，流年但物華。","水梳苔髪直，風引蕙心斜。","凡客從題鳳，膚音未勝蛙。","小船兼有槳，始與問漁家。"]', '["絕境非身事，流年但物华。","水梳苔髪直，风引蕙心斜。","凡客從題鳳，膚音未勝蛙。","小船兼有槳，始與问漁家。"]', '诗', 'shi', '', NULL, '絕境 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11098e31-1df2-4627-9dbd-d1f5600e7330', '雪中懷友人', '雪中懷友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["臘酒復臘雪，故人今越鄉。","所思誰把醆，端坐恨無航。","兔苑舊遊盡，龜臺仙路長。","未知鄒孟子，何以奉梁王。"]', '["臘酒复臘雪，故人今越乡。","所思誰把醆，端坐恨無航。","兔苑旧游尽，龟台仙路长。","未知鄒孟子，何以奉梁王。"]', '诗', 'shi', '', NULL, '雪中懷友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3840a008-1325-4ebd-a31c-fdc54e1dcc4b', '秋晚', '秋晚', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["宰邑慙良術，爲文愧壯圖。","縱饒長委命，爭奈漸非夫。","杯酒有時有，亂罹無處無。","金庭在何域，回首一踟躕。"]', '["宰邑慙良術，爲文愧壯圖。","縱饒长委命，爭奈漸非夫。","杯酒有时有，亂罹無处無。","金庭在何域，回首一踟躕。"]', '诗', 'shi', '', NULL, '秋晚 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e334c7-1993-4676-b4f8-14e29829c662', '昇仙橋', '昇仙橋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["危梁枕路岐，駐馬問前時。","價自友朋得，名因婦女知。","直須論運命，不得逞文詞。","執戟君鄉里，榮華竟若爲。"]', '["危梁枕路岐，駐马问前时。","價自友朋得，名因婦女知。","直須論運命，不得逞文词。","執戟君乡里，榮华竟若爲。"]', '诗', 'shi', '', NULL, '昇仙橋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8507e813-5ed4-4fa4-855e-49b63c7eab4b', '姑蘇[真]娘墓', '姑蘇[真]娘墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["春草荒墳墓，萋萋向虎丘。","死猶嫌寂寞，生肯不風流。","皎鏡山泉冷，輕裾海霧秋。","還應伴西子，香逕夜深遊。"]', '["春草荒墳墓，萋萋向虎丘。","死猶嫌寂寞，生肯不风流。","皎镜山泉冷，轻裾海霧秋。","還應伴西子，香逕夜深游。"]', '诗', 'shi', '', NULL, '姑蘇[真]娘墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584bf15b-b357-4e00-9825-69f1e97d374a', '靈山寺', '靈山寺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["晚景聊攄抱，憑欄幾蕩魂。","檻虛從四面，江闊奈孤根。","幽徑薜蘿色，小山菭蘚痕。"]', '["晚景聊攄抱，憑欄幾蕩魂。","檻虛從四面，江闊奈孤根。","幽徑薜蘿色，小山菭蘚痕。"]', '诗', 'shi', '', NULL, '靈山寺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bde0eaf-4976-4226-bee4-fd4eea7f0800', '倚櫂', '倚櫂', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["倚櫂聽鄰笛，霑衣認酒壚。","自緣悲巨室，誰復爲窮途。","樹解將軍夢，城遺御史烏。","直應齊始了，傾酌向寒蕪。"]', '["倚櫂听鄰笛，霑衣認酒壚。","自緣悲巨室，誰复爲窮途。","樹解將軍梦，城遺御史烏。","直應齊始了，傾酌向寒蕪。"]', '诗', 'shi', '', NULL, '倚櫂 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a76099-2881-41a9-96a9-9cf30d89aa1e', '秋夕對月', '秋夕对月', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["夜月色可掬，倚樓聊解顏。","未能分寇盜，徒欲滿關山。","背冷金蟾滑，毛寒玉兔頑。","姮娥謾偷藥，長寡老中閒。"]', '["夜月色可掬，倚楼聊解顏。","未能分寇盜，徒欲满关山。","背冷金蟾滑，毛寒玉兔頑。","姮娥謾偷藥，长寡老中閒。"]', '诗', 'shi', '', NULL, '秋夕對月 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8390a735-8d6e-4735-bf8d-a7654ace28b3', '寄徵士魏員外', '寄徵士魏員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["家遁蘇門節，清貧粉署官。","不矜朝命重，只恨路行難。","窗曉雞譚倦，庭秋蝶夢闌。","羨君歸未得，還有釣魚竿。"]', '["家遁蘇门節，清貧粉署官。","不矜朝命重，只恨路行难。","窗晓雞譚倦，庭秋蝶梦闌。","羨君归未得，還有釣鱼竿。"]', '诗', 'shi', '', NULL, '寄徵士魏員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa001e9-f339-4f45-851c-3a9445d859de', '宿彭蠡館', '宿彭蠡館', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["孤館少行旅，解鞍增別愁。","遠山矜薄暮，高柳怯清秋。","病裏見時態，醉中思舊遊。","所懷今已矣，何必恨東流。"]', '["孤館少行旅，解鞍增別愁。","远山矜薄暮，高柳怯清秋。","病裏见时態，醉中思旧游。","所懷今已矣，何必恨东流。"]', '诗', 'shi', '', NULL, '宿彭蠡館 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a132269-6d2f-4c0d-b33b-8a5f46c77f1c', '螢', '螢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["空庭夜未央，點點度西牆。","抱影何微細，乘時忽發揚。","不思因腐草，便擬倚孤光。","若道能通照，車公業肯長。"]', '["空庭夜未央，点点度西牆。","抱影何微細，乘时忽發揚。","不思因腐草，便擬倚孤光。","若道能通照，车公業肯长。"]', '诗', 'shi', '', NULL, '螢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0878208a-077c-4a26-9aa1-3b7d6a3cf1fd', '早秋宿葉墮所居', '早秋宿葉墮所居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["池荷葉正圓，長曆報時殫。","曠野雲蒸熱，空庭雨始寒。","蠅蚊猶得志，簟席若爲安。","浮世知誰是，勞歌共一懽。"]', '["池荷葉正圓，长曆報时殫。","曠野云蒸熱，空庭雨始寒。","蠅蚊猶得志，簟席若爲安。","浮世知誰是，勞歌共一懽。"]', '诗', 'shi', '', NULL, '早秋宿葉墮所居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e9756f-7235-4dc3-82af-62b9ac125201', '蜨', '蜨', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["漢王刀筆精，寫爾逼天生。","舞巧何妨急，飛高所恨輕。","野田黃雀慮，山館主人情。","此物那堪作，莊周夢不成。"]', '["漢王刀笔精，寫爾逼天生。","舞巧何妨急，飞高所恨轻。","野田黄雀慮，山館主人情。","此物那堪作，莊周梦不成。"]', '诗', 'shi', '', NULL, '蜨 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366e760c-9b39-4c24-a6b3-b2c7c3db4a69', '春居', '春居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["春風百卉搖，舊國路迢迢。","偶病成疎散，因貧得寂寥。","倚簾高柳弱，乘露小桃夭。","春色常無處，村醪更一瓢。"]', '["春风百卉搖，旧国路迢迢。","偶病成疎散，因貧得寂寥。","倚簾高柳弱，乘露小桃夭。","春色常無处，村醪更一瓢。"]', '诗', 'shi', '', NULL, '春居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be51aba-ce9c-4c38-b06a-bd752d53e98c', '輕飆', '轻飆', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["輕飆掠晚莎，秋物慘關河。","戰壘平時少，齋壇上處多。","楚雖屈子重，漢亦憶廉頗。","不及雲臺議，空山老薜蘿。"]', '["轻飆掠晚莎，秋物慘关河。","戰壘平时少，斋壇上处多。","楚雖屈子重，漢亦憶廉頗。","不及云台議，空山老薜蘿。"]', '诗', 'shi', '', NULL, '輕飆 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d0b64a-05f0-4786-a6ae-966c9c2fdfc7', '燕', '燕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不必嫌漂露，何妨養羽毛。","漢妃金屋遠，盧女杏梁高。","野迥雙飛急，煙晴對語勞。","猶勝黃雀在，棲息是蓬蒿。"]', '["不必嫌漂露，何妨養羽毛。","漢妃金屋远，盧女杏梁高。","野迥雙飞急，煙晴对語勞。","猶勝黄雀在，棲息是蓬蒿。"]', '诗', 'shi', '', NULL, '燕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c995bb-273b-4eab-af5e-c9c0e2fbf0c1', '陝西晚思', '陝西晚思', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["長途已自窮，此去便西東。","樹色榮衰裏，人心往返中。","別情流水急，歸夢故山空。","莫忘交遊分，從來事一同。"]', '["长途已自窮，此去便西东。","樹色榮衰裏，人心往返中。","別情流水急，归梦故山空。","莫忘交游分，從来事一同。"]', '诗', 'shi', '', NULL, '陝西晚思 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25c764c-0011-4e53-9871-13bca20195ca', '除夜寄張達', '除夜寄張達', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["梅花已著眼，竹葉況黏脣。","只此留殘歲，那堪憶故人。","亂罹書不遠，衰病日相親。","江浦思歸意，明朝又一春。"]', '["梅花已著眼，竹葉況黏脣。","只此留殘歲，那堪憶故人。","亂罹书不远，衰病日相親。","江浦思归意，明朝又一春。"]', '诗', 'shi', '', NULL, '除夜寄張達 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('071199b2-efba-4061-b79b-4d123c7a2800', '寄酬鄴王羅令公五首 一', '寄酬鄴王羅令公五首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["營室東迴廕斥丘，少年承襲擁青油。","坐調金鼎尊明主，橫把琱戈拜列侯。","書札二王爭巧拙，篇章七子避風流。","西園舊跡今應在，衰老無因奉勝游。"]', '["營室东迴廕斥丘，少年承襲擁青油。","坐調金鼎尊明主，橫把琱戈拜列侯。","书札二王爭巧拙，篇章七子避风流。","西园旧跡今應在，衰老無因奉勝游。"]', '诗', 'shi', '', NULL, '寄酬鄴王羅令公五首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5372777f-9cad-46d9-a01c-adba1b9f305e', '寄酬鄴王羅令公五首 二', '寄酬鄴王羅令公五首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["脉散源分歷幾朝，縱然官宦只卑僚。","正憂末派淪滄海，忽見高枝拂絳霄。","十萬貔貅趨玉帳，三千賓客珥金貂。","良時難得吾宗少，應念寒門更寂寥。"]', '["脉散源分歷幾朝，縱然官宦只卑僚。","正憂末派淪滄海，忽见高枝拂絳霄。","十万貔貅趨玉帳，三千賓客珥金貂。","良时难得吾宗少，應念寒门更寂寥。"]', '诗', 'shi', '', NULL, '寄酬鄴王羅令公五首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2eb084b-79d7-4d4f-b81f-6c8dfbcab6fb', '寄酬鄴王羅令公五首 三', '寄酬鄴王羅令公五首 三', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["敢將衰弱附強宗，細筭還緣血脉同。","湘浦煙波無舊跡，鄴都蘭菊有遺風。","每憐罹亂書猶達，所恨雲泥路不通。","珍重珠璣兼繡段，草玄堂下寄揚雄。"]', '["敢將衰弱附強宗，細筭還緣血脉同。","湘浦煙波無旧跡，鄴都蘭菊有遺风。","每怜罹亂书猶達，所恨云泥路不通。","珍重珠璣兼繡段，草玄堂下寄揚雄。"]', '诗', 'shi', '', NULL, '寄酬鄴王羅令公五首 三 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede3aeb6-6953-4165-bb4a-6cb51b697d7d', '寄酬鄴王羅令公五首 四', '寄酬鄴王羅令公五首 四', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["水雲開霽立高亭，依約黎陽對福星。","只見篇章矜鏤管，不知勳業柱青冥。","早緣入夢金方礪，晚爲傳家鼎始銘。","鶴髪四垂煙閣遠，此生何處拜儀形。"]', '["水云开霽立高亭，依約黎陽对福星。","只见篇章矜鏤管，不知勳業柱青冥。","早緣入梦金方礪，晚爲傳家鼎始銘。","鹤髪四垂煙閣远，此生何处拜儀形。"]', '诗', 'shi', '', NULL, '寄酬鄴王羅令公五首 四 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1a55d7-e75b-4900-8fe8-7e58d1b6649c', '寄酬鄴王羅令公五首 五', '寄酬鄴王羅令公五首 五', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["錦笈朱囊連復連，紫鸞飛下浙江邊。","綃從海室奪煙霧，樂奏帝官勝管弦。","長笑應劉悲顯達，每嫌伊霍少詩篇。","戴灣老圃根基薄，虛費工夫八十年。"]', '["錦笈朱囊連复連，紫鸾飞下浙江邊。","綃從海室奪煙霧，乐奏帝官勝管弦。","长笑應劉悲显達，每嫌伊霍少诗篇。","戴灣老圃根基薄，虛費工夫八十年。"]', '诗', 'shi', '', NULL, '寄酬鄴王羅令公五首 五 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb2c8ba-cf74-4b09-a6ac-5149ec7b399b', '春日投錢塘元帥尚父二首 一', '春日投錢塘元帥尚父二首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["正憂衰老辱金臺，敢望昭王顧問來。","門外旌旗屯[虎豹]，壁閒章句動風雷。","三都節已聯翩降，兩地花應次第開。","若比紫髯分鼎足，未聞餘力有瓊環。"]', '["正憂衰老辱金台，敢望昭王顧问来。","门外旌旗屯[虎豹]，壁閒章句动风雷。","三都節已聯翩降，兩地花應次第开。","若比紫髯分鼎足，未闻餘力有瓊环。"]', '诗', 'shi', '', NULL, '春日投錢塘元帥尚父二首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c55aa21-2074-4bac-b235-fdf1a5bfbe15', '春日投錢塘元帥尚父二首 二', '春日投錢塘元帥尚父二首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["征東幕府十三州，敢望非才忝上游。","官秩已叨吳品職，姓名兼顯魯春秋。","鹽車顧後聲方重，火井窺來焰始浮。","一句黃河千載事，麥城王粲謾登樓。"]', '["征东幕府十三州，敢望非才忝上游。","官秩已叨吳品職，姓名兼显魯春秋。","鹽车顧後声方重，火井窺来焰始浮。","一句黄河千載事，麦城王粲謾登楼。"]', '诗', 'shi', '', NULL, '春日投錢塘元帥尚父二首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d938ab61-c83e-4164-8d9b-64486930297c', '錢塘府亭', '錢塘府亭', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["新恩別啓館娃宮，還拜吳王向此中。","九牧土田周制在，兩藩茅社漢儀同。","春生舊苑芳洲雨，香入高臺小徑風。","更有寵光人未見，問安調膳盡三公。"]', '["新恩別啓館娃宮，還拜吳王向此中。","九牧土田周制在，兩藩茅社漢儀同。","春生旧苑芳洲雨，香入高台小徑风。","更有寵光人未见，问安調膳尽三公。"]', '诗', 'shi', '', NULL, '錢塘府亭 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c05c64a-c6d3-44fc-9c4e-2a786e425773', '野狐泉', '野狐泉', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["潏潏寒光濺路塵，相傳妖物此潛身。","又應改換皮毛後，何處人間作好人。"]', '["潏潏寒光濺路塵，相傳妖物此潛身。","又應改換皮毛後，何处人间作好人。"]', '诗', 'shi', '', NULL, '野狐泉 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be848f6b-a2a3-4e89-9afd-ad0bb68bda17', '宿紀南驛', '宿紀南驛', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["策蹇南游憶楚朝，陰風淅淅樹蕭蕭。","不知無忌姦邪骨，又作何山野葛苗。"]', '["策蹇南游憶楚朝，陰风淅淅樹蕭蕭。","不知無忌姦邪骨，又作何山野葛苗。"]', '诗', 'shi', '', NULL, '宿紀南驛 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0103da-c20c-4d6c-8e2a-7d2fd0bbb862', '贈無相禪師', '贈無相禪師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["人人盡道事空王，心裏忙於市井忙。","惟有馬當山上客，死門生路兩相忘。"]', '["人人尽道事空王，心裏忙於市井忙。","惟有马當山上客，死门生路兩相忘。"]', '诗', 'shi', '', NULL, '贈無相禪師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a3cf70-d6fd-4d19-97ed-df1721dae438', '遣興', '遣兴', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青雲路不通，歸計奈長蒙。","老恐醫方誤，窮憂酒醆空。","何堪罹亂後，更入是非中。","長短遭譏笑，迴頭避釣翁。"]', '["青云路不通，归計奈长蒙。","老恐醫方誤，窮憂酒醆空。","何堪罹亂後，更入是非中。","长短遭譏笑，迴头避釣翁。"]', '诗', 'shi', '', NULL, '遣興 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c4adf0-707b-4ad6-a613-80f09917dab3', '江夏酬高崇節', '江夏酬高崇節', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["臘雪都堂試，春風汴水行。","十年雖抱疾，何處不無情？","羣盜正當路，此游應隔生。","勞君問流落，山下已躬耕。"]', '["臘雪都堂試，春风汴水行。","十年雖抱疾，何处不無情？","羣盜正當路，此游應隔生。","勞君问流落，山下已躬耕。"]', '诗', 'shi', '', NULL, '江夏酬高崇節 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b9fddd5-a802-4367-92b4-ecaec0e7efe6', '鸎聲', '鸎声', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["井上梧桐暗，花間霧露晞。","一枝晴復暖，百囀是兼非。","金屋夢初覺，玉關人未歸。","不堪閑日聽，因爾又霑衣。"]', '["井上梧桐暗，花间霧露晞。","一枝晴复暖，百囀是兼非。","金屋梦初覺，玉关人未归。","不堪闲日听，因爾又霑衣。"]', '诗', 'shi', '', NULL, '鸎聲 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2aa0e3-f6df-4f2c-8b1c-9e3038f7d54b', '倣玉臺體', '倣玉台體', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青樓枕路隅，壁甃復椒塗。","晚夢通簾柙，春寒逼酒罏。","解吟憐芍藥，難見恨菖蒲。","試問年多少，鄰姬亦姓胡。"]', '["青楼枕路隅，壁甃复椒塗。","晚梦通簾柙，春寒逼酒罏。","解吟怜芍藥，难见恨菖蒲。","試问年多少，鄰姬亦姓胡。"]', '诗', 'shi', '', NULL, '倣玉臺體 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274e5ab1-a01e-43f1-8f4d-cb6517493786', '夜泊義興戲呈邑宰', '夜泊義兴戲呈邑宰', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["溪畔維舟問戴星，此中三害有圖經。","長橋可避南山遠，却恐難防是最靈。"]', '["溪畔維舟问戴星，此中三害有圖經。","长橋可避南山远，却恐难防是最靈。"]', '诗', 'shi', '', NULL, '夜泊義興戲呈邑宰 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a083f14-011f-4861-9615-ac6b5ac9643f', '聽琵琶', '听琵琶', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["香筵酒散思朝散，偶向梧桐暗處聞。","大底曲中皆有恨，滿樓人自不知君。"]', '["香筵酒散思朝散，偶向梧桐暗处闻。","大底曲中皆有恨，满楼人自不知君。"]', '诗', 'shi', '', NULL, '聽琵琶 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df71f7a9-3486-4c20-beb8-ed851bdf40ab', '經耒陽杜工部墓', '經耒陽杜工部墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["紫菊馨香覆楚醪，奠君江畔雨蕭騷。","旅魂自是才相累，閑骨何妨塚更高。","騄驥喪來空蹇蹶，芝蘭衰後長蓬蒿。","屈原宋玉鄰君處，幾駕青螭緩鬱陶。"]', '["紫菊馨香覆楚醪，奠君江畔雨蕭騷。","旅魂自是才相累，闲骨何妨塚更高。","騄驥喪来空蹇蹶，芝蘭衰後长蓬蒿。","屈原宋玉鄰君处，幾駕青螭緩鬱陶。"]', '诗', 'shi', '', NULL, '經耒陽杜工部墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7f881b-9e02-4400-85ce-6ab14c9dcc89', '題袁溪張逸人所居', '題袁溪張逸人所居', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蒲梢獵獵燕差差，數里溪光日落時。","芳樹文君機上錦，遠山孫壽鏡中眉。","雞窗夜靜開書卷，魚檻春深展釣絲。"]', '["蒲梢獵獵燕差差，數里溪光日落时。","芳樹文君機上錦，远山孫壽镜中眉。","雞窗夜静开书卷，鱼檻春深展釣絲。"]', '诗', 'shi', '', NULL, '題袁溪張逸人所居 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f161af-3e62-464f-97c0-d13167214eff', '昇平公主舊第', '昇平公主旧第', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["乘鳳仙人降此時，玉篇纔罷到文詞。","兩輪水磑光明照，百尺鮫綃換好詩。","帶礪山河今盡在，風流罇俎見無期。","壇場客散香街暝，惆悵齊竽取次吹。"]', '["乘鳳仙人降此时，玉篇纔罷到文词。","兩輪水磑光明照，百尺鮫綃換好诗。","带礪山河今尽在，风流罇俎见無期。","壇場客散香街暝，惆悵齊竽取次吹。"]', '诗', 'shi', '', NULL, '昇平公主舊第 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44285cc-9b71-447c-9e56-17b19fc5f4d5', '寄黔中王從事', '寄黔中王從事', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["故人刀筆事軍書，南轉黔江半月餘。","別後鄉關情幾許，近來詩酒興何如。","貪將醉袖矜鶯谷，不把瑤緘附鯉魚。","今日舉觴君莫問，生涯牢落鬢蕭疎。"]', '["故人刀笔事軍书，南轉黔江半月餘。","別後乡关情幾許，近来诗酒兴何如。","貪將醉袖矜鶯谷，不把瑤緘附鯉鱼。","今日舉觴君莫问，生涯牢落鬢蕭疎。"]', '诗', 'shi', '', NULL, '寄黔中王從事 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c898cd1-2aeb-44dc-9c99-6d8138b71cb7', '關亭春望', '关亭春望', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["關畔春雲拂馬頭，馬前春事共悠悠。","風搖岸柳長條困，露裛山花小朵愁。","信越功名高似狗，裴王氣力大於牛。","未知至竟將何用，渭水涇川一向流。"]', '["关畔春云拂马头，马前春事共悠悠。","风搖岸柳长條困，露裛山花小朵愁。","信越功名高似狗，裴王氣力大於牛。","未知至竟將何用，渭水涇川一向流。"]', '诗', 'shi', '', NULL, '關亭春望 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59cb956e-506d-4f4e-be4d-1b11d782d2b5', '寄徐濟進士', '寄徐濟進士', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["往年疎嬾共江湖，月滿花香記得無。","霜壓楚蓮秋後折，雨催蠻酒夜深酤。","紅塵偶別迷前事，丹桂相傾媿後徒。","出得函關抽得手，從來不及阮元瑜。"]', '["往年疎嬾共江湖，月满花香記得無。","霜壓楚蓮秋後折，雨催蠻酒夜深酤。","紅塵偶別迷前事，丹桂相傾媿後徒。","出得函关抽得手，從来不及阮元瑜。"]', '诗', 'shi', '', NULL, '寄徐濟進士 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ace288-8b23-4e7b-bbc0-a2906f3b418d', '寄韋贍', '寄韋贍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["石城蓑笠阻心期，落盡山花有所思。","羸馬二年蓬轉後，故人何處月明時？","風催曉雁看看別，雨脅秋蠅漸漸癡。","禪智闌干市橋酒，縱然相見只相悲。"]', '["石城蓑笠阻心期，落尽山花有所思。","羸马二年蓬轉後，故人何处月明时？","风催晓雁看看別，雨脅秋蠅漸漸癡。","禪智闌干市橋酒，縱然相见只相悲。"]', '诗', 'shi', '', NULL, '寄韋贍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c066a85-1b54-4929-834d-d43490becfa5', '霅溪晚泊寄裴庶子', '霅溪晚泊寄裴庶子', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["溪風如扇雨如絲，閑步閑吟柳惲詩。","杯酒疎狂非曩日，野花狼藉似當時。","道窮謾有依劉感，才急應無借寇期。","滿眼雲山莫相笑，與君俱是受深知。"]', '["溪风如扇雨如絲，闲步闲吟柳惲诗。","杯酒疎狂非曩日，野花狼藉似當时。","道窮謾有依劉感，才急應無借寇期。","满眼云山莫相笑，與君俱是受深知。"]', '诗', 'shi', '', NULL, '霅溪晚泊寄裴庶子 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff7711a-e6a9-4165-94b4-87e62754345f', '送姚安之赴任秋浦', '送姚安之赴任秋浦', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["官罷春坊地象雷，片帆高指貴池開。","五侯水暖魚鱗去，九子山晴雁敘來。","江夏黃童徒逞辯，廣都龐令恐非才。","到頭稱意須年少，贏得時光向酒杯。"]', '["官罷春坊地象雷，片帆高指貴池开。","五侯水暖鱼鱗去，九子山晴雁敘来。","江夏黄童徒逞辯，廣都龐令恐非才。","到头稱意須年少，贏得时光向酒杯。"]', '诗', 'shi', '', NULL, '送姚安之赴任秋浦 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4110930-1989-4cdc-a320-68d961de9cd3', '寄喬逸人', '寄喬逸人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["南經湘浦北揚州，別後風帆幾度游。","春酒誰家禁爛熳，野花何處最淹留？","欲憑尺素邊鴻嬾，未定雕梁海燕愁。","長短此行須入手，更饒君占一年秋。"]', '["南經湘浦北揚州，別後风帆幾度游。","春酒誰家禁爛熳，野花何处最淹留？","欲憑尺素邊鴻嬾，未定雕梁海燕愁。","长短此行須入手，更饒君占一年秋。"]', '诗', 'shi', '', NULL, '寄喬逸人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c590d55d-3153-4043-bf4c-4cdfc1fdeb40', '塞外', '塞外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["塞外偷兒塞內兵，聖君宵旰望升平。","碧幢未作朝廷計，白梃猶驅婦女行。","可使禦戎無上策，只應憂國是虛聲。","漢王第宅秦田土，今日將軍已自榮。"]', '["塞外偷兒塞內兵，聖君宵旰望升平。","碧幢未作朝廷計，白梃猶驱婦女行。","可使禦戎無上策，只應憂国是虛声。","漢王第宅秦田土，今日將軍已自榮。"]', '诗', 'shi', '', NULL, '塞外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7617c9fa-edf9-4d0c-9466-d49d1f18d652', '裴庶子除太僕卿因賀', '裴庶子除太僕卿因賀', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["楚珪班序未爲輕，莫惜良途副聖明。","宮省舊推皇甫謐，寺曹今得夏侯嬰。","秩隨科第臨時貴，官逐簪裾到處清。","應笑馬安虛巧宦，四迴遷轉始爲卿。"]', '["楚珪班序未爲轻，莫惜良途副聖明。","宮省旧推皇甫謐，寺曹今得夏侯嬰。","秩隨科第臨时貴，官逐簪裾到处清。","應笑马安虛巧宦，四迴遷轉始爲卿。"]', '诗', 'shi', '', NULL, '裴庶子除太僕卿因賀 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0954ea1-5991-4671-bff4-87f3fb4c5f1e', '詠史', '詠史', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蠹簡遺編試一尋，寂寥前事似如今。","徐陵筆硯珊瑚架，趙勝賓朋瑇瑁簪。","未必片言資國計，只應邪說動人心。","九原郝泚何由起，虛誤西蕃八尺金。"]', '["蠹簡遺編試一尋，寂寥前事似如今。","徐陵笔硯珊瑚架，趙勝賓朋瑇瑁簪。","未必片言資国計，只應邪说动人心。","九原郝泚何由起，虛誤西蕃八尺金。"]', '诗', 'shi', '', NULL, '詠史 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594aa891-9234-42b6-8d39-d797a55bffb3', '中元夜泊淮口', '中元夜泊淮口', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["木葉迴飄水面平，偶因孤棹已三更。","秋涼霧露侵燈下，夜靜魚龍逼岸行。","欹枕正牽題柱思，隔樓誰轉遶梁聲。","錦帆天子狂魂魄，應過揚州看月明。"]', '["木葉迴飄水面平，偶因孤棹已三更。","秋涼霧露侵灯下，夜静鱼龙逼岸行。","欹枕正牽題柱思，隔楼誰轉遶梁声。","錦帆天子狂魂魄，應過揚州看月明。"]', '诗', 'shi', '', NULL, '中元夜泊淮口 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c821c4-8e3e-4825-a465-e1839f3667b7', '寄池州鄭員外', '寄池州鄭員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["獸遶朱輪酒滿船，郡城蕭灑貴池邊。","衣同萊子曾分筆，扇似袁宏別有天。","九點好山樓上客，兩行高柳雨中煙。","陵陽百姓將何福，社舞村歌又一年。"]', '["獸遶朱輪酒满船，郡城蕭灑貴池邊。","衣同萊子曾分笔，扇似袁宏別有天。","九点好山楼上客，兩行高柳雨中煙。","陵陽百姓將何福，社舞村歌又一年。"]', '诗', 'shi', '', NULL, '寄池州鄭員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ba85be-9355-400f-b3f2-20b7349c3b8c', '歸夢', '归梦', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["陸海波濤漸漸深，一迴歸夢抵千金。","路傍草色休多事，牆外鶯聲肯有心。","日晚向隅悲斷梗，夜闌澆酒哭知音。","貪財敗陣誰相悉，鮑叔如今不可尋。"]', '["陸海波濤漸漸深，一迴归梦抵千金。","路傍草色休多事，牆外鶯声肯有心。","日晚向隅悲斷梗，夜闌澆酒哭知音。","貪財敗陣誰相悉，鲍叔如今不可尋。"]', '诗', 'shi', '', NULL, '歸夢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c0eca6-e03c-40c5-9ca2-1d86a0f70453', '送溪州使君', '送溪州使君', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["兵寇傷殘國力衰，就中南土藉良醫。","鳳銜泥詔辭丹闕，鵰倚霜風上畫旗。","官職不須輕遠地，生靈只是計臨時。","灞橋酒醆黔巫月，從此江心兩所思。"]', '["兵寇傷殘国力衰，就中南土藉良醫。","鳳銜泥詔辞丹闕，鵰倚霜风上畫旗。","官職不須轻远地，生靈只是計臨时。","灞橋酒醆黔巫月，從此江心兩所思。"]', '诗', 'shi', '', NULL, '送溪州使君 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d553bc-61c8-4108-98e9-3bcac1b7869d', '送霅川鄭員外', '送霅川鄭員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["明時塞詔列分麾，東擁朱輪出帝畿。","銅虎貴提天子印，銀魚榮傍老萊衣。","歌聽茗塢春山暖，詩詠蘋洲暮鳥飛。","知有掖垣南步在，可能須待政成歸。"]', '["明时塞詔列分麾，东擁朱輪出帝畿。","銅虎貴提天子印，銀鱼榮傍老萊衣。","歌听茗塢春山暖，诗詠蘋洲暮鸟飞。","知有掖垣南步在，可能須待政成归。"]', '诗', 'shi', '', NULL, '送霅川鄭員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c5b59b-6355-4cdd-ab2d-0e41834c3369', '酬寄右司李員外', '酬寄右司李員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["當年憶見桂枝春，自此清途未四旬。","左省望高推健筆，右曹官重得名人。","閑摛麗藻嫌秋興，靜獵遺編笑過秦。","猶把隨和向泥滓，應憐疎散任天真。"]', '["當年憶见桂枝春，自此清途未四旬。","左省望高推健笔，右曹官重得名人。","闲摛丽藻嫌秋兴，静獵遺編笑過秦。","猶把隨和向泥滓，應怜疎散任天真。"]', '诗', 'shi', '', NULL, '酬寄右司李員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72567d89-5a52-4888-9aaf-0860182f9f2c', '蓮塘驛', '蓮塘驛', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蓮塘館東初日明，蓮塘館西行人行。","隔林啼鳥似相應，當路好花疑有情。","一夢不須追往事，數杯猶可慰勞生。","莫言來去只如此，君看鬢邊霜幾莖。"]', '["蓮塘館东初日明，蓮塘館西行人行。","隔林啼鸟似相應，當路好花疑有情。","一梦不須追往事，數杯猶可慰勞生。","莫言来去只如此，君看鬢邊霜幾莖。"]', '诗', 'shi', '', NULL, '蓮塘驛 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7599d611-9bb5-487e-8134-c4502e6fe456', '甘露寺火後', '甘露寺火後', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["六朝勝事已塵埃，猶有閑人悵望來。","只道鬼神能護物，不知龍象自成灰。","犀慙水府渾非怪，燕說吳宮未是災。","還識平泉故侯否，一生蹤跡比樓臺。"]', '["六朝勝事已塵埃，猶有闲人悵望来。","只道鬼神能護物，不知龙象自成灰。","犀慙水府渾非怪，燕说吳宮未是災。","還識平泉故侯否，一生蹤跡比楼台。"]', '诗', 'shi', '', NULL, '甘露寺火後 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3142a69e-ec91-4f6b-a400-52f6ff112b1f', '春日登上元石頭故城', '春日登上元石头故城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["萬里傷心極目春，東南王氣只逡巡。","野花相笑落滿地，山鳥自驚啼傍人。","謾道城池須險阻，可知豪傑亦埃塵。","太平寺主惟輕薄，却把三公與賊臣。"]', '["万里傷心極目春，东南王氣只逡巡。","野花相笑落满地，山鸟自驚啼傍人。","謾道城池須險阻，可知豪傑亦埃塵。","太平寺主惟轻薄，却把三公與賊臣。"]', '诗', 'shi', '', NULL, '春日登上元石頭故城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5817e2-23e3-4255-a699-d30f0febe0ad', '送宣武徐巡官', '送宣武徐巡官', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["傲睨公卿二十年，東來西去只悠然。","白知關畔元非馬，玄覺壺中別有天。","漢帝詔銜應異日，梁王風雪是初筵。","臨行不惜刀圭便，愁殺長安買笑錢。"]', '["傲睨公卿二十年，东来西去只悠然。","白知关畔元非马，玄覺壺中別有天。","漢帝詔銜應異日，梁王风雪是初筵。","臨行不惜刀圭便，愁殺长安買笑錢。"]', '诗', 'shi', '', NULL, '送宣武徐巡官 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3db1c4-790d-4a9c-8150-7004586d0ed6', '冬暮寄裴郎中', '冬暮寄裴郎中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["曉髪星星入鏡宜，早年容易近年悲。","敢言得事時將晚，只恐酬恩日漸遲。","南國傾心應望速，東堂開口欲從誰。","仙郎舊有黃金約，瀝膽隳肝更禱祈。"]', '["晓髪星星入镜宜，早年容易近年悲。","敢言得事时將晚，只恐酬恩日漸遲。","南国傾心應望速，东堂开口欲從誰。","仙郎旧有黄金約，瀝膽隳肝更禱祈。"]', '诗', 'shi', '', NULL, '冬暮寄裴郎中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81cea04b-a1bf-49a5-a04b-6bdf8c82aed4', '中元甲子以辛丑駕幸蜀四首 一', '中元甲子以辛丑駕幸蜀四首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["子儀不起渾瑊亡，西幸誰人從武皇。","四海爲家雖未遠，九州多事竟難防。","已聞旰食思真將，會待畋遊致假王。","應感兩朝巡狩跡，綠槐端正驛荒涼。"]', '["子儀不起渾瑊亡，西幸誰人從武皇。","四海爲家雖未远，九州多事竟难防。","已闻旰食思真將，會待畋游致假王。","應感兩朝巡狩跡，綠槐端正驛荒涼。"]', '诗', 'shi', '', NULL, '中元甲子以辛丑駕幸蜀四首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe17864-b25a-4c21-935d-31da714a47f4', '中元甲子以辛丑駕幸蜀四首 二', '中元甲子以辛丑駕幸蜀四首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["爪牙柱石兩俱銷，一點渝塵九土搖。","敢恨甲兵爲棄物，所嗟流品誤清朝。","幾時睿算殲張角，何處愚人戴隗囂？","跪望嵕山重啓告，可能餘烈不勝妖。"]', '["爪牙柱石兩俱銷，一点渝塵九土搖。","敢恨甲兵爲棄物，所嗟流品誤清朝。","幾时睿算殲張角，何处愚人戴隗囂？","跪望嵕山重啓告，可能餘烈不勝妖。"]', '诗', 'shi', '', NULL, '中元甲子以辛丑駕幸蜀四首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7a0b2f-c70f-4cff-be01-40c9a2055cf2', '中元甲子以辛丑駕幸蜀四首 三', '中元甲子以辛丑駕幸蜀四首 三', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["邪氣奔屯瑞氣移，清平過盡到艱危。","縱饒犬彘迷常理，不奈豺狼幸此時。","九廟有靈思李令，三川悲憶恨張儀。","可憐一曲還京樂，重對紅蕉教蜀兒。"]', '["邪氣奔屯瑞氣移，清平過尽到艱危。","縱饒犬彘迷常理，不奈豺狼幸此时。","九廟有靈思李令，三川悲憶恨張儀。","可怜一曲還京乐，重对紅蕉教蜀兒。"]', '诗', 'shi', '', NULL, '中元甲子以辛丑駕幸蜀四首 三 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144dd730-1b1e-4241-b687-3503139abf8d', '中元甲子以辛丑駕幸蜀四首 四', '中元甲子以辛丑駕幸蜀四首 四', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["白丁攘臂犯長安，翠輦蒼黃路屈盤。","丹鳳有情塵外遠，玉龍無跡渡頭寒。","靜憐貴族謀身易，危惜文皇創業難。","不將不侯何計是，釣魚船上淚闌干。"]', '["白丁攘臂犯长安，翠輦蒼黄路屈盤。","丹鳳有情塵外远，玉龙無跡渡头寒。","静怜貴族謀身易，危惜文皇創業难。","不將不侯何計是，釣鱼船上泪闌干。"]', '诗', 'shi', '', NULL, '中元甲子以辛丑駕幸蜀四首 四 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe6d5e7-b600-41fe-b0bf-eacc20a2800f', '題潤州妙善前石羊', '題潤州妙善前石羊', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["紫髯桑蓋此沈吟，很石猶存事可尋。","漢鼎未安聊把手，楚醪雖滿肯同心。","英雄已往時難問，苔蘚何知日漸深。","還有市鄽沽酒客，雀喧鳩聚話蹄涔。"]', '["紫髯桑蓋此沈吟，很石猶存事可尋。","漢鼎未安聊把手，楚醪雖满肯同心。","英雄已往时难问，苔蘚何知日漸深。","還有市鄽沽酒客，雀喧鳩聚話蹄涔。"]', '诗', 'shi', '', NULL, '題潤州妙善前石羊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('564dbdf3-62d8-4e54-bed8-3332111b33da', '登宛陵條風樓寄竇常侍', '登宛陵條风楼寄竇常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["亂罹時節懶登臨，試借條風半日吟。","只有遠山含煖律，不知高閣動歸心。","溪喧晚棹千聲浪，雲護寒郊數丈陰。","自笑疎慵似麇鹿，也教臺上費黃金。"]', '["亂罹时節懶登臨，試借條风半日吟。","只有远山含煖律，不知高閣动归心。","溪喧晚棹千声浪，云護寒郊數丈陰。","自笑疎慵似麇鹿，也教台上費黄金。"]', '诗', 'shi', '', NULL, '登宛陵條風樓寄竇常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15df63b3-2839-4f86-8905-f63288586443', '臺城', '台城', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["晚雲陰暎下空城，六代纍纍夕照明。","玉井已乾龍不起，金甌雖破虎曾爭。","亦知霸世才難得，却是蒙塵事最平。","深谷作陵山作海，茂弘流輩莫傷情。"]', '["晚云陰暎下空城，六代纍纍夕照明。","玉井已乾龙不起，金甌雖破虎曾爭。","亦知霸世才难得，却是蒙塵事最平。","深谷作陵山作海，茂弘流輩莫傷情。"]', '诗', 'shi', '', NULL, '臺城 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649cca9f-4298-499e-b0a3-ad885fd23caf', '甘露寺看雪上周相公', '甘露寺看雪上周相公', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["篩寒灑白亂溟濛，禱請功兼造化功。","光薄乍迷京口月，影交初展海門風。","細黏謝客衣裾上，輕墮梁王酒醆中。","一種爲祥君看取，半禳災沴半年豐。"]', '["篩寒灑白亂溟濛，禱請功兼造化功。","光薄乍迷京口月，影交初展海门风。","細黏謝客衣裾上，轻墮梁王酒醆中。","一種爲祥君看取，半禳災沴半年豐。"]', '诗', 'shi', '', NULL, '甘露寺看雪上周相公 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('222195f8-718a-4bb2-9be1-ad8c49bf679b', '寄京闕陸郎中昆仲', '寄京闕陸郎中昆仲', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["柏臺蘭署四周旋，賓榻何妨雁影連。","纔見玳簪欹細柳，便知油幕勝紅蓮。","家從入洛聲名大，跡爲依劉事分偏。","爭奈亂罹人漸少，麥城新賦許誰傳。"]', '["柏台蘭署四周旋，賓榻何妨雁影連。","纔见玳簪欹細柳，便知油幕勝紅蓮。","家從入洛声名大，跡爲依劉事分偏。","爭奈亂罹人漸少，麦城新賦許誰傳。"]', '诗', 'shi', '', NULL, '寄京闕陸郎中昆仲 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdcfe16-ef25-4e28-8e51-51ed6beb6494', '偶題', '偶題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鍾陵醉別十餘春，重見雲英掌上身。","我未成名君未嫁，可能俱是不如人。"]', '["鍾陵醉別十餘春，重见云英掌上身。","我未成名君未嫁，可能俱是不如人。"]', '诗', 'shi', '', NULL, '偶題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0062c24e-650b-4978-ae4e-b12c65b840aa', '故都', '故都', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江南江北兩風流，一作迷津一拜侯。","至竟不如隋煬帝，破家猶得到揚州。"]', '["江南江北兩风流，一作迷津一拜侯。","至竟不如隋煬帝，破家猶得到揚州。"]', '诗', 'shi', '', NULL, '故都 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88775d50-097b-4777-a8bf-b4aaa78e73c4', '董仲舒', '董仲舒', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["災變儒生不合聞，謾將刀筆指乾坤。","偶然留得陰陽術，閉却南門又北門。"]', '["災变儒生不合闻，謾將刀笔指乾坤。","偶然留得陰陽術，閉却南门又北门。"]', '诗', 'shi', '', NULL, '董仲舒 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e55f238-9d05-48ba-b13d-b6f1cfb3a37e', '獻尚父大王', '獻尚父大王', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["數年鐵甲定東甌，夜渡江山瞻斗牛。","今日朱方平殄後，虎符龍節十三州。"]', '["數年鐵甲定东甌，夜渡江山瞻斗牛。","今日朱方平殄後，虎符龙節十三州。"]', '诗', 'shi', '', NULL, '獻尚父大王 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7513920-9e51-4c34-ae10-8ab77d73fb07', '蜂', '蜂', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["不論平地與山尖，無限風光盡被占。","採得百花成蜜後，爲誰辛苦爲誰甜。"]', '["不論平地與山尖，無限风光尽被占。","採得百花成蜜後，爲誰辛苦爲誰甜。"]', '诗', 'shi', '', NULL, '蜂 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041222a2-9c0c-4ea9-a253-8fa3a0d81d12', '簾二首 一', '簾二首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["疊影重紋暎畫堂，玉鉤銀燭共熒煌。","會應得見神仙在，休下真珠十二行。"]', '["叠影重紋暎畫堂，玉鉤銀燭共熒煌。","會應得见神仙在，休下真珠十二行。"]', '诗', 'shi', '', NULL, '簾二首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bd8d309-926b-4143-ae2c-870d7bc1927f', '簾二首 二', '簾二首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["翡翠佳名世共稀，玉堂高下巧相宜。","殷勤爲囑纖纖手，捲上銀鉤莫放垂。"]', '["翡翠佳名世共稀，玉堂高下巧相宜。","殷勤爲囑纖纖手，捲上銀鉤莫放垂。"]', '诗', 'shi', '', NULL, '簾二首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a742242a-651f-4554-9355-edd4ab8446e9', '送顧雲下第', '送顧云下第', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["行行杯酒莫辭頻，怨歎勞歌兩未伸。","漢帝後宮猶識字，楚王前殿更無人。","年深旅舍衣裳敝，潮打村田活計貧。","百歲都來多幾日，不堪相別又傷春。"]', '["行行杯酒莫辞頻，怨歎勞歌兩未伸。","漢帝後宮猶識字，楚王前殿更無人。","年深旅舍衣裳敝，潮打村田活計貧。","百歲都来多幾日，不堪相別又傷春。"]', '诗', 'shi', '', NULL, '送顧雲下第 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4fd9b0-c786-4b0e-bcdb-2120ac3484b3', '村橋', '村橋', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["村橋酒斾月明樓，偶逐漁舟繫葉舟。","莫學魯人疑海鳥，須知莊叟惡犧牛。","心寒已分灰無焰，事往曾將水共流。","除却思量太平在，肯拋疎散換公侯。"]', '["村橋酒斾月明楼，偶逐漁舟繫葉舟。","莫学魯人疑海鸟，須知莊叟惡犧牛。","心寒已分灰無焰，事往曾將水共流。","除却思量太平在，肯拋疎散換公侯。"]', '诗', 'shi', '', NULL, '村橋 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4fb78aa-cdb9-47ec-a36b-e4f8aeab16a2', '送劉校書之新安寄吳常侍', '送劉校书之新安寄吳常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["野雲如火照行塵，會績溪邊去問津。","才子省銜非幕客，楚君科第是同人。","狂思下國千場醉，病負東堂兩度春。","他日酒筵應見問，鹿裘漁艇隔朱輪。"]', '["野云如火照行塵，會績溪邊去问津。","才子省銜非幕客，楚君科第是同人。","狂思下国千場醉，病負东堂兩度春。","他日酒筵應见问，鹿裘漁艇隔朱輪。"]', '诗', 'shi', '', NULL, '送劉校書之新安寄吳常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de0e3d55-aa1b-42aa-80d1-acb65c839b05', '官池秋夕', '官池秋夕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["池邊月影閑婆娑，池上醉來成短歌。","芙渠抵死怨珠露，蟋蟀苦口嫌金波。","往事向人言不得，舊遊臨老恨空多。","松醪作酒蘭爲棹，十載煙塵奈爾何。"]', '["池邊月影闲婆娑，池上醉来成短歌。","芙渠抵死怨珠露，蟋蟀苦口嫌金波。","往事向人言不得，旧游臨老恨空多。","松醪作酒蘭爲棹，十載煙塵奈爾何。"]', '诗', 'shi', '', NULL, '官池秋夕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68505c1-99a5-45f7-a96b-8e87333be899', '奉使宛陵別二三從事', '奉使宛陵別二三從事', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["梁王雪裏有深知，偶別家鄉隔路岐。","官品共傳勝曩日，酒杯爭肯忍當時。","豫章地暖矜千尺，越嶠天寒愧一枝。","還有釣魚蓑笠在，不堪風雨失歸期。"]', '["梁王雪裏有深知，偶別家乡隔路岐。","官品共傳勝曩日，酒杯爭肯忍當时。","豫章地暖矜千尺，越嶠天寒愧一枝。","還有釣鱼蓑笠在，不堪风雨失归期。"]', '诗', 'shi', '', NULL, '奉使宛陵別二三從事 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a16d3ad-e1c9-4459-a76d-12f8672868ad', '金陵思古', '金陵思古', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["杜秋在時花解言，杜秋死後花更繁。","柔姿曼態葬何處，天紅膩白愁荒原。","高洞紫簫吹夢想，小窗殘雨濕精魂。","綺筵金縷無消息，一陣征帆過海門。"]', '["杜秋在时花解言，杜秋死後花更繁。","柔姿曼態葬何处，天紅膩白愁荒原。","高洞紫簫吹梦想，小窗殘雨濕精魂。","綺筵金縷無消息，一陣征帆過海门。"]', '诗', 'shi', '', NULL, '金陵思古 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7ea43e-04ec-40e8-9887-32f8a6abce46', '送王使君赴蘇臺', '送王使君赴蘇台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["東南一望可長吁，猶憶王孫領虎符。","兩地干戈連越絕，數年麋鹿臥姑蘇。","疲甿賦重全家盡，舊族兵侵太半無。","料得伍員兼旅寓，不妨招取好揶揄。"]', '["东南一望可长吁，猶憶王孫領虎符。","兩地干戈連越絕，數年麋鹿臥姑蘇。","疲甿賦重全家尽，旧族兵侵太半無。","料得伍員兼旅寓，不妨招取好揶揄。"]', '诗', 'shi', '', NULL, '送王使君赴蘇臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420966fc-be4c-4137-8e3e-beef4e9e88f9', '憶九華', '憶九华', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["九華巉崪廕柴扉，長憶前時此息機。","黃菊倚風村酒熟，綠蒲低雨釣魚歸。","干戈已是三年別，塵土那堪萬事違。","回首佳期恨多少，夜闌霜露又霑衣。"]', '["九华巉崪廕柴扉，长憶前时此息機。","黄菊倚风村酒熟，綠蒲低雨釣鱼归。","干戈已是三年別，塵土那堪万事違。","回首佳期恨多少，夜闌霜露又霑衣。"]', '诗', 'shi', '', NULL, '憶九華 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a73982c-926c-4f04-a40f-dc96d5ddb32d', '送裴饒歸會稽', '送裴饒归會稽', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["金庭路指剡川隈，珍重良朋自此來。","兩鬢不堪悲歲月，一巵猶得話塵埃。","家通曩分心空在，世逼橫流眼未開。","笑殺山陰雪中客，等閑乘興又須回。"]', '["金庭路指剡川隈，珍重良朋自此来。","兩鬢不堪悲歲月，一巵猶得話塵埃。","家通曩分心空在，世逼橫流眼未开。","笑殺山陰雪中客，等闲乘兴又須回。"]', '诗', 'shi', '', NULL, '送裴饒歸會稽 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd7f0b3-6258-4504-83f6-ba8f7a339991', '送程尊師之晉陵', '送程尊師之晉陵', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["棟間雲出認行軒，郊外陰陰夏木繁。","高道乍爲張翰侶，使君兼是世龍孫。","溪含句曲清連底，酒貰餘杭淥滿罇。"]', '["棟间云出認行軒，郊外陰陰夏木繁。","高道乍爲張翰侶，使君兼是世龙孫。","溪含句曲清連底，酒貰餘杭淥满罇。"]', '诗', 'shi', '', NULL, '送程尊師之晉陵 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41559dac-b084-4396-a5d1-ca37267febce', '吳門晚泊寄句曲道友', '吳门晚泊寄句曲道友', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["采香徑在人不留，采香徑下停葉舟。","桃花李花鬬紅白，山鳥水鳥自獻酬。","十萬梅鋗空寸土，三分孫策竟荒丘。","未知到了關身否，笑殺雷平許遠遊。"]', '["采香徑在人不留，采香徑下停葉舟。","桃花李花鬬紅白，山鸟水鸟自獻酬。","十万梅鋗空寸土，三分孫策竟荒丘。","未知到了关身否，笑殺雷平許远游。"]', '诗', 'shi', '', NULL, '吳門晚泊寄句曲道友 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c008f9c1-4ddc-4ed7-870b-556333d3bfcb', '貴池曉望', '貴池晓望', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["稂莠參天剪未平，且乘孤櫂且行行。","計疎狡兔無三窟，羈甚賓鴻欲一生。","合眼亦知非本意，傷心其奈是多情。","前溪好泊誰爲主，昨夜沙禽占月明。"]', '["稂莠參天剪未平，且乘孤櫂且行行。","計疎狡兔無三窟，羈甚賓鴻欲一生。","合眼亦知非本意，傷心其奈是多情。","前溪好泊誰爲主，昨夜沙禽占月明。"]', '诗', 'shi', '', NULL, '貴池曉望 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f96fb6-f725-48d0-b687-ec4821651a9f', '寄崔慶孫', '寄崔慶孫', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["故人何處又留連，月冷風高鏡水邊。","文陣解圍纔昨日，醉鄉分袂已三年。","交情澹泊應長在，俗態流離且勉旃。","還擬山陰一乘興，雪寒難得渡江船。"]', '["故人何处又留連，月冷风高镜水邊。","文陣解圍纔昨日，醉乡分袂已三年。","交情澹泊應长在，俗態流離且勉旃。","還擬山陰一乘兴，雪寒难得渡江船。"]', '诗', 'shi', '', NULL, '寄崔慶孫 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70f489e5-ec50-4b47-8039-beeb7b5d5a76', '寄楊秘書', '寄楊秘书', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蕭蕭檐雪打窗聲，因憶江東阮步兵。","兩信海潮書不達，數峰稽嶺眼長明。","梅繁幾處垂鞭看，酒好何人倚檻傾。","會待與君開秫甕，滿船般載鏡中行。"]', '["蕭蕭檐雪打窗声，因憶江东阮步兵。","兩信海潮书不達，數峰稽嶺眼长明。","梅繁幾处垂鞭看，酒好何人倚檻傾。","會待與君开秫甕，满船般載镜中行。"]', '诗', 'shi', '', NULL, '寄楊秘書 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a8961e-2d55-4199-9412-9d5778c4c13e', '酬章處士見寄', '酬章处士见寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中原甲馬未曾安，今日逢君事萬端。","亂後幾回鄉夢隔，別來何處路行難。","霜鱗共落三門浪，雪鬢同歸七里灘。","何必新詩更相戲，小樓吟罷暮天寒。"]', '["中原甲马未曾安，今日逢君事万端。","亂後幾回乡梦隔，別来何处路行难。","霜鱗共落三门浪，雪鬢同归七里灘。","何必新诗更相戲，小楼吟罷暮天寒。"]', '诗', 'shi', '', NULL, '酬章處士見寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef7f30b0-195c-4f2e-8bd9-622a3d5bd920', '送丁明府赴紫溪任', '送丁明府赴紫溪任', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["金徽玉軫肯躇[躕]，偶滯良途半月餘。","樓上酒闌梅拆後，馬前山好雪晴初。","欒公社在憐鄉樹，潘令花繁賀版輿。","縣譜莫辭留舊本，異時量度更何如。"]', '["金徽玉軫肯躇[躕]，偶滯良途半月餘。","楼上酒闌梅拆後，马前山好雪晴初。","欒公社在怜乡樹，潘令花繁賀版輿。","縣譜莫辞留旧本，異时量度更何如。"]', '诗', 'shi', '', NULL, '送丁明府赴紫溪任 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e2977f-0092-4218-938e-4663d8cc46fd', '寄前宣州竇常侍', '寄前宣州竇常侍', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["往年西謁謝玄暉，罇酒留歡醉始歸。","曲檻柳濃鶯未老，小園花煖蝶初飛。","噴香瑞獸金三尺，舞雪佳人玉一圍。","今日亂罹尋不得，滿蓑風雨釣魚磯。"]', '["往年西謁謝玄暉，罇酒留歡醉始归。","曲檻柳濃鶯未老，小园花煖蝶初飞。","噴香瑞獸金三尺，舞雪佳人玉一圍。","今日亂罹尋不得，满蓑风雨釣鱼磯。"]', '诗', 'shi', '', NULL, '寄前宣州竇常侍 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de880f4-5373-4b36-9420-fb3eee9ffa84', '秦望山僧院', '秦望山僧院', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["巉巉危岫倚滄洲，聞說秦皇亦此遊。","霸主卷衣纔二世，老僧傳錫已千秋。","陰崖水賴松梢直，蘚壁苔侵畫像愁。","各是病來俱未了，莫將煩惱問湯休。"]', '["巉巉危岫倚滄洲，闻说秦皇亦此游。","霸主卷衣纔二世，老僧傳錫已千秋。","陰崖水賴松梢直，蘚壁苔侵畫像愁。","各是病来俱未了，莫將煩惱问湯休。"]', '诗', 'shi', '', NULL, '秦望山僧院 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('677c599a-f6f6-439f-a766-a4227b2d96dc', '送光祿崔卿赴闕', '送光祿崔卿赴闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一年極目望西轅，此日殷勤聖主恩。","上國已留虞寄命，中朝應聽范汪言。","官從府幕歸卿寺，路向干戈見禁門。","鵷侶寂寥曹署冷，更堪嗚咽問田園。"]', '["一年極目望西轅，此日殷勤聖主恩。","上国已留虞寄命，中朝應听范汪言。","官從府幕归卿寺，路向干戈见禁门。","鵷侶寂寥曹署冷，更堪嗚咽问田园。"]', '诗', 'shi', '', NULL, '送光祿崔卿赴闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa4016e-ccab-445d-a39b-3f6d495a9cef', '寄程尊師', '寄程尊師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["鶴信雖然到五湖，煙波迢遰路崎嶇。","玉書分薄花生眼，金鼎功遲雪滿鬚。","三秀紫芝勞夢寐，一番紅槿恨朝晡。","未知朽敗凡間骨，中授先生指教無。"]', '["鹤信雖然到五湖，煙波迢遰路崎嶇。","玉书分薄花生眼，金鼎功遲雪满鬚。","三秀紫芝勞梦寐，一番紅槿恨朝晡。","未知朽敗凡间骨，中授先生指教無。"]', '诗', 'shi', '', NULL, '寄程尊師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6101a577-e246-46c7-b451-000521d1f2bb', '定遠樓', '定远楼', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["前年上將定妖氛，曾築巖城駐大軍。","近日關防雖弛柝，舊時欄檻尚侵雲。","蠻兵績盛人皆伏，坐石名高世共聞。","唯恐亂來良吏少，不知誰解敘功勳。"]', '["前年上將定妖氛，曾築巖城駐大軍。","近日关防雖弛柝，旧时欄檻尚侵云。","蠻兵績盛人皆伏，坐石名高世共闻。","唯恐亂来良吏少，不知誰解敘功勳。"]', '诗', 'shi', '', NULL, '定遠樓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b24c44c9-d48a-4d7f-ba13-be8433a97c2f', '送程尊師東遊有寄', '送程尊師东游有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["華蓋峰前擬卜耕，主人無奈又閑行。","且憑鶴駕尋滄海，又恐犀軒過赤城。","絳簡便應朝右弼，紫旄兼合見東卿。","勸君莫忘歸時節，芝似螢光處處生。"]', '["华蓋峰前擬卜耕，主人無奈又闲行。","且憑鹤駕尋滄海，又恐犀軒過赤城。","絳簡便應朝右弼，紫旄兼合见东卿。","勸君莫忘归时節，芝似螢光处处生。"]', '诗', 'shi', '', NULL, '送程尊師東遊有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b599447-34c3-46ef-a55c-cfac2584aee2', '江亭別裴饒', '江亭別裴饒', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["行杯且待怨歌終，多病憐君事事同。","衰鬢別來光景裏，故鄉歸去亂罹中。","乾坤墊裂三分在，井邑摧殘一半空。","日晚長亭問西使，不堪車馬尚萍蓬。"]', '["行杯且待怨歌終，多病怜君事事同。","衰鬢別来光景裏，故乡归去亂罹中。","乾坤墊裂三分在，井邑摧殘一半空。","日晚长亭问西使，不堪车马尚萍蓬。"]', '诗', 'shi', '', NULL, '江亭別裴饒 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d15499-e147-430b-9a5b-ea45bd6e1eaf', '江南寄所知周僕射', '江南寄所知周僕射', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["曾陪公子醉西園，峴首碑前事嬾言。","世亂共嗟王粲老，時危俱受信陵恩。","潮憐把醆吟江徼，雨憶凭闌望海門。","飛蓋寂寥清宴罷，不知簪履更誰存。"]', '["曾陪公子醉西园，峴首碑前事嬾言。","世亂共嗟王粲老，时危俱受信陵恩。","潮怜把醆吟江徼，雨憶凭闌望海门。","飞蓋寂寥清宴罷，不知簪履更誰存。"]', '诗', 'shi', '', NULL, '江南寄所知周僕射 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a92305b-7497-4ed5-979a-f0eb89d170a7', '錢唐見芮逢', '錢唐见芮逢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["蔡倫池北雁峰前，罹亂相兼十九年。","所喜故人猶會面，不堪良牧已重泉。","醉思把筯欹歌席，狂憶判身入酒船。","今日與君贏得在，戴家灣裏兩皤然。"]', '["蔡倫池北雁峰前，罹亂相兼十九年。","所喜故人猶會面，不堪良牧已重泉。","醉思把筯欹歌席，狂憶判身入酒船。","今日與君贏得在，戴家灣裏兩皤然。"]', '诗', 'shi', '', NULL, '錢唐見芮逢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd14c86-ad99-4dcc-a5d0-c51aaad5329b', '江都', '江都', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["淮王高讌動江都，曾憶狂生亦坐隅。","九里樓臺牽翡翠，兩行鴛鷺踏真珠。","歌聽麗句秦雲咽，詩轉新題蜀錦鋪。","惆悵晉陽星拆後，世間兵革地荒蕪。"]', '["淮王高讌动江都，曾憶狂生亦坐隅。","九里楼台牽翡翠，兩行鴛鷺踏真珠。","歌听丽句秦云咽，诗轉新題蜀錦鋪。","惆悵晉陽星拆後，世间兵革地荒蕪。"]', '诗', 'shi', '', NULL, '江都 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d5aab7-719f-4885-a33a-34f115c93731', '湖上歲暮感懷有寄友人', '湖上歲暮感懷有寄友人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雪天螢席幾辛勤，同志當時四五人。","蘭版地寒俱[受]露，桂堂風惡獨傷春。","音書久絕應埋玉，編簡難言竟委塵。","唯有廣都龐令在，白頭罇酒憶交親。"]', '["雪天螢席幾辛勤，同志當时四五人。","蘭版地寒俱[受]露，桂堂风惡独傷春。","音书久絕應埋玉，編簡难言竟委塵。","唯有廣都龐令在，白头罇酒憶交親。"]', '诗', 'shi', '', NULL, '湖上歲暮感懷有寄友人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a0a9c9-3322-4505-9bdf-b028ee16fc32', '送張綰游鍾陵', '送張綰游鍾陵', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["南憶龍沙兩岸行，當時天下尚清平。","醉眠野寺花方落，吟倚江樓月欲明。","老去亦知難重到，亂來爭肯不牽情。","西山十二真人在，從此煩君語姓名。"]', '["南憶龙沙兩岸行，當时天下尚清平。","醉眠野寺花方落，吟倚江楼月欲明。","老去亦知难重到，亂来爭肯不牽情。","西山十二真人在，從此煩君語姓名。"]', '诗', 'shi', '', NULL, '送張綰游鍾陵 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c210de-b965-48fd-ab4f-1275dfbe2d24', '送{巩/言}光大師', '送{巩/言}光大師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["禹祠分首戴灣逢，健筆尋知達九重。","聖主賜衣憐絕藝，侍臣摛藻許高蹤。","寧親久別街西寺，待詔初離海上峰。","一種苦心師得了，不須回首笑龍鍾。"]', '["禹祠分首戴灣逢，健笔尋知達九重。","聖主賜衣怜絕藝，侍臣摛藻許高蹤。","寧親久別街西寺，待詔初離海上峰。","一種苦心師得了，不須回首笑龙鍾。"]', '诗', 'shi', '', NULL, '送{巩/言}光大師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09941bcf-4168-41c5-a3c1-3e4941f6d802', '息夫人廟', '息夫人廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["百雉摧殘連野青，廟門猶見昔朝廷。","一生雖抱楚王恨，千載終爲息地靈。","蟲網翠環終縹緲，風吹寶瑟助微冥。","玉顏渾似羞來客，依舊無言照畫屏。"]', '["百雉摧殘連野青，廟门猶见昔朝廷。","一生雖抱楚王恨，千載終爲息地靈。","蟲網翠环終縹緲，风吹寶瑟助微冥。","玉顏渾似羞来客，依旧無言照畫屏。"]', '诗', 'shi', '', NULL, '息夫人廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cebcbc22-16f4-4384-9dd5-21a0411e2f34', '漂母塚', '漂母塚', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寂寂荒墳一水濱，蘆洲絕島自相親。","青娥已落淮邊月，白骨甘爲泉下塵。","原上荻花飄素髪，道傍菰葉碎羅巾。","雖然寂寞千秋魄，猶是韓侯舊主人。"]', '["寂寂荒墳一水濱，蘆洲絕島自相親。","青娥已落淮邊月，白骨甘爲泉下塵。","原上荻花飄素髪，道傍菰葉碎羅巾。","雖然寂寞千秋魄，猶是韓侯旧主人。"]', '诗', 'shi', '', NULL, '漂母塚 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8d8a66-2da9-425d-813a-eea228a8d09f', '感懷', '感懷', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["石徑松軒亦自由，謾隨浮世逐飄流。","駑駘路結前程恨，蟋蟀床生半夜秋。","揜耳惡聞宮妾語，低顏須向路人羞。","雖教小事相催逼，未到青雲擬白頭。"]', '["石徑松軒亦自由，謾隨浮世逐飄流。","駑駘路結前程恨，蟋蟀床生半夜秋。","揜耳惡闻宮妾語，低顏須向路人羞。","雖教小事相催逼，未到青云擬白头。"]', '诗', 'shi', '', NULL, '感懷 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4711cb1e-1139-4d70-870f-be1ed149e06d', '扇上畫牡丹', '扇上畫牡丹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["爲愛紅芳滿砌堦，教人扇上畫將來。","葉隨彩筆參差長，花逐輕風吹第開。","閑挂幾曾停蛺蜨，頻搖不怕落莓苔。","根生無地如仙桂，疑是姮娥月裏栽。"]', '["爲愛紅芳满砌堦，教人扇上畫將来。","葉隨彩笔參差长，花逐轻风吹第开。","闲挂幾曾停蛺蜨，頻搖不怕落莓苔。","根生無地如仙桂，疑是姮娥月裏栽。"]', '诗', 'shi', '', NULL, '扇上畫牡丹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a724d990-45eb-45ba-83ed-aae74c3c4028', '書懷', '书懷', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["釣船拋却異鄉來，擬向何門用不才。","日晚獨登樓上望，馬蹄車轍滿塵埃。"]', '["釣船拋却異乡来，擬向何门用不才。","日晚独登楼上望，马蹄车轍满塵埃。"]', '诗', 'shi', '', NULL, '書懷 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b7195e-2b66-4935-868e-679f9419bf43', '七夕', '七夕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["月帳星房次第開，兩情惟恐曙光催。","時人不用穿鍼待，沒得心情送巧來。"]', '["月帳星房次第开，兩情惟恐曙光催。","时人不用穿鍼待，沒得心情送巧来。"]', '诗', 'shi', '', NULL, '七夕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbaba50-ee8f-4aed-b8a3-76de8820ad59', '柳', '柳', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一簇青煙鎖玉樓，半垂闌畔半垂溝。","明年更有新條在，繞亂春風卒未休。"]', '["一簇青煙鎖玉楼，半垂闌畔半垂溝。","明年更有新條在，繞亂春风卒未休。"]', '诗', 'shi', '', NULL, '柳 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b5f696-3eae-4a5c-93c0-74a6d31677dd', '羅敷水', '羅敷水', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雉聲角角野田春，試駐征車問水濱。","數樹枯桑雖不語，思量應合識秦人。"]', '["雉声角角野田春，試駐征车问水濱。","數樹枯桑雖不語，思量應合識秦人。"]', '诗', 'shi', '', NULL, '羅敷水 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbdbf4e-0e7b-4e8f-b9bb-0b0d910f1b24', '京中正月七日立春', '京中正月七日立春', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一二三四五六七，萬木生芽是今日。","遠天歸雁拂雲飛，近水遊魚迸冰出。"]', '["一二三四五六七，万木生芽是今日。","远天归雁拂云飞，近水游鱼迸冰出。"]', '诗', 'shi', '', NULL, '京中正月七日立春 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d648ad-eb39-45ac-b3e7-e6ad133e39cd', '貴游', '貴游', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["館陶園外雨初晴，繡轂香車入鳳城。","八尺家僮三尺箠，何知高祖要蒼生。"]', '["館陶园外雨初晴，繡轂香车入鳳城。","八尺家僮三尺箠，何知高祖要蒼生。"]', '诗', 'shi', '', NULL, '貴游 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea74125-a999-437c-b429-50d484d27f3b', '嚴陵灘', '嚴陵灘', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中都九鼎勤英髦，漁釣牛蓑且遁逃。","世祖升遐夫子死，原陵不及釣臺高。"]', '["中都九鼎勤英髦，漁釣牛蓑且遁逃。","世祖升遐夫子死，原陵不及釣台高。"]', '诗', 'shi', '', NULL, '嚴陵灘 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d312188d-6a0f-471f-b359-f613ac79e84f', '虛白堂前牡丹相傳云太傅手植在錢塘', '虛白堂前牡丹相傳云太傅手植在錢塘', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["欲詢往事奈無言，六十年來託此根。","香暖幾飄袁虎扇，格高常對孔融罇。","曾憂世亂陰難合，且喜春殘色上存。","莫背闌干便相笑，與君俱受主人恩。"]', '["欲詢往事奈無言，六十年来託此根。","香暖幾飄袁虎扇，格高常对孔融罇。","曾憂世亂陰难合，且喜春殘色上存。","莫背闌干便相笑，與君俱受主人恩。"]', '诗', 'shi', '', NULL, '虛白堂前牡丹相傳云太傅手植在錢塘 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42aaf6ae-5478-4d8a-bd32-be4b97a5073a', '縣齋秋晚酬友人朱瓚見寄', '縣斋秋晚酬友人朱瓚见寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中和節後捧瓊瑰，坐讀行吟數月來。","只歎雕龍方擅價，不知赬尾竟空回。","千枝白露陶潛柳，百尺黃金郭隗臺。","惆悵報君無玉案，水天東望一裴回。"]', '["中和節後捧瓊瑰，坐读行吟數月来。","只歎雕龙方擅價，不知赬尾竟空回。","千枝白露陶潛柳，百尺黄金郭隗台。","惆悵報君無玉案，水天东望一裴回。"]', '诗', 'shi', '', NULL, '縣齋秋晚酬友人朱瓚見寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b2ca6f-22d3-4213-84e9-9f57691e4988', '第五將軍于餘杭天柱宮入道因題寄', '第五將軍于餘杭天柱宮入道因題寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["交棃火棗味何如，聞說苕川已下車。","瓦榼尚攜京口酒，草堂應寫潁陽書。","亦知得意須乘鶴，未必忘機便釣魚。","欲恐武皇還望祀，軟輪徵入問玄虛。"]', '["交棃火棗味何如，闻说苕川已下车。","瓦榼尚携京口酒，草堂應寫潁陽书。","亦知得意須乘鹤，未必忘機便釣鱼。","欲恐武皇還望祀，軟輪徵入问玄虛。"]', '诗', 'shi', '', NULL, '第五將軍于餘杭天柱宮入道因題寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1959433c-2d93-4d1e-bb6c-bcba84bc7a1c', '寄無相禪師', '寄無相禪師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["老住西峰第幾層，爲師回首憶南能。","有緣有相應非佛，無我無人始是僧。","爛椹作袍名復利，鑠金爲講愛兼憎。","何如一衲塵埃外，日日香煙夜夜燈。"]', '["老住西峰第幾層，爲師回首憶南能。","有緣有相應非佛，無我無人始是僧。","爛椹作袍名复利，鑠金爲講愛兼憎。","何如一衲塵埃外，日日香煙夜夜灯。"]', '诗', 'shi', '', NULL, '寄無相禪師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('860a14fe-e927-43ef-a579-a966dd6525d9', '秋日有寄', '秋日有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["丹青未合便回頭，見盡人閒事始休。","只有百神朝寶鏡，永無纖浪犯虛舟。","曾臨鐵甕雖分職，近得金陵亦偶遊。","東去西來人不會，上卿踪跡本玄洲。"]', '["丹青未合便回头，见尽人閒事始休。","只有百神朝寶镜，永無纖浪犯虛舟。","曾臨鐵甕雖分職，近得金陵亦偶游。","东去西来人不會，上卿踪跡本玄洲。"]', '诗', 'shi', '', NULL, '秋日有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4963dc-7a73-41a9-951a-475b2c20fee8', '送前南昌崔令替任映攝新城縣', '送前南昌崔令替任映攝新城縣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["五年苛政甚蟲螟，深喜夫君已戴星。","大族不唯專禮樂，上才終是惜生靈。","亦知單父琴猶在，莫厭東歸酒未醒。","二月春風何處好，亞夫營畔柳青青。"]', '["五年苛政甚蟲螟，深喜夫君已戴星。","大族不唯專禮乐，上才終是惜生靈。","亦知單父琴猶在，莫厭东归酒未醒。","二月春风何处好，亞夫營畔柳青青。"]', '诗', 'shi', '', NULL, '送前南昌崔令替任映攝新城縣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0921c427-83e4-47aa-aff9-38f0edc6cb30', '下第作', '下第作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["年年模樣一般般，何似東歸把釣竿。","嵒谷謾勞思雨露，彩雲終是逐鵷鸞。","塵迷魏闕身應老，水到吳門葉欲殘。","至竟窮途也須達，才能長與世人看。"]', '["年年模樣一般般，何似东归把釣竿。","嵒谷謾勞思雨露，彩云終是逐鵷鸾。","塵迷魏闕身應老，水到吳门葉欲殘。","至竟窮途也須達，才能长與世人看。"]', '诗', 'shi', '', NULL, '下第作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06122850-e2d5-4e8d-ae8b-03ea47f02d60', '丁亥歲作', '丁亥歲作', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["病想醫門渴望梅，十年心地僅成灰。","早知世事長如此，自是孤寒不合來。","谷畔氣濃高蔽日，蟄邊聲煖乍聞雷。","滿城桃李君看取，一一還從舊處開。"]', '["病想醫门渴望梅，十年心地僅成灰。","早知世事长如此，自是孤寒不合来。","谷畔氣濃高蔽日，蟄邊声煖乍闻雷。","满城桃李君看取，一一還從旧处开。"]', '诗', 'shi', '', NULL, '丁亥歲作 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e6c7afe-d709-472a-a611-b3a436878615', '北邙山', '北邙山', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一種山前路入秦，嵩山堪愛此傷神。","魏明未死虛留意，莊叟雖生酌滿巾。","何必更尋無主骨，也知曾有弄權人。","羨他緱嶺吹簫客，閑訪雲頭看俗塵。"]', '["一種山前路入秦，嵩山堪愛此傷神。","魏明未死虛留意，莊叟雖生酌满巾。","何必更尋無主骨，也知曾有弄權人。","羨他緱嶺吹簫客，闲訪云头看俗塵。"]', '诗', 'shi', '', NULL, '北邙山 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af802af-9104-444a-85cc-9f01a3f2d511', '重過三衢哭孫員外', '重過三衢哭孫員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["爛柯山下忍重到，雙檜樓前日欲殘。","華屋未移春照灼，故侯何在淚汍瀾。","不唯濟物工夫大，長憶容才尺度寬。","一慟旁人莫相笑，知音衰盡路行難。"]', '["爛柯山下忍重到，雙檜楼前日欲殘。","华屋未移春照灼，故侯何在泪汍瀾。","不唯濟物工夫大，长憶容才尺度寬。","一慟旁人莫相笑，知音衰尽路行难。"]', '诗', 'shi', '', NULL, '重過三衢哭孫員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad88e8e-d295-4d9a-97b8-bcbdcbe0a229', '送蘄州裴員外', '送蘄州裴員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["六枝仙桂最先春，蕭灑高辭九陌塵。","兩晉家聲須有主，六朝文雅別無人。","榮驅豹尾拋同輩，貴上螭頭見近臣。","蘄水蒼生莫相羨，早看歸去掌絲綸。"]', '["六枝仙桂最先春，蕭灑高辞九陌塵。","兩晉家声須有主，六朝文雅別無人。","榮驱豹尾拋同輩，貴上螭头见近臣。","蘄水蒼生莫相羨，早看归去掌絲綸。"]', '诗', 'shi', '', NULL, '送蘄州裴員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254e8d60-2913-44d3-9360-01a328651127', '重九日廣陵道中', '重九日廣陵道中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秋山抱病何處登，前時韋曲今廣陵。","廣陵大醉不解悶，韋曲舊遊堪拊膺。","佳節縱饒隨分過，流年無奈得人憎。","却驅羸馬向前去，牢落路岐非所能。"]', '["秋山抱病何处登，前时韋曲今廣陵。","廣陵大醉不解悶，韋曲旧游堪拊膺。","佳節縱饒隨分過，流年無奈得人憎。","却驱羸马向前去，牢落路岐非所能。"]', '诗', 'shi', '', NULL, '重九日廣陵道中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8bd7953-fdbf-42f7-b4b4-ffa39d44571b', '東歸別所知', '东归別所知', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["芙蓉宮闕二妃壇，兩處因依五歲寒。","鄒律有風吹不變，郄枝無分住應難。","愁心似火還燒鬢，別淚非珠謾落盤。","却羨淮南好雞犬，也能終始逐劉安。"]', '["芙蓉宮闕二妃壇，兩处因依五歲寒。","鄒律有风吹不变，郄枝無分住應难。","愁心似火還燒鬢，別泪非珠謾落盤。","却羨淮南好雞犬，也能終始逐劉安。"]', '诗', 'shi', '', NULL, '東歸別所知 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8d0496-b8fb-4cc5-b59b-8a67cb611e66', '旅舍書懷寄所知二首 一', '旅舍书懷寄所知二首 一', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["思量前事不堪尋，牢落餘情滿素琴。","四海豈無騰躍路，一家長有別離心。","道從汩沒甘雌伏，跡恐因循更陸沈。","寂寞誰應弔空館，異鄉時節獨霑襟。"]', '["思量前事不堪尋，牢落餘情满素琴。","四海豈無腾躍路，一家长有別離心。","道從汩沒甘雌伏，跡恐因循更陸沈。","寂寞誰應弔空館，異乡时節独霑襟。"]', '诗', 'shi', '', NULL, '旅舍書懷寄所知二首 一 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01761e1-66ca-440f-ad31-9a610dea9514', '旅舍書懷寄所知二首 二', '旅舍书懷寄所知二首 二', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["簟卷兩牀琴瑟秋，暫憑前計奈相尤。","塵飄馬尾甘蓬轉，酒憶江邊有夢留。","隋帝舊祠雖寂寞，楚妃清唱亦風流。","可憐別恨無人見，獨背殘陽下寺樓。"]', '["簟卷兩牀琴瑟秋，暫憑前計奈相尤。","塵飄马尾甘蓬轉，酒憶江邊有梦留。","隋帝旧祠雖寂寞，楚妃清唱亦风流。","可怜別恨無人见，独背殘陽下寺楼。"]', '诗', 'shi', '', NULL, '旅舍書懷寄所知二首 二 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa54def-386d-4a9b-81a6-002102127901', '西京道中', '西京道中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["半夜秋聲獨斷蓬，百年身事筭成空。","禰生詞賦拋江夏，漢祖精神憶沛中。","未必他時能富貴，只應從此見窮通。","邊禽隴水休相笑，自有滄洲一棹風。"]', '["半夜秋声独斷蓬，百年身事筭成空。","禰生词賦拋江夏，漢祖精神憶沛中。","未必他时能富貴，只應從此见窮通。","邊禽隴水休相笑，自有滄洲一棹风。"]', '诗', 'shi', '', NULL, '西京道中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44053ed-a02a-448d-b685-aa934cd36755', '粉', '粉', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["每持纖白助君時，霜自無憀雪自疑。","郎若姓何應解傅，女能窺宋不勞施。","妝成麗色唯花妬，落盡啼痕只鏡知。","最好玉京仙署裏，更知秋月照瓊枝。"]', '["每持纖白助君时，霜自無憀雪自疑。","郎若姓何應解傅，女能窺宋不勞施。","妝成丽色唯花妬，落尽啼痕只镜知。","最好玉京仙署裏，更知秋月照瓊枝。"]', '诗', 'shi', '', NULL, '粉 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee650e5-e9fc-410a-8e67-736f0ea4ea07', '贈漁翁', '贈漁翁', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["葉艇悠揚鶴髪垂，生涯空託一綸絲。","是非不向眼前起，寒暑任從波上移。","風瀁長歌籠月裏，夢和春雨晝眠時。","逍遙此意誰人會，應有青山淥水知。"]', '["葉艇悠揚鹤髪垂，生涯空託一綸絲。","是非不向眼前起，寒暑任從波上移。","风瀁长歌籠月裏，梦和春雨晝眠时。","逍遙此意誰人會，應有青山淥水知。"]', '诗', 'shi', '', NULL, '贈漁翁 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d752ce-b1ab-413f-a91f-26a04f59c54f', '下第寄張坤', '下第寄張坤', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["謾費精神掉五侯，破琴孤劒是身讐。","九衢護闕擬何去，玉壘銅梁空舊遊。","蝴蝶有情牽晚夢，杜鵑無賴伴春愁。","思量不及張公子，經歲池江倚酒樓。"]', '["謾費精神掉五侯，破琴孤劒是身讐。","九衢護闕擬何去，玉壘銅梁空旧游。","蝴蝶有情牽晚梦，杜鵑無賴伴春愁。","思量不及張公子，經歲池江倚酒楼。"]', '诗', 'shi', '', NULL, '下第寄張坤 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db6276d-22da-4c7e-8ebe-4ff07748f1c3', '東歸別常修', '东归別常修', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["六載辛勤九陌中，却尋歸路五湖東。","名慙桂苑一枝綠，鱠憶松江兩筯紅。","浮世到頭須適性，男兒何必盡成功。","唯慙鮑叔深知我，他日蒲帆百尺風。"]', '["六載辛勤九陌中，却尋归路五湖东。","名慙桂苑一枝綠，鱠憶松江兩筯紅。","浮世到头須適性，男兒何必尽成功。","唯慙鲍叔深知我，他日蒲帆百尺风。"]', '诗', 'shi', '', NULL, '東歸別常修 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48bacbae-c4d2-45a0-93e9-b6daa8b51e15', '言', '言', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["珪玷由來尚可磨，似簧終日復如何。","成名成事皆因慎，亡國亡家只爲多。","須信禍胎生利口，莫將譏思逞懸河。","猩猩鸚鵡無端解，長向人間被網羅。"]', '["珪玷由来尚可磨，似簧終日复如何。","成名成事皆因慎，亡国亡家只爲多。","須信禍胎生利口，莫將譏思逞懸河。","猩猩鸚鵡無端解，长向人间被網羅。"]', '诗', 'shi', '', NULL, '言 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37b8021-3571-4d44-974d-e0c28b209f0b', '簡令生日', '簡令生日', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["祥煙靄靄拂樓臺，慶積玄元節後來。","已向青陽標四序，便從嵩嶽應三台。","龜銜玉柄增年筭，鶴舞瓊筵獻壽杯。","自顧下儒何以祝，柱天功業濟時才。"]', '["祥煙靄靄拂楼台，慶積玄元節後来。","已向青陽標四序，便從嵩嶽應三台。","龟銜玉柄增年筭，鹤舞瓊筵獻壽杯。","自顧下儒何以祝，柱天功業濟时才。"]', '诗', 'shi', '', NULL, '簡令生日 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee74800-56eb-4d0b-9644-52094e1dbf50', '晚眺', '晚眺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["凭古城邊眺晚晴，遠村高樹轉分明。","天如鏡面都來靜，地似人心總不平。","雲向嶺頭閑不徹，水流溪裏太忙生。","誰人得及莊居老，免被榮枯寵辱驚。"]', '["凭古城邊眺晚晴，远村高樹轉分明。","天如镜面都来静，地似人心總不平。","云向嶺头闲不徹，水流溪裏太忙生。","誰人得及莊居老，免被榮枯寵辱驚。"]', '诗', 'shi', '', NULL, '晚眺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a0d6e69-ee2c-4bdb-97a4-f5673fc378a2', '野花', '野花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["萬點紅芳血色殷，爲無名字對空山。","多映戲蜨尋香住，少有行人輟櫂攀。","若在侯門看不足，爲生江岸見如閑。","結根必竟輸桃李，長向春城紫陌間。"]', '["万点紅芳血色殷，爲無名字对空山。","多映戲蜨尋香住，少有行人輟櫂攀。","若在侯门看不足，爲生江岸见如闲。","結根必竟輸桃李，长向春城紫陌间。"]', '诗', 'shi', '', NULL, '野花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c78173-41c5-4d03-9e37-8cc2b02876ec', '病驄馬', '病驄马', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["櫪上病驄蹄褭褭，江邊廢宅路迢迢。","自經梅雨長垂耳，乍食菰漿欲折腰。","金絡銜頭光未滅，玉花毛色瘦來焦。","曾聽禁漏驚街鼓，慣踏康莊怕小橋。","夜半雄聲心尚壯，日中高臥尾還搖。","龍媒落地天池遠，何事牽牛在碧霄。"]', '["櫪上病驄蹄褭褭，江邊廢宅路迢迢。","自經梅雨长垂耳，乍食菰漿欲折腰。","金絡銜头光未滅，玉花毛色瘦来焦。","曾听禁漏驚街鼓，慣踏康莊怕小橋。","夜半雄声心尚壯，日中高臥尾還搖。","龙媒落地天池远，何事牽牛在碧霄。"]', '诗', 'shi', '', NULL, '病驄馬 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5c30c2-fb5e-41bc-8c8c-0bb1115cf94d', '狄浦', '狄浦', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["晴川倚落暉，極目思依依。","野色寒來淺，人家亂後稀。","久貧身不達，多病意長違。","還有漁舟在，時時夢裏歸。"]', '["晴川倚落暉，極目思依依。","野色寒来淺，人家亂後稀。","久貧身不達，多病意长違。","還有漁舟在，时时梦裏归。"]', '诗', 'shi', '', NULL, '狄浦 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9289c3bc-1558-423d-859f-64da2a242c51', '南康道中', '南康道中', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["弱冠負文翰，此中聽鹿鳴。","使君延上榻，時輩仰前程。","丹桂竟多故，白雲空有情。","唯餘路旁淚，霑灑向塵纓。"]', '["弱冠負文翰，此中听鹿鳴。","使君延上榻，时輩仰前程。","丹桂竟多故，白云空有情。","唯餘路旁泪，霑灑向塵纓。"]', '诗', 'shi', '', NULL, '南康道中 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b57d4268-2cf1-42f2-b87b-51d921d2176c', '北固亭東望寄默師', '北固亭东望寄默師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["高亭暮色中，往事更誰同。","水謾矜天闊，山應到此窮。","病憐京口酒，老怯海門風。","唯有言堪解，何由見遠公。"]', '["高亭暮色中，往事更誰同。","水謾矜天闊，山應到此窮。","病怜京口酒，老怯海门风。","唯有言堪解，何由见远公。"]', '诗', 'shi', '', NULL, '北固亭東望寄默師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5054aa7-3d44-4983-b847-c33de498ca7e', '華清宮', '华清宮', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["樓殿層層佳氣多，開元時節好笙歌。","也知道德勝堯舜，爭奈楊妃解笑何。"]', '["楼殿層層佳氣多，开元时節好笙歌。","也知道德勝堯舜，爭奈楊妃解笑何。"]', '诗', 'shi', '', NULL, '華清宮 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13487697-62e7-4226-ad1a-ff59455bb4f5', '韓信廟', '韓信廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["翦項移秦勢自雄，布衣還是負深功。","寡妻稚女俱堪恨，却把餘杯奠蒯通。"]', '["翦項移秦勢自雄，布衣還是負深功。","寡妻稚女俱堪恨，却把餘杯奠蒯通。"]', '诗', 'shi', '', NULL, '韓信廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc76e677-8144-4471-95d6-b962c366bbe1', '韋公子', '韋公子', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["擊柱狂歌慘別顏，百年人事夢魂閒。","李將軍自嘉聲在，不得封侯亦自閑。"]', '["擊柱狂歌慘別顏，百年人事梦魂閒。","李將軍自嘉声在，不得封侯亦自闲。"]', '诗', 'shi', '', NULL, '韋公子 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358d3aeb-89c8-484c-9d8f-5f07d8e11e02', '望思臺', '望思台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["芳草臺邊魂不歸，野煙喬木弄殘暉。","可憐高祖清平業，留與閑人作是非。"]', '["芳草台邊魂不归，野煙喬木弄殘暉。","可怜高祖清平業，留與闲人作是非。"]', '诗', 'shi', '', NULL, '望思臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdb35d4-c035-4718-a0b9-a370804e514d', '帝幸蜀', '帝幸蜀', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["馬嵬山色翠依依，又見鑾輿幸蜀歸。","泉下阿蠻應有語，這迴休更怨楊妃。"]', '["马嵬山色翠依依，又见鑾輿幸蜀归。","泉下阿蠻應有語，這迴休更怨楊妃。"]', '诗', 'shi', '', NULL, '帝幸蜀 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302ca5d4-da71-404f-ab9f-2753300e5133', '王夷甫', '王夷甫', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["把得閑書坐水濱，讀來前事亦酸辛。","莫言麈尾清譚柄，壞却淳風是此人。"]', '["把得闲书坐水濱，读来前事亦酸辛。","莫言麈尾清譚柄，壞却淳风是此人。"]', '诗', 'shi', '', NULL, '王夷甫 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7119dbe0-b773-4c90-b4e5-28c155631907', '鷺鷥', '鷺鷥', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["斜陽澹澹柳陰陰，風褭寒絲映水深。","不要向人誇素白，也知常有羨魚心。"]', '["斜陽澹澹柳陰陰，风褭寒絲映水深。","不要向人誇素白，也知常有羨鱼心。"]', '诗', 'shi', '', NULL, '鷺鷥 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcc2b4b-e4ec-4e10-b990-3b20a87f1e7e', '書淮陰侯傳', '书淮陰侯傳', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寒燈挑盡見遺塵，試瀝椒漿合有神。","莫恨高皇不終始，滅秦謀項是何人。"]', '["寒灯挑尽见遺塵，試瀝椒漿合有神。","莫恨高皇不終始，滅秦謀項是何人。"]', '诗', 'shi', '', NULL, '書淮陰侯傳 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8863962-9946-497c-891b-647435ebd726', '青山廟', '青山廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["市簫聲咽跡崎嶇，雪恥酬恩此丈夫。","霸主兩亡時亦異，不知魂魄更無歸。"]', '["市簫声咽跡崎嶇，雪恥酬恩此丈夫。","霸主兩亡时亦異，不知魂魄更無归。"]', '诗', 'shi', '', NULL, '青山廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee3fb5b-ae43-47d0-a10c-16aa3320e16a', '小松', '小松', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["已有清陰逼座隅，愛聲仙客肯過無。","陵遷谷變須高節，莫向人間作大夫。"]', '["已有清陰逼座隅，愛声仙客肯過無。","陵遷谷变須高節，莫向人间作大夫。"]', '诗', 'shi', '', NULL, '小松 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db79e1b-aa48-4759-9a2c-1373f63d7c52', '竹', '竹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["籬外清陰接藥闌，曉風交戛碧琅玕。","子猷死後知音少，粉節霜筠謾歲寒。"]', '["籬外清陰接藥闌，晓风交戛碧琅玕。","子猷死後知音少，粉節霜筠謾歲寒。"]', '诗', 'shi', '', NULL, '竹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079f7f8f-d3a8-4151-95d9-a4064ec5ccc1', '謾天嶺', '謾天嶺', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["西去休言蜀道難，此中危峻已多端。","到頭未會蒼蒼色，爭得禁他兩度謾。"]', '["西去休言蜀道难，此中危峻已多端。","到头未會蒼蒼色，爭得禁他兩度謾。"]', '诗', 'shi', '', NULL, '謾天嶺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43ae73e-8db4-4d73-bd16-b4331e2d3b00', '秋蟲賦', '秋蟲賦', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["物之小兮，迎網而斃。","物之大兮，兼網而逝。","網也者，繩其小而不繩其大。","吾不知爾身之危兮，腹之餒兮。","吁！。"]', '["物之小兮，迎網而斃。","物之大兮，兼網而逝。","網也者，繩其小而不繩其大。","吾不知爾身之危兮，腹之餒兮。","吁！。"]', '诗', 'shi', '', NULL, '秋蟲賦 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf25390e-0c8b-4ccf-996c-3a8a5c4fe4f7', '蟋蟀詩', '蟋蟀诗', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["頑颸斃芳，吹愁夕長。","屑戍有動，歌離弔夢。","如訴如言，緒引虛寬。","周隙伺榻，繁咽夤緣。","范睡蟬老，冠峨緌好。","不冠不緌，爾奚以悲。","蚊蚋有毒，食人肌肉。","蒼蠅多端，黑白偷安。","爾也出處，物兮莫累。","壞舍啼衰，虛堂泣曙。","勿徇諠譁，鼠豈無牙。","勿學萋菲，垣亦有耳。","危條槁飛，抽恨咿咿。","別帳缸冷，柔魂不定。","美人在何，夜影流波。","與子佇立，裴回思多。"]', '["頑颸斃芳，吹愁夕长。","屑戍有动，歌離弔梦。","如訴如言，緒引虛寬。","周隙伺榻，繁咽夤緣。","范睡蟬老，冠峨緌好。","不冠不緌，爾奚以悲。","蚊蚋有毒，食人肌肉。","蒼蠅多端，黑白偷安。","爾也出处，物兮莫累。","壞舍啼衰，虛堂泣曙。","勿徇諠譁，鼠豈無牙。","勿学萋菲，垣亦有耳。","危條槁飞，抽恨咿咿。","別帳缸冷，柔魂不定。","美人在何，夜影流波。","與子佇立，裴回思多。"]', '诗', 'shi', '', NULL, '蟋蟀詩 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cffa133-1dd0-411b-9529-7953920c1aa0', '西川與蔡十九同別子超', '西川與蔡十九同別子超', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["相歡雖則不多時，相別那能不歛眉。","蜀客賦高君解愛，楚宮腰細我還知。","百年恩愛無終始，萬里因緣有夢思。","腸斷門前舊行處，不堪全屬五陵兒。"]', '["相歡雖則不多时，相別那能不歛眉。","蜀客賦高君解愛，楚宮腰細我還知。","百年恩愛無終始，万里因緣有梦思。","腸斷门前旧行处，不堪全屬五陵兒。"]', '诗', 'shi', '', NULL, '西川與蔡十九同別子超 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43580422-ead9-4e06-b4aa-e881b4965287', '龍泉東下却寄孫員外', '龙泉东下却寄孫員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["縠江東下幾多程，每泊孤舟即有情。","山色已隨遊子遠，水紋猶認主人清。","恩如海岳何時報，恨似煙花觸處生。","百尺風帆兩行淚，不堪迴首望崢嶸。"]', '["縠江东下幾多程，每泊孤舟即有情。","山色已隨游子远，水紋猶認主人清。","恩如海岳何时報，恨似煙花觸处生。","百尺风帆兩行泪，不堪迴首望崢嶸。"]', '诗', 'shi', '', NULL, '龍泉東下却寄孫員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f33b24-11f8-4b3b-a125-809932e9101f', '牡丹', '牡丹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["豔多煙重欲開難，紅蘂當心一抹檀。","公子醉歸燈下見，美人朝插鏡中看。","當庭始覺春風貴，帶雨方知國色寒。","日晚更將何所似，太真無力凭闌干。"]', '["豔多煙重欲开难，紅蘂當心一抹檀。","公子醉归灯下见，美人朝插镜中看。","當庭始覺春风貴，带雨方知国色寒。","日晚更將何所似，太真無力凭闌干。"]', '诗', 'shi', '', NULL, '牡丹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067ad4c1-e52d-4048-9eae-9b27c33a6c4b', '巫山高', '巫山高', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["下壓重泉上千仞，香雲結夢西風緊。","縱有精靈得往來，狖軛鼯軒亦顛隕。","嵐光雙雙雷隱隱，愁爲衣裳恨爲鬢。","暮灑朝行何所之，江邊日月情無盡。","珠零冷露丹墮楓，細腰長臉愁滿宮。","人生對面猶異同，況在千巖萬壑中。"]', '["下壓重泉上千仞，香云結梦西风緊。","縱有精靈得往来，狖軛鼯軒亦顛隕。","嵐光雙雙雷隐隐，愁爲衣裳恨爲鬢。","暮灑朝行何所之，江邊日月情無尽。","珠零冷露丹墮楓，細腰长臉愁满宮。","人生对面猶異同，況在千巖万壑中。"]', '诗', 'shi', '', NULL, '巫山高 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('042d20d8-077a-4692-891b-8e236e32fce0', '江南行', '江南行', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江煙濕雨蛟綃軟，漠漠小山眉黛淺。","水國多愁又有情，夜槽壓酒銀船滿。","細絲搖柳凝曉空，吳王臺榭春夢中。","鴛鴦鸂鶒喚不起，平鋪綠水眠東風。","西陵路邊月悄悄，油碧輕車蘇小小。"]', '["江煙濕雨蛟綃軟，漠漠小山眉黛淺。","水国多愁又有情，夜槽壓酒銀船满。","細絲搖柳凝晓空，吳王台榭春梦中。","鴛鴦鸂鶒喚不起，平鋪綠水眠东风。","西陵路邊月悄悄，油碧轻车蘇小小。"]', '诗', 'shi', '', NULL, '江南行 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc86bce2-f842-4643-9372-3e4e82c31add', '空城雀', '空城雀', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雀入官倉中，所食能損幾。","所恨往復頻，官倉乃害爾。","魚網不在天，鳥網不張水。","飲啄要自然，何必空城裏。"]', '["雀入官倉中，所食能損幾。","所恨往复頻，官倉乃害爾。","鱼網不在天，鸟網不張水。","饮啄要自然，何必空城裏。"]', '诗', 'shi', '', NULL, '空城雀 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3589d6f-b2ff-452a-a1eb-3ab22ea94a59', '芳樹', '芳樹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["細蕚慢逐風，暖香閑破鼻。","青帝固有心，時時漏天意。","去年高枝猶墮地，今年低枝已顦顇。","吾所以見造化之權，變通之理。","春夏作頭，秋冬爲尾。","循環反覆無終已，人生長短同一軌。","若使威可以制，力可以止。","則秦皇不肯斂手下沙丘，孟賁不合低頭入蒿里。","伊人強猛猶如此，顧我勞生何足恃。","但顧我開素袍，傾綠蟻。","陶陶兀兀大醉於清宵白晝間，任他上是天，下是地。"]', '["細蕚慢逐风，暖香闲破鼻。","青帝固有心，时时漏天意。","去年高枝猶墮地，今年低枝已顦顇。","吾所以见造化之權，变通之理。","春夏作头，秋冬爲尾。","循环反覆無終已，人生长短同一軌。","若使威可以制，力可以止。","則秦皇不肯斂手下沙丘，孟賁不合低头入蒿里。","伊人強猛猶如此，顧我勞生何足恃。","但顧我开素袍，傾綠蟻。","陶陶兀兀大醉於清宵白晝间，任他上是天，下是地。"]', '诗', 'shi', '', NULL, '芳樹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885da9f9-7098-4858-8130-75764fd2797b', '聽琴', '听琴', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寒雨蕭蕭落井梧，夜深何處怨啼烏？不知一盞臨邛酒，救得相如渴病無。"]', '["寒雨蕭蕭落井梧，夜深何处怨啼烏？不知一盞臨邛酒，救得相如渴病無。"]', '诗', 'shi', '', NULL, '聽琴 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34540fe9-9378-4280-8146-b0e9d421e07a', '大梁見喬詡', '大梁见喬詡', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["湘水春浮岸，淮燈夜滿橋。","六年悲梗斷，兩地各萍漂。","刀筆依三事，篇章奏珥貂。","跡卑甘汩沒，名散稱逍遙。","好寺松爲徑，空江桂作橈。","野香花伴落，缸暖酒和燒。","晉沼尋遊鳳，秦冠竟歎鴞。","骨凡雞犬薄，魂斷蕙蘭招。","悵望添燕琯，蹉跎厭魯瓢。","敗桐方委爨，冤匣正沖霄。","戰代安釐國，封崇孝景朝。","千年非有限，一醉解無聊。","漏永燈花暗，爐紅雪片銷。","久遊家共遠，相對鬢俱凋。","運命從難合，光陰奈不饒。","到頭蓑笠契，兩信釣魚潮。"]', '["湘水春浮岸，淮灯夜满橋。","六年悲梗斷，兩地各萍漂。","刀笔依三事，篇章奏珥貂。","跡卑甘汩沒，名散稱逍遙。","好寺松爲徑，空江桂作橈。","野香花伴落，缸暖酒和燒。","晉沼尋游鳳，秦冠竟歎鴞。","骨凡雞犬薄，魂斷蕙蘭招。","悵望添燕琯，蹉跎厭魯瓢。","敗桐方委爨，冤匣正沖霄。","戰代安釐国，封崇孝景朝。","千年非有限，一醉解無聊。","漏永灯花暗，爐紅雪片銷。","久游家共远，相对鬢俱凋。","運命從难合，光陰奈不饒。","到头蓑笠契，兩信釣鱼潮。"]', '诗', 'shi', '', NULL, '大梁見喬詡 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9a8b2f-3cef-4df4-8767-0df44bf64429', '寄洪正師', '寄洪正師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["寄蹇渾成跡，經年滯杜南。","價輕猶有二，足刖已過三。","雞肋曹公忿，猪肝仲叔慙。","會應謀避地，依約近禪菴。"]', '["寄蹇渾成跡，經年滯杜南。","價轻猶有二，足刖已過三。","雞肋曹公忿，猪肝仲叔慙。","會應謀避地，依約近禪菴。"]', '诗', 'shi', '', NULL, '寄洪正師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d3b5b9-212f-48be-9cbf-f9724e6be9bc', '聖真觀劉真師院十韻', '聖真观劉真師院十韻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["簾下嚴君卜，窗間少室峰。","攝生門已盡，混跡世猶逢。","山藪師王烈，簪纓友戴顒。","魚跳介象鱠，飯吐葛玄蜂。","紫飽垂新椹，黃輕墮小松。","塵埃金谷路，樓閣上陽鐘。","野耗鳶肩寄，仙書鳥爪封。","支牀龜縱老，取箭鶴何慵。","別久曾牽念，閑來肯壓重。","尚餘青竹在，試爲剪成龍。"]', '["簾下嚴君卜，窗间少室峰。","攝生门已尽，混跡世猶逢。","山藪師王烈，簪纓友戴顒。","鱼跳介象鱠，飯吐葛玄蜂。","紫飽垂新椹，黄轻墮小松。","塵埃金谷路，楼閣上陽鐘。","野耗鳶肩寄，仙书鸟爪封。","支牀龟縱老，取箭鹤何慵。","別久曾牽念，闲来肯壓重。","尚餘青竹在，試爲剪成龙。"]', '诗', 'shi', '', NULL, '聖真觀劉真師院十韻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f9cafd-f1ee-466f-9983-d651fbe44ac3', '寄聶尊師', '寄聶尊師', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["欲芟荆棘種交棃，指畫城中日恐遲。","安得紫青磨鏡石，與君閑處看榮衰。"]', '["欲芟荆棘種交棃，指畫城中日恐遲。","安得紫青磨镜石，與君闲处看榮衰。"]', '诗', 'shi', '', NULL, '寄聶尊師 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2ecd97-8029-4a50-ba71-07d6a3509658', '金山僧院', '金山僧院', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["根盤蛟蜃路藤蘿，四面無塵輟棹過。","得似吾師始惆悵，眼前終日有風波。"]', '["根盤蛟蜃路藤蘿，四面無塵輟棹過。","得似吾師始惆悵，眼前終日有风波。"]', '诗', 'shi', '', NULL, '金山僧院 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26848a50-5cfa-42a5-ab77-82e90d4d8262', '酬高崇節', '酬高崇節', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["舊遊雖一夢，別緒忽千般。","敗草湯陵晚，衰槐楚寺寒。","數奇常自愧，時薄欲何干。","猶賴君相勉，慇懃貢禹冠。"]', '["旧游雖一梦，別緒忽千般。","敗草湯陵晚，衰槐楚寺寒。","數奇常自愧，时薄欲何干。","猶賴君相勉，慇懃貢禹冠。"]', '诗', 'shi', '', NULL, '酬高崇節 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6f537b-504b-4eda-b491-cb902117583a', '送汝州李中丞十二韻', '送汝州李中丞十二韻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["羣盜方爲梗，分符奏未寧。","黃巾攻郡邑，白梃掠生靈。","塵土周畿暗，瘡痍汝水腥。","一兇雖剪滅，數縣尚凋零。","理必資寬猛，謀須藉典刑。","與能纔物論，慎選忽天庭。","官品尊臺秩，山河擁福星。","虎知應去境，牛在肯全形。","舊政窮人瘼，新銜展武經。","關防秋草白，城壁晚峰青。","破膽期來復，迷魂想待醒。","魯山行縣後，聊爲奠惟馨。"]', '["羣盜方爲梗，分符奏未寧。","黄巾攻郡邑，白梃掠生靈。","塵土周畿暗，瘡痍汝水腥。","一兇雖剪滅，數縣尚凋零。","理必資寬猛，謀須藉典刑。","與能纔物論，慎選忽天庭。","官品尊台秩，山河擁福星。","虎知應去境，牛在肯全形。","旧政窮人瘼，新銜展武經。","关防秋草白，城壁晚峰青。","破膽期来复，迷魂想待醒。","魯山行縣後，聊爲奠惟馨。"]', '诗', 'shi', '', NULL, '送汝州李中丞十二韻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad1e4c7-e8dd-48cd-9246-a008d173b2b9', '淮南送節度盧端公將命之汴州端公常爲汴州相公從事', '淮南送節度盧端公將命之汴州端公常爲汴州相公從事', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["吹臺高倚圃田東，此去軺車事不同。","珠履舊參蕭相國，綵衣今佐晉司空。","醉離淮甸寒星下，吟指梁園密雪中。","到彼的知宣室語，幾時徵拜黑頭公。"]', '["吹台高倚圃田东，此去軺车事不同。","珠履旧參蕭相国，綵衣今佐晉司空。","醉離淮甸寒星下，吟指梁园密雪中。","到彼的知宣室語，幾时徵拜黑头公。"]', '诗', 'shi', '', NULL, '淮南送節度盧端公將命之汴州端公常爲汴州相公從事 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4b2c1d1-e85e-47ac-8e23-43b780a1e7cf', '送盧端公歸臺盧校書之夏縣', '送盧端公归台盧校书之夏縣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["綿綿隄草拂征輪，龍虎俱辭楚水濱。","只是勝之爲御史，不知梅福是仙人。","地推八米源流盛，才笑三張事業貧。","一種西歸一般達，柏臺霜冷夏城春。"]', '["綿綿隄草拂征輪，龙虎俱辞楚水濱。","只是勝之爲御史，不知梅福是仙人。","地推八米源流盛，才笑三張事業貧。","一種西归一般達，柏台霜冷夏城春。"]', '诗', 'shi', '', NULL, '送盧端公歸臺盧校書之夏縣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4d816f-818e-4209-a74b-ef9f90855b00', '送朗州張員外', '送朗州張員外', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["聖朝綸閣最延才，須牧生民始入來。","鳳藻已期他日用，隼旟應是隔年迴。","旗飄峴首嵐光重，酒奠湘江杜魄哀。","腸斷秦原二三月，好花全爲使君開。"]', '["聖朝綸閣最延才，須牧生民始入来。","鳳藻已期他日用，隼旟應是隔年迴。","旗飄峴首嵐光重，酒奠湘江杜魄哀。","腸斷秦原二三月，好花全爲使君开。"]', '诗', 'shi', '', NULL, '送朗州張員外 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb99ee8-7f00-4972-bd75-c473daccf06b', '淮南送工部盧員外赴闕', '淮南送工部盧員外赴闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["始從豸角曳長裾，又吐雞香奏玉除。","隋邸舊僚推謝掾，漢廷高議得相如。","貴分赤筆升蘭署，榮著緋衣從板輿。","遙想到時秋欲盡，禁城涼冷露槐疎。"]', '["始從豸角曳长裾，又吐雞香奏玉除。","隋邸旧僚推謝掾，漢廷高議得相如。","貴分赤笔升蘭署，榮著緋衣從板輿。","遙想到时秋欲尽，禁城涼冷露槐疎。"]', '诗', 'shi', '', NULL, '淮南送工部盧員外赴闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('427d96ec-b5a2-4e87-9ec8-e34d63c4bde6', '淮南送司勳李郎中赴闕', '淮南送司勳李郎中赴闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["中朝品秩重文章，雙筆依前賜望郎。","五夜星辰歸帝座，半年樽俎奉梁王。","南都水煖蓮分影，北極天寒雁著行。","不必戀恩多感激，過淮應合見徵黃。"]', '["中朝品秩重文章，雙笔依前賜望郎。","五夜星辰归帝座，半年樽俎奉梁王。","南都水煖蓮分影，北極天寒雁著行。","不必戀恩多感激，過淮應合见徵黄。"]', '诗', 'shi', '', NULL, '淮南送司勳李郎中赴闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f46eaf0-0fc6-4ed3-88a6-9300674f4018', '送陸郎中赴闕', '送陸郎中赴闕', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["幕下留連兩月強，爐邊侍史舊焚香。","不關雨露偏垂意，自是鴛鸞合著行。","三署履聲通建禮，九霄星彩映明光。","少瑜鏤管丘遲錦，從此西垣使鳳凰。"]', '["幕下留連兩月強，爐邊侍史旧焚香。","不关雨露偏垂意，自是鴛鸾合著行。","三署履声通建禮，九霄星彩映明光。","少瑜鏤管丘遲錦，從此西垣使鳳凰。"]', '诗', 'shi', '', NULL, '送陸郎中赴闕 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93efeb8f-09d7-493c-b02d-2fffa90bdbcc', '途中送人東遊有寄', '途中送人东游有寄', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["離驂莫惜暫逡巡，君向池陽我入秦。","歲月易拋非曩日，酒桮難得是同人。","路經隋苑橋燈夜，江轉臺城岸草春。","此處故交誰見問，爲言霜鬢壓風塵。"]', '["離驂莫惜暫逡巡，君向池陽我入秦。","歲月易拋非曩日，酒桮难得是同人。","路經隋苑橋灯夜，江轉台城岸草春。","此处故交誰见问，爲言霜鬢壓风塵。"]', '诗', 'shi', '', NULL, '途中送人東遊有寄 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f13e09-e6e1-4b12-9961-56b4277c84c4', '過廢江寧縣', '過廢江寧縣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["縣前水色細鱗鱗，一爲夫君弔水濱。","漫把文章矜後代，可知榮貴是他人。","鶯偷舊韻還成曲，草賴餘吟盡解春。","我亦有心無處說，等閑停棹似迷津。"]', '["縣前水色細鱗鱗，一爲夫君弔水濱。","漫把文章矜後代，可知榮貴是他人。","鶯偷旧韻還成曲，草賴餘吟尽解春。","我亦有心無处说，等闲停棹似迷津。"]', '诗', 'shi', '', NULL, '過廢江寧縣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ec0d0b-9377-4502-a81a-c297be4ffe08', '邊夜', '邊夜', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["光景漂如水，生涯轉似萍。","雁門窮朔路，牛斗故鄉星。","句盡人誰切，歌終淚自零。"]', '["光景漂如水，生涯轉似萍。","雁门窮朔路，牛斗故乡星。","句尽人誰切，歌終泪自零。"]', '诗', 'shi', '', NULL, '邊夜 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c531f4-075b-4cce-a110-1d4af4837f75', '哭張博士太常', '哭張博士太常', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["前輩倏云歿，媿君曾比方。","格卑雖不稱，言重亦難忘。","諫草猶青瑣，悲風已白楊。","只應移理窟，泉下對真長。"]', '["前輩倏云歿，媿君曾比方。","格卑雖不稱，言重亦难忘。","諫草猶青瑣，悲风已白楊。","只應移理窟，泉下对真长。"]', '诗', 'shi', '', NULL, '哭張博士太常 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb2ebff-196f-4916-ab7e-ce273a1cdc2d', '淮口軍葬', '淮口軍葬', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["一陣孤軍不復迴，更無分別只荒堆。","莫言賦分須如此，曾作文皇赤子來。"]', '["一陣孤軍不复迴，更無分別只荒堆。","莫言賦分須如此，曾作文皇赤子来。"]', '诗', 'shi', '', NULL, '淮口軍葬 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f51467-08d8-4ccb-ad66-a9b137ce667f', '燕昭王墓', '燕昭王墓', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["戰國蒼茫難重尋，此中踪跡想知音。","強停別騎山花曉，欲弔遺魂野草深。","浮世近來輕駿骨，高臺何處有黃金？","思量郭隗平生事，不殉昭王是負心。"]', '["戰国蒼茫难重尋，此中踪跡想知音。","強停別騎山花晓，欲弔遺魂野草深。","浮世近来轻駿骨，高台何处有黄金？","思量郭隗平生事，不殉昭王是負心。"]', '诗', 'shi', '', NULL, '燕昭王墓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0718070a-79f8-422f-b0ea-1b8cdeeffbb7', '江南', '江南', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["玉樹歌聲澤國春，纍纍輜重憶亡陳。","垂衣端拱渾閑事，忍把江山乞與人。"]', '["玉樹歌声澤国春，纍纍輜重憶亡陳。","垂衣端拱渾闲事，忍把江山乞與人。"]', '诗', 'shi', '', NULL, '江南 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab288a3-ee47-4a46-8b51-49d4bbb7a512', '江北', '江北', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["廢宮荒苑莫閑愁，成敗終須要徹頭。","一種風流一種死，朝歌爭得似揚州。"]', '["廢宮荒苑莫闲愁，成敗終須要徹头。","一種风流一種死，朝歌爭得似揚州。"]', '诗', 'shi', '', NULL, '江北 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e670d591-68cb-4dd0-bb77-ba8da3019155', '早登新安縣樓', '早登新安縣楼', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["關城樹色齊，往事未全迷。","塞路真人氣，封門壯土泥。","草濃延蝶舞，花密教鶯啼。","若以鳴爲德，鸞皇不及雞。"]', '["关城樹色齊，往事未全迷。","塞路真人氣，封门壯土泥。","草濃延蝶舞，花密教鶯啼。","若以鳴爲德，鸾皇不及雞。"]', '诗', 'shi', '', NULL, '早登新安縣樓 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a605cbe4-ca13-45fd-8159-7b533cdf5d21', '干越亭', '干越亭', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["楚水蕭蕭多病身，強凭危檻送殘春。","高城自有陵兼谷，流水那知越與秦。","岸下藤蘿陰作怪，橋邊蛟蜃夜欺人。","琵琶洲遠江村闊，迴首征途淚滿巾。"]', '["楚水蕭蕭多病身，強凭危檻送殘春。","高城自有陵兼谷，流水那知越與秦。","岸下藤蘿陰作怪，橋邊蛟蜃夜欺人。","琵琶洲远江村闊，迴首征途泪满巾。"]', '诗', 'shi', '', NULL, '干越亭 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('762dfcac-43d0-4cf0-b868-484c053623f6', '南園題', '南园題', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["搏擊路終迷，南園且灌畦。","敢言逃俗態，自是樂幽棲。","葉長春松闊，科圓早薤齊。","雨霑虛檻冷，雪壓遠山低。","竹好還成徑，桃夭亦有蹊。","小窗奔野馬，閑甕養醯雞。","水石心逾切，煙霄分已暌。","病憐王猛畚，愚笑隗囂泥。","澤國潮平岸，江村柳覆堤。","到頭乘興是，誰手好提攜。"]', '["搏擊路終迷，南园且灌畦。","敢言逃俗態，自是乐幽棲。","葉长春松闊，科圓早薤齊。","雨霑虛檻冷，雪壓远山低。","竹好還成徑，桃夭亦有蹊。","小窗奔野马，闲甕養醯雞。","水石心逾切，煙霄分已暌。","病怜王猛畚，愚笑隗囂泥。","澤国潮平岸，江村柳覆堤。","到头乘兴是，誰手好提携。"]', '诗', 'shi', '', NULL, '南園題 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503cd816-6f8b-4371-b0d8-06236e2d5a5e', '人日新安道中見梅花', '人日新安道中见梅花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["長途酒醒臘春寒，嫩蘂香英撲馬鞍。","不上壽陽公主面，憐君開得却無端。"]', '["长途酒醒臘春寒，嫩蘂香英撲马鞍。","不上壽陽公主面，怜君开得却無端。"]', '诗', 'shi', '', NULL, '人日新安道中見梅花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42fead9-4e26-4ccc-a874-7147b82fdebb', '許由廟', '許由廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["高挂風瓢濯漢濱，土階三尺愧清塵。","可憐比屋堪封日，若到人間是衆人。"]', '["高挂风瓢濯漢濱，土階三尺愧清塵。","可怜比屋堪封日，若到人间是衆人。"]', '诗', 'shi', '', NULL, '許由廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca3dc32-2bb1-490a-ad00-87392746a58f', '題段太尉廟', '題段太尉廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["近甸蒙塵日，南梁反正年。","飄流茂陵椀，零落太官椽。","建纛非降楚，披圖異錄燕。","堪嗟侍中血，不及御衣前。"]', '["近甸蒙塵日，南梁反正年。","飄流茂陵椀，零落太官椽。","建纛非降楚，披圖異錄燕。","堪嗟侍中血，不及御衣前。"]', '诗', 'shi', '', NULL, '題段太尉廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42fb4b55-ff70-47e7-b16d-6a783f01ed66', '湘妃廟', '湘妃廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["劉表荒碑斷水濱，廟前幽草閉殘春。","已將怨淚流斑竹，又感悲風入白蘋。","八族未來誰北拱，四兇猶在莫南巡。","九峰相似堪疑處，望見蒼梧不見人。"]', '["劉表荒碑斷水濱，廟前幽草閉殘春。","已將怨泪流斑竹，又感悲风入白蘋。","八族未来誰北拱，四兇猶在莫南巡。","九峰相似堪疑处，望见蒼梧不见人。"]', '诗', 'shi', '', NULL, '湘妃廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7bdd4f4-fd6a-45d4-8fdb-5ae21cb3097b', '八駿圖', '八駿圖', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["穆滿當年物外程，電腰風脚一何輕。","如今縱有驊騮在，不得長鞭不肯行。"]', '["穆满當年物外程，電腰风脚一何轻。","如今縱有驊騮在，不得长鞭不肯行。"]', '诗', 'shi', '', NULL, '八駿圖 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34af532-0492-452a-bd0a-22cff9b13212', '庭花', '庭花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["昨日芳豔濃，開尊幾同醉。","今朝風雨惡，惆悵人生事。","南威病不起，西子老兼至。","向晚寂無人，相偎墮紅淚。"]', '["昨日芳豔濃，开尊幾同醉。","今朝风雨惡，惆悵人生事。","南威病不起，西子老兼至。","向晚寂無人，相偎墮紅泪。"]', '诗', 'shi', '', NULL, '庭花 羅隱 shi');
